internal static partial class CheckCandidateArenaLifecycle
{
    static string CareerRefinerySnapshot(GameState p){return Convert.ToString(Sql(@"SELECT json_build_object('career',@career::json,'refinery',(SELECT json_agg(a ORDER BY a.uid,a.iditemadding) FROM itemadding a JOIN items i ON i.uid=a.uid WHERE i.entityid=@uid AND a.addingtype=1))::text","career",CareerSkySnapshot(p),"uid",(long)CareerUid));}
    static byte[] CareerRefinePacket(uint target,uint material){
        var packet=new byte[24];Revora.Network.Writer.WriteUInt16(16,0,packet);Revora.Network.Writer.WriteUInt16(2076,2,packet);
        Revora.Network.Writer.WriteUInt32(target,8,packet);Revora.Network.Writer.WriteUInt32(material,12,packet);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,16,packet);return packet;
    }
    static void CareerRefineryJourney(bool reload){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();p.Quests=new Quests(p);p.Quests.Load();
        if((bool)Sql("SELECT to_regclass('revora_career_refinery_probe') IS NULL")){
            Require(!reload && (bool)Sql("SELECT done FROM revora_career_sky_probe") && CareerSkySnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_sky_probe")));
            Sql("CREATE TABLE revora_career_refinery_probe(step int NOT NULL,snapshot text);INSERT INTO revora_career_refinery_probe VALUES(0,@snapshot)","snapshot",CareerRefinerySnapshot(p));
        }
        Require(CareerRefinerySnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_refinery_probe")));
        int step=Convert.ToInt32(Sql("SELECT step FROM revora_career_refinery_probe"));
        if(!reload)for(int index=step;index<2;index++){
            uint type=index==0?3004140u:3004163u;var material=p.Inventory.Objects.Single(i=>i.ID==type);var info=Kernel.DatabaseRefinery[type];
            var target=p.Equipment.GetItems().Single(i=>i.Position<20 && i.Bound && (bool)Call(Feature("RefineryProgress"),"Fits",i,info));
            Require(material.Bound && material.StackSize==1 && target.RefineItem==0);int count=p.Inventory.Objects.Count();ulong silver=p.Entity.Money;uint cps=p.Entity.ConquerPoints;
            // A real incompatible material must preserve every owned item and receipt.
            var incompatible=p.Inventory.Objects.Single(i=>i.ID==724424);string before=CareerRefinerySnapshot(p);
            Purification.Process(CareerRefinePacket(target.UID,incompatible.UID),p);Require(before==CareerRefinerySnapshot(p));
            var packet=CareerRefinePacket(target.UID,material.UID);Purification.Process(packet,p);
            Require(p.Action==2 && !p.Inventory.ContainsUID(material.UID) && p.Inventory.Objects.Count()==count-1 && target.RefineItem==type && target.ExtraEffect.EffectLevel==6 && target.ExtraEffect.EffectPercent==info.Percent && target.ExtraEffect.EffectDuration==14*86400);
            Require(p.Entity.Money==silver && p.Entity.ConquerPoints==cps);
            string after=CareerRefinerySnapshot(p);Purification.Process(packet,p);Require(after==CareerRefinerySnapshot(p));
            Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_refinery_probe SET step=@step,snapshot=@snapshot","step",index+1,"snapshot",CareerRefinerySnapshot(p));
            Console.WriteLine("[career-refinery] applied="+type+" target="+target.UID+" replay-refused");
        }
        Require(Convert.ToInt32(Sql("SELECT step FROM revora_career_refinery_probe"))==2);
        Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=10431 AND source='refinery-apply'","uid",(long)CareerUid)==1);
        foreach(uint type in new uint[]{3004140,3004163}){var item=p.Equipment.GetItems().Single(i=>i.RefineItem==type);Require(item.Bound && item.ExtraEffect.EffectID==type && item.ExtraEffect.EffectLevel==6 && item.ExtraEffect.EffectDuration==14*86400);}
        Require(CareerRefinerySnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_refinery_probe")));
        Console.WriteLine("[career-process] career-refinery-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career refinery did not close.");
    }
    static string CareerSnakeSnapshot(GameState p){return Convert.ToString(Sql(@"SELECT json_build_object('career',@career::json,'hunts',(SELECT json_agg(r ORDER BY day) FROM revora_snake_hunts r WHERE uid=@uid),'attempts',(SELECT json_agg(r ORDER BY started_at,id) FROM revora_snake_attempts r WHERE uid=@uid))::text","career",CareerRefinerySnapshot(p),"uid",(long)CareerUid));}
    static void CareerJumpTo(GameState p,ushort tx,ushort ty){
        ushort map=p.Entity.MapID;int width=p.Map.Floor.Bounds.Width,height=p.Map.Floor.Bounds.Height,start=p.Entity.Y*width+p.Entity.X,found=-1;
        var previous=Enumerable.Repeat(-1,width*height).ToArray();var queue=new System.Collections.Generic.Queue<int>();previous[start]=start;queue.Enqueue(start);
        while(queue.Count>0){int node=queue.Dequeue(),x=node%width,y=node/width;if(Kernel.GetDistance((ushort)x,(ushort)y,tx,ty)<=3){found=node;break;}
            for(int nx=Math.Max(1,x-17);nx<Math.Min(width,x+18);nx++)for(int ny=Math.Max(1,y-17);ny<Math.Min(height,y+18);ny++){
                int next=ny*width+nx;if(previous[next]>=0 || !p.Map.Floor[nx,ny,MapObjectType.Player] || Kernel.GetDistance((ushort)x,(ushort)y,(ushort)nx,(ushort)ny)>17)continue;previous[next]=node;queue.Enqueue(next);}}
        Require(found>=0);var route=new System.Collections.Generic.Stack<int>();for(int node=found;node!=start;node=previous[node])route.Push(node);int jumps=0;
        foreach(int node in route){System.Threading.Thread.Sleep(1200);ushort x=(ushort)(node%width),y=(ushort)(node/width);
            var packet=new Data(true){UID=p.Entity.UID,ID=Data.Jump,wParam1=p.Entity.X,wParam2=p.Entity.Y,Xt1=x,Yt1=y,TimeStamp=Time32.Now}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,packet.Length-8,packet);Data.Process(packet,p);
            Require(p.Action==2 && p.Entity.MapID==map && p.Entity.X==x && p.Entity.Y==y);jumps++;}
        Console.WriteLine("[career-snake] accepted-jumps="+jumps);
    }
    static void CareerSnakeJourney(string phase){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();p.Quests=new Quests(p);p.Quests.Load();
        var feature=Feature("SnakeIslandsQuest");var oldClock=feature.GetField("Clock",Hidden).GetValue(null);feature.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>new DateTime(2026,10,3,20,0,0,DateTimeKind.Utc)));
        try{
            if(phase.EndsWith("victory")){
                Require(p.Entity.MapID==1002);
                bool prepared=CareerRefinerySnapshot(p)!=Convert.ToString(Sql("SELECT snapshot FROM revora_career_refinery_probe"));
                if(prepared)Require((bool)Sql(@"WITH RECURSIVE nodes(side,path,v) AS(
SELECT 0,ARRAY[]::text[],snapshot::jsonb FROM revora_career_refinery_probe UNION ALL SELECT 1,ARRAY[]::text[],@now::jsonb
UNION ALL SELECT n.side,n.path||e.key,CASE WHEN jsonb_typeof(e.value)='string' AND left(e.value#>>'{}',1)='{' THEN (e.value#>>'{}')::jsonb ELSE e.value END FROM nodes n CROSS JOIN LATERAL(
SELECT key,value FROM jsonb_each(CASE WHEN jsonb_typeof(n.v)='object' THEN n.v ELSE '{}'::jsonb END)
UNION ALL SELECT ord::text,value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(n.v)='array' THEN n.v ELSE '[]'::jsonb END) WITH ORDINALITY a(value,ord)) e),
leaves AS(SELECT side,path,v FROM nodes WHERE jsonb_typeof(v) NOT IN('object','array')),
changes AS(SELECT COALESCE(o.path,n.path) path,o.v old,n.v current FROM (SELECT * FROM leaves WHERE side=0) o FULL JOIN (SELECT * FROM leaves WHERE side=1) n USING(path) WHERE o.v IS DISTINCT FROM n.v)
SELECT count(*)=2 AND bool_and(path[array_length(path,1)]='warehouse' AND old='0'::jsonb AND current='8'::jsonb) FROM changes","now",CareerRefinerySnapshot(p)));
                if(!prepared){
                var npc=p.Map.Npcs[8];p.Entity.X=npc.X;p.Entity.Y=(ushort)(npc.Y+1);var stored=p.Inventory.Objects.Where(i=>i.ID/1000>=410 && i.ID/1000<=580).Take(2).ToArray();Require(stored.Length==2);
                foreach(var item in stored){var packet=new byte[172];Revora.Network.Writer.WriteUInt16(164,0,packet);Revora.Network.Writer.WriteUInt16(1102,2,packet);Revora.Network.Writer.WriteUInt32(8,4,packet);packet[12]=1;packet[13]=10;Revora.Network.Writer.WriteUInt32(item.UID,18,packet);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,164,packet);Warehouse.Process(packet,p);Require(!p.Inventory.ContainsUID(item.UID));}
                }
                Require(p.Inventory.Count==36);var scrollShop=ShopFile.Shops.Values.First(v=>v.MoneyType==ShopFile.MoneyType.Gold && v.Items.Contains(1060020) && v.Items.Contains(1060024) && p.Map.Npcs.ContainsKey(v.UID));CareerSilverBuy(p,1060020,scrollShop.UID);System.Threading.Thread.Sleep(1100);CareerSilverBuy(p,1060024,scrollShop.UID);
                ItemHandler.UseItem(p.Inventory.Objects.Single(i=>i.ID==1060024),p);Require(p.Entity.MapID==1015 && p.Inventory.Count==37);
                HeartTalk(p,30115,1);Require(p.Entity.MapID==1063);var boss=p.Map.Entities.Values.First(e=>e.MonsterInfo!=null && e.MonsterInfo.ID==3102 && !e.Dead);
                CareerJumpTo(p,boss.X,boss.Y);p.Screen.Add(boss);int shots=0;
                while(!boss.Dead && shots<2000){p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=boss.UID,X=boss.X,Y=boss.Y,AttackType=Attack.Ranged},p);shots++;}
                Require(boss.Dead && !p.Entity.Dead && p.Action==2);Console.WriteLine("[career-snake] normal-ranged-shots="+shots);
                Require((long)Sql("SELECT count(*) FROM revora_snake_hunts WHERE uid=@uid AND state='victory' AND NOT entered AND cardinality(rewards)=0","uid",(long)CareerUid)==1);
                Require(EntityTable.SaveEntity(p));Sql("CREATE TABLE revora_career_snake_probe(done boolean NOT NULL,snapshot text);INSERT INTO revora_career_snake_probe VALUES(false,@snapshot)","snapshot",CareerSnakeSnapshot(p));
                Console.WriteLine("[career-process] career-snake-victory-passed");Console.Out.Flush();Environment.Exit(0);return;
            }
            Require(CareerSnakeSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_snake_probe")));
            if(phase.EndsWith("claim")){
                Call(feature,"OnLogin",p);Require(p.Entity.MapID==1015);HeartTalk(p,30115,3);Require(p.Inventory.Count==40);
                Require((long)Sql("SELECT count(*) FROM revora_snake_hunts r JOIN items i ON i.uid=ANY(r.rewards) WHERE r.uid=@uid AND r.state='claimed' AND i.entityid=r.uid AND i.bound=1 AND i.id IN(1088001,4030101)","uid",(long)CareerUid)==3);
                string after=CareerSnakeSnapshot(p);HeartTalk(p,30115,3);HeartTalk(p,30115,1);Require(after==CareerSnakeSnapshot(p) && p.Entity.MapID==1015);
                ItemHandler.UseItem(p.Inventory.Objects.Single(i=>i.ID==1060020),p);Require(p.Entity.MapID==1002 && p.Inventory.Count==39);Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_snake_probe SET done=true,snapshot=@snapshot","snapshot",CareerSnakeSnapshot(p));
            }
            Require((bool)Sql("SELECT done FROM revora_career_snake_probe") && CareerSnakeSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_snake_probe")));
            Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=11018 AND source='snake-islands-v1'","uid",(long)CareerUid)==1);
        }finally{feature.GetField("Clock",Hidden).SetValue(null,oldClock);}
        Console.WriteLine("[career-process] "+phase+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career Snake Islands did not close.");
    }
    static string CareerSoulsSnapshot(GameState p){return Convert.ToString(Sql(@"SELECT json_build_object('career',@career::json,'chi',(SELECT points FROM chi WHERE uid=@uid),'study',(SELECT studypoints FROM entities WHERE uid=@uid),'jades',(SELECT json_agg(r ORDER BY used_at,id) FROM revora_dis_jade_uses r WHERE uid=@uid),'souls',(SELECT json_agg(r ORDER BY day) FROM revora_soul_runs r WHERE uid=@uid))::text","career",CareerSnakeSnapshot(p),"uid",(long)CareerUid));}
    static void CareerSoulsJourney(bool reload){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();p.Quests=new Quests(p);p.Quests.Load();ChiTable.Load(p);
        var feature=Feature("ReleaseSoulsQuest");var oldClock=feature.GetField("Clock",Hidden).GetValue(null);DateTime now=new DateTime(2026,10,4,20,0,0,DateTimeKind.Utc);feature.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
        try{
            if(!reload){
                Require(CareerSnakeSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_snake_probe")) && p.Inventory.Count==39 && p.ChiPoints==0);
                HeartTalk(p,79882,3);Require(p.Entity.MapID==1000);HeartTalk(p,301,1);string before=CareerSoulsSnapshot(p);HeartTalk(p,301,3);Require(before==CareerSoulsSnapshot(p));
                foreach(uint npc in new uint[]{65822,65823,65824}){
                    HeartTalk(p,npc,0);Require(p.Entity.OnCheckGuard);before=CareerSoulsSnapshot(p);now=now.AddSeconds(2);Call(feature,"Tick");Require(before==CareerSoulsSnapshot(p) && p.Entity.OnCheckGuard);
                    now=now.AddSeconds(1);Call(feature,"Tick");Require(!p.Entity.OnCheckGuard);before=CareerSoulsSnapshot(p);HeartTalk(p,npc,0);now=now.AddSeconds(3);Call(feature,"Tick");Require(before==CareerSoulsSnapshot(p));
                }
                Require((bool)Sql("SELECT seen=ARRAY[65822,65823,65824]::bigint[] AND state='active' FROM revora_soul_runs WHERE uid=@uid AND day='20261004'","uid",(long)CareerUid));
                before=CareerSoulsSnapshot(p);HeartTalk(p,301,3);Require(before==CareerSoulsSnapshot(p));
                var jades=p.Inventory.Objects.Where(i=>i.ID==3008059).ToArray();Require(jades.Length==2 && jades.All(i=>i.StackSize==1));
                foreach(var jade in jades){uint chi=p.ChiPoints;ItemHandler.UseItem(jade,p);Require(p.Action==2 && p.ChiPoints==chi+300 && !p.Inventory.ContainsUID(jade.UID));before=CareerSoulsSnapshot(p);ItemHandler.UseItem(jade,p);Require(before==CareerSoulsSnapshot(p));}
                Require(p.Inventory.Count==37 && p.ChiPoints==600);uint cp=p.Entity.ConquerPoints,rvp=p.Entity.RevoraPoint;ushort study=p.Entity.SubClasses.StudyPoints;
                HeartTalk(p,301,3);Require(p.Action==2 && p.Inventory.Count==40 && p.Entity.ConquerPoints==cp+Config.DailyQuestCp && p.Entity.RevoraPoint==rvp+Config.DailyQuestRevoraPoints && p.Entity.SubClasses.StudyPoints==study+Config.DailyDesertGuardianStudy);
                Require((bool)Sql(@"SELECT state='complete' AND cardinality(rewards)=3 AND (SELECT count(*) FROM items i WHERE i.uid=ANY(r.rewards) AND i.entityid=r.uid AND i.bound=1 AND i.id IN(722136,r.chi,4030101))=3 FROM revora_soul_runs r WHERE uid=@uid AND day='20261004'","uid",(long)CareerUid));
                before=CareerSoulsSnapshot(p);HeartTalk(p,301,3);HeartTalk(p,301,1);Require(before==CareerSoulsSnapshot(p));
                Require(EntityTable.SaveEntity(p));ChiTable.Save(p);Require(p.Action==2);Sql("CREATE TABLE revora_career_souls_probe(snapshot text);INSERT INTO revora_career_souls_probe VALUES(@snapshot)","snapshot",CareerSoulsSnapshot(p));
            }
            Require(CareerSoulsSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_souls_probe")) && p.ChiPoints==600);
            foreach(int id in new[]{11012,10319})Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id","uid",(long)CareerUid,"id",id)==1);
            if(reload){Call(feature,"OnLogin",p);HeartTalk(p,301,3);Require(CareerSoulsSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_souls_probe")));}
        }finally{feature.GetField("Clock",Hidden).SetValue(null,oldClock);}
        Console.WriteLine("[career-process] career-souls-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career Release Souls did not close.");
    }
    static string CareerQuizSnapshot(GameState p){return Convert.ToString(Sql(@"SELECT json_build_object('career',@career::json,'peer_items',(SELECT json_agg(i ORDER BY uid) FROM items i WHERE entityid=4294907002),'trades',(SELECT json_agg(r ORDER BY settled_at,id) FROM revora_trade_receipts r WHERE left_uid=@uid OR right_uid=@uid),'entries',(SELECT json_agg(r ORDER BY uid) FROM revora_quiz_entries r WHERE run='2026100314'),'answers',(SELECT json_agg(r ORDER BY uid,question) FROM revora_quiz_answers r WHERE run='2026100314'),'results',(SELECT json_agg(r ORDER BY uid) FROM revora_quiz_results r WHERE run='2026100314'),'run',(SELECT row_to_json(r) FROM revora_quiz_runs r WHERE id='2026100314'))::text","career",CareerSoulsSnapshot(p),"uid",(long)CareerUid));}
