    static void CareerQuizJourney(bool reload){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();p.Quests=new Quests(p);p.Quests.Load();ChiTable.Load(p);
        nextUid=4294907002;var peer=Player(Kernel.Maps[1002],true);SkillTable.LoadProficiencies(peer);new TitleStorage().Login(peer);
        var feature=Feature("QuizShowEvent");var oldClock=feature.GetField("Clock",Hidden).GetValue(null);DateTime start=new DateTime(2026,10,3,21,0,0,DateTimeKind.Utc),now=start.AddMinutes(-4);feature.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
        try{
            if(!reload){
                Require(CareerSoulsSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_souls_probe")));
                CareerPortal(p,1002);HeartTalk(p,900000062,0);HeartTalk(peer,900000062,0);
                var weapons=p.Inventory.Objects.Where(i=>i.ID/1000>=410 && i.ID/1000<=580 && (bool)Call(Feature("AtomicTrade"),"Tradable",p,peer,i)).Take(4).ToArray();Require(weapons.Length==4 && peer.Inventory.Count<=33);
                CareerTradePacket(p,Trade.Request,peer.Entity.UID);CareerTradePacket(peer,Trade.Request,p.Entity.UID);Require(p.Trade.InTrade && peer.Trade.InTrade);
                foreach(var item in weapons)CareerTradePacket(p,Trade.AddItem,item.UID);Require(p.Trade.Items.Count==4);
                CareerTradePacket(p,Trade.Accept,0);CareerTradePacket(peer,Trade.Accept,0);Require(!p.Trade.InTrade && !peer.Trade.InTrade && p.Inventory.Count==36);
                foreach(var item in weapons)Require(!p.Inventory.ContainsUID(item.UID) && peer.Inventory.ContainsUID(item.UID));
                HeartTalk(p,900000062,2);HeartTalk(peer,900000062,2);
                var questions=(Array)Feature("QuizQuestionsV1").GetField("All",Hidden).GetValue(null);var deck=(int[])Sql("SELECT deck FROM revora_quiz_runs WHERE id='2026100314'");Require(deck.Length==20);
                for(int index=0;index<20;index++){
                    now=start.AddSeconds(index*30+2);var question=questions.GetValue(deck[index]);int correct=(int)question.GetType().GetField("Correct",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(question);
                    if(index==0){HeartTalk(p,900000062,(byte)(10+correct));Require((long)Sql("SELECT count(*) FROM revora_quiz_answers WHERE run='2026100314'")==0);}
                    HeartTalk(p,900000062,1);HeartTalk(p,900000062,(byte)(10+index*4+correct));string before=CareerQuizSnapshot(p);HeartTalk(p,900000062,(byte)(10+index*4+(correct+1)%4));Require(before==CareerQuizSnapshot(p));
                    now=now.AddSeconds(2);HeartTalk(peer,900000062,1);HeartTalk(peer,900000062,(byte)(10+index*4+(index<10?correct:(correct+1)%4)));
                }
                now=start.AddMinutes(10);feature.GetField("next",Hidden).SetValue(null,DateTime.MinValue);Call(feature,"Tick");
                Require((long)Sql("SELECT count(*) FROM revora_quiz_results WHERE run='2026100314' AND ((uid=@uid AND correct=20 AND answered=20 AND rank=1 AND prize=3) OR (uid=4294907002 AND correct=10 AND answered=20 AND rank=2 AND prize=2))","uid",(long)CareerUid)==2);
                HeartTalk(p,900000062,3);HeartTalk(peer,900000062,3);Require(p.Inventory.Count==40);
                foreach(var player in new[]{p,peer}){
                    Require((long)Sql("SELECT count(*) FROM revora_quiz_results r JOIN items i ON i.uid=ANY(r.rewards) WHERE run='2026100314' AND r.uid=@uid AND r.claimed AND i.entityid=r.uid AND i.bound=1","uid",(long)player.Entity.UID)==(player==p?4:3));
                    var souls=player.Inventory.Objects.Where(i=>i.Bound && ConquerItemInformation.BaseInformations[i.ID].PurificationLevel==7).Select(i=>(long)i.UID).ToArray();Require((long)Sql("SELECT count(*) FROM revora_quiz_results WHERE run='2026100314' AND uid=@uid AND rewards && @souls","uid",(long)player.Entity.UID,"souls",souls)==1);
                }
                string after=CareerQuizSnapshot(p);HeartTalk(p,900000062,3);HeartTalk(peer,900000062,3);Call(feature,"Tick");Require(after==CareerQuizSnapshot(p));Require(EntityTable.SaveEntity(p) && EntityTable.SaveEntity(peer));ChiTable.Save(p);
                Sql("CREATE TABLE revora_career_quiz_probe(snapshot text);INSERT INTO revora_career_quiz_probe VALUES(@snapshot)","snapshot",CareerQuizSnapshot(p));
            }
            Require(CareerQuizSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_quiz_probe")));
            foreach(int id in new[]{10120,11128})Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id AND source='quiz-local-v1'","uid",(long)CareerUid,"id",id)==1);
            if(reload){HeartTalk(p,900000062,3);HeartTalk(peer,900000062,3);Require(CareerQuizSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_quiz_probe")));}
        }finally{feature.GetField("Clock",Hidden).SetValue(null,oldClock);}
        Console.WriteLine("[career-process] career-quiz-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career quiz did not close.");
