    static void RetainedBattlePowerRepair(){
        DateTime now=new DateTime(2035,1,20,6,0,0,DateTimeKind.Utc);GameAssembly.GetType("Revora.TitleRequirements",true).GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));var purse=Feature("GuildWarPurses");lock(purse.GetField("pollGate",Hidden).GetValue(null))purse.GetField("nextPoll",Hidden).SetValue(null,DateTime.MaxValue);
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();ChiTable.Load(p);EntityVariableTable.Load(p);nextUid=4294908901;var peer=Player(Kernel.Maps[1002],true);SkillTable.LoadSpells(peer);SkillTable.LoadProficiencies(peer);SubClassTable.Load(peer.Entity);peer.LoadItemStats();EntityVariableTable.Load(peer);Server.GamePool=new[]{p,peer};foreach(var who in new[]{p,peer}){Revora.Database.KnownPersons.LoadPartner(who);Revora.Database.KnownPersons.LoaderFriends(who);Revora.Database.KnownPersons.LoadMentor(who);}
        p.Quests=new Quests(p);p.Quests.Load();
        Revora.Database.KnownPersons.LoadEnemy(p);if((bool)Sql("SELECT to_regclass('revora_retained_bp_repair_probe') IS NULL")){Require(RetainedRevengeSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_retained_revenge_probe")));Sql("CREATE TABLE revora_retained_bp_repair_probe(snapshot text,done boolean);INSERT INTO revora_retained_bp_repair_probe VALUES(@snapshot,false);CREATE TABLE revora_retained_bp_repair_items(uid bigint PRIMARY KEY,position int);INSERT INTO revora_retained_bp_repair_items SELECT uid,position FROM items WHERE entityid=4294907001 AND position BETWEEN 1 AND 11 AND durability<maximdurability","snapshot",RetainedRevengeSnapshot(p));}
        Require(RetainedRevengeSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_retained_bp_repair_probe")));Action save=()=>{foreach(var who in new[]{p,peer})Require(EntityTable.SaveEntity(who));Call(Feature("QuestInventory"),"Refresh",p);Sql("UPDATE revora_retained_bp_repair_probe SET snapshot=@snapshot","snapshot",RetainedRevengeSnapshot(p));};
        if((bool)Sql("SELECT to_regclass('revora_retained_bp_repair_hold') IS NULL"))Sql("CREATE TABLE revora_retained_bp_repair_hold(uid bigint PRIMARY KEY);INSERT INTO revora_retained_bp_repair_hold SELECT uid FROM items WHERE entityid=4294907001 AND id IN(710011,710012,710013,710014,710015,710635,711336,711600,3004947) AND position=0 AND warehouse=0 AND bound=0");
        Action<GameState,GameState> transfer=(from,to)=>{var ids=from.Inventory.Objects.Where(i=>Convert.ToInt64(Sql("SELECT count(*) FROM revora_retained_bp_repair_hold WHERE uid=@uid","uid",(long)i.UID))==1).Select(i=>i.UID).ToArray();if(ids.Length==0)return;Require(to.Inventory.Count+ids.Length<=40);foreach(var who in new[]{from,to}){who.Entity.Teleport(1002,400,350);HeartTalk(who,8,0);}CareerTradePacket(from,Trade.Request,to.Entity.UID);CareerTradePacket(to,Trade.Request,from.Entity.UID);foreach(uint uid in ids)CareerTradePacket(from,Trade.AddItem,uid);Require(from.Trade.Items.Count==ids.Length);CareerTradePacket(from,Trade.Accept,0);CareerTradePacket(to,Trade.Accept,0);Require(ids.All(uid=>to.Inventory.ContainsUID(uid) && !from.Inventory.ContainsUID(uid)));save();};transfer(p,peer);
        var plans=new System.Collections.Generic.List<Tuple<uint,ushort>>();using(var c=DataHolder.MySqlConnection){c.Open();using(var q=new Npgsql.NpgsqlCommand("SELECT uid,position FROM revora_retained_bp_repair_items ORDER BY position",c))using(var r=q.ExecuteReader())while(r.Read())plans.Add(Tuple.Create((uint)r.GetInt64(0),(ushort)r.GetInt32(1)));}
        foreach(var plan in plans){var item=p.Inventory.Objects.Concat(p.Equipment.GetItems()).Single(i=>i.UID==plan.Item1);if(item.Durability==item.MaximDurability && item.Position==plan.Item2)continue;Require(p.Inventory.Count<40);if(item.Position!=0){ItemHandler.UnequipItem(new ItemUsage(true){dwParam=plan.Item2,Action=ItemUsage.Mode.UnequipItem},p);Require(p.Inventory.ContainsUID(item.UID));save();}if(item.Durability==0){int before=p.Inventory.Objects.Where(i=>i.ID==1088001 && !i.Bound).Sum(i=>(int)i.StackSize);for(int n=0;n<5;n++){CareerBuy(p,1088001);save();}Require(p.Inventory.Objects.Where(i=>i.ID==1088001 && !i.Bound).Sum(i=>(int)i.StackSize)==before+5);}if(item.Durability<item.MaximDurability){ItemHandler.HandleRepair(new ItemUsage(true){UID=item.UID,Action=ItemUsage.Mode.Repair},p);Require(item.Durability==item.MaximDurability);save();}ItemHandler.EquipItem(new ItemUsage(true){UID=item.UID,dwParam=plan.Item2,Action=ItemUsage.Mode.EquipItem},p);Require(p.Equipment.TryGetItem(plan.Item2).UID==item.UID);save();}
        transfer(peer,p);Require(Convert.ToInt64(Sql("SELECT count(*) FROM revora_retained_bp_repair_hold h JOIN items i ON i.uid=h.uid WHERE i.entityid=4294907001"))==9);Require(p.Entity.BattlePower>=300);Sql("UPDATE revora_retained_bp_repair_probe SET done=true");Console.WriteLine("[career-process] career-retained-bp-repair-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Retained BP repairs did not close.");
    }
    static void RetainedTravelConfirm(bool reload){
        DateTime now=new DateTime(2035,1,20,6,0,0,DateTimeKind.Utc);GameAssembly.GetType("Revora.TitleRequirements",true).GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));var purse=Feature("GuildWarPurses");lock(purse.GetField("pollGate",Hidden).GetValue(null))purse.GetField("nextPoll",Hidden).SetValue(null,DateTime.MaxValue);
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();ChiTable.Load(p);EntityVariableTable.Load(p);nextUid=4294908901;var peer=Player(Kernel.Maps[1002],true);SkillTable.LoadSpells(peer);SkillTable.LoadProficiencies(peer);SubClassTable.Load(peer.Entity);peer.LoadItemStats();EntityVariableTable.Load(peer);Server.GamePool=new[]{p,peer};foreach(var who in new[]{p,peer}){Revora.Database.KnownPersons.LoadPartner(who);Revora.Database.KnownPersons.LoaderFriends(who);Revora.Database.KnownPersons.LoadMentor(who);}
        p.Quests=new Quests(p);p.Quests.Load();
        Revora.Database.KnownPersons.LoadEnemy(p);
        if((bool)Sql("SELECT to_regclass('revora_retained_travel_confirm_probe') IS NULL")){
            Require(!reload && (bool)Sql("SELECT done FROM revora_retained_bp_repair_probe")
                && RetainedRevengeSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_retained_bp_repair_probe")));
            Sql("CREATE TABLE revora_retained_travel_confirm_probe(step integer NOT NULL,snapshot text NOT NULL,before_snapshot text NOT NULL);INSERT INTO revora_retained_travel_confirm_probe VALUES(0,@s,@s)","s",RetainedRevengeSnapshot(p));
        }
        Require(RetainedRevengeSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_retained_travel_confirm_probe")));
        int step=(int)Sql("SELECT step FROM revora_retained_travel_confirm_probe");
        Action<int> save=n=>{
            Require(EntityTable.SaveEntity(p));
            string current=RetainedRevengeSnapshot(p);
            Require((bool)Sql(@"WITH RECURSIVE nodes(side,path,v,depth) AS(
SELECT 0,ARRAY[]::text[],before_snapshot::jsonb,0 FROM revora_retained_travel_confirm_probe
UNION ALL SELECT 1,ARRAY[]::text[],@now::jsonb,0
UNION ALL SELECT n.side,n.path||e.key,
CASE WHEN jsonb_typeof(e.value)='string' AND left(e.value#>>'{}',1)='{' THEN (e.value#>>'{}')::jsonb ELSE e.value END,n.depth+1
FROM nodes n CROSS JOIN LATERAL(
SELECT key,value FROM jsonb_each(CASE WHEN jsonb_typeof(n.v)='object' THEN n.v ELSE '{}'::jsonb END)
UNION ALL SELECT ord::text,value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(n.v)='array' THEN n.v ELSE '[]'::jsonb END) WITH ORDINALITY a(value,ord))e
WHERE n.depth<256),flat AS(
SELECT side,jsonb_object_agg(array_to_string(path,'/'),v) AS v FROM nodes
WHERE jsonb_typeof(v) NOT IN('object','array')
AND lower(path[array_length(path,1)]) NOT IN('x','y','mapid','previousmapid','previousx','previousy') GROUP BY side)
