            var scrollShop=ShopFile.Shops.Values.First(v=>v.MoneyType==ShopFile.MoneyType.Gold && v.Items.Contains(1060021) && p.Map.Npcs.ContainsKey(v.UID));CareerSilverBuy(p,1060021,scrollShop.UID);ItemHandler.UseItem(p.Inventory.Objects.First(i=>i.ID==1060021),p);Require(p.Entity.MapID==1000);HeartTalk(p,27837,2);Require(p.Entity.MapID==1927);RetainedSnowLootSave(p,10);}else p.Entity.Teleport(1927,370,366);Call(encounter,"Tick");var active=encounter.GetField("Active",Hidden).GetValue(null);Require(active!=null);var boss=(Entity)active.GetType().GetField("Body",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).GetValue(active);Require(boss.Hitpoints==100000000);Sql("UPDATE revora_retained_snowloot_probe SET run=(SELECT id FROM revora_snow_banshee_runs WHERE state='active')");RetainedSnowLootSave(p,10);
