    static void RetainedUpgrades(bool reload){
        DateTime now=new DateTime(2035,1,6,4,5,0,DateTimeKind.Utc);GameAssembly.GetType("Revora.TitleRequirements",true).GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));var purse=Feature("GuildWarPurses");lock(purse.GetField("pollGate",Hidden).GetValue(null))purse.GetField("nextPoll",Hidden).SetValue(null,DateTime.MaxValue);
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();ChiTable.Load(p);EntityVariableTable.Load(p);Server.GamePool=new[]{p};
        if((bool)Sql("SELECT to_regclass('revora_retained_upgrade_probe') IS NULL")){Require(!reload && RetainedGuardSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_retained_guard_probe")));Sql("CREATE TABLE revora_retained_upgrade_probe(step int,snapshot text,target bigint);INSERT INTO revora_retained_upgrade_probe VALUES(0,@snapshot,0)","snapshot",RetainedUpgradeSnapshot(p));}
        Require(RetainedUpgradeSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_retained_upgrade_probe")));int step=(int)Sql("SELECT step FROM revora_retained_upgrade_probe");var upgrades=Feature("EquipmentUpgrades");upgrades.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
        if(!reload){
            if(step==0){
                var catalog=ConquerItemInformation.BaseInformations;uint type=ShopFile.Shops[1].Items.Where(id=>catalog.ContainsKey(id) && id%10<6 && id/1000!=562 && catalog[id].Level>=15 && catalog[id].Level<50 && catalog[id].GoldWorth>0 && catalog.ContainsKey(id-id%10+6)).OrderBy(id=>id).First();
                var old=p.Inventory.Objects.Select(i=>i.UID).ToArray();ulong silver=p.Entity.Money;var npc=p.Map.Npcs[1];p.Entity.X=npc.X;p.Entity.Y=(ushort)(npc.Y+2);var frame=new ItemUsage(true){UID=1,dwParam=type,dwExtraInfo=1,Action=ItemUsage.Mode.BuyFromNPC}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,frame.Length-8,frame);ItemUsage.Process(frame,p);var bought=p.Inventory.Objects.Single(i=>!old.Contains(i.UID) && i.ID==type);Require(p.Entity.Money==silver-catalog[type].GoldWorth && bought.SocketOne==0 && bought.SocketTwo==0);Sql("UPDATE revora_retained_upgrade_probe SET target=@target","target",(long)bought.UID);RetainedUpgradeSave(p,1);step=1;
            }
            uint target=Convert.ToUInt32(Sql("SELECT target FROM revora_retained_upgrade_probe"));var item=p.Inventory.Objects.Single(i=>i.UID==target);
            // Forty paid failed quality attempts earn both sockets without supplying socket progress.
            while(step<=40){
                CareerBuy(p,1088000);var material=p.Inventory.Objects.First(i=>i.ID==1088000 && !i.Bound);ushort stack=material.StackSize;uint materialUid=material.UID;now=now.AddSeconds(2);upgrades.GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>max-1));long receipts=(long)Sql("SELECT count(*) FROM revora_equipment_upgrades WHERE uid=@uid","uid",(long)CareerUid);uint beforeType=item.ID;
                RetainedUpgradeUsage(p,target,materialUid,ItemUsage.Mode.DragonBallUpgrade);Require(item.ID==beforeType && item.Durability<item.MaximDurability && (long)Sql("SELECT count(*) FROM revora_equipment_upgrades WHERE uid=@uid","uid",(long)CareerUid)==receipts+1);Require(stack==1?!p.Inventory.ContainsUID(materialUid):material.StackSize==stack-1);
                string paid=RetainedUpgradeSnapshot(p);RetainedUpgradeUsage(p,target,materialUid,ItemUsage.Mode.DragonBallUpgrade);Require(paid==RetainedUpgradeSnapshot(p));ulong silver=p.Entity.Money;RetainedUpgradeUsage(p,target,0,ItemUsage.Mode.Repair);Require(item.Durability==item.MaximDurability && p.Entity.Money<silver);RetainedUpgradeSave(p,++step);
            }
            Require(item.SocketOne!=0 && item.SocketTwo!=0);
            while(step<45){
                bool meteor=step==41 || step==42;CareerBuy(p,meteor?1088001u:1088000u);var material=p.Inventory.Objects.First(i=>i.ID==(meteor?1088001u:1088000u) && !i.Bound);now=now.AddSeconds(2);bool success=step!=41;upgrades.GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>success?0:max-1));uint before=item.ID;long count=(long)Sql("SELECT count(*) FROM revora_equipment_upgrades WHERE uid=@uid","uid",(long)CareerUid);
                if(step==44){var frame=new byte[28];Revora.Network.Writer.WriteUInt16(20,0,frame);Revora.Network.Writer.WriteUInt16(2036,2,frame);frame[4]=6;frame[5]=3;Revora.Network.Writer.WriteUInt32(target,8,frame);Revora.Network.Writer.WriteUInt32(1,12,frame);Revora.Network.Writer.WriteUInt32(material.UID,16,frame);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,20,frame);Revora.Network.PacketHandler.HandlePacket(frame,p);}else RetainedUpgradeUsage(p,target,material.UID,meteor?ItemUsage.Mode.MeteorUpgrade:ItemUsage.Mode.DragonBallUpgrade);
                Require((item.ID!=before)==success && (long)Sql("SELECT count(*) FROM revora_equipment_upgrades WHERE uid=@uid","uid",(long)CareerUid)==count+1);if(!success)RetainedUpgradeUsage(p,target,0,ItemUsage.Mode.Repair);Require(item.Durability==item.MaximDurability);RetainedUpgradeSave(p,++step);
            }
        }else {Require(step==45);uint target=Convert.ToUInt32(Sql("SELECT target FROM revora_retained_upgrade_probe"));uint spent=Convert.ToUInt32(Sql("SELECT m.item_uid FROM revora_equipment_upgrade_materials m JOIN revora_equipment_upgrades r ON r.id=m.receipt WHERE r.uid=@uid AND m.after_stack=0 AND NOT EXISTS(SELECT 1 FROM items i WHERE i.uid=m.item_uid) ORDER BY r.created_at LIMIT 1","uid",(long)CareerUid));string saved=RetainedUpgradeSnapshot(p);RetainedUpgradeUsage(p,target,spent,ItemUsage.Mode.DragonBallUpgrade);RetainedUpgradeUsage(p,target,0,ItemUsage.Mode.Repair);Require(saved==RetainedUpgradeSnapshot(p));}
        Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id BETWEEN 10420 AND 10426 AND source='equipment-upgrade'","uid",(long)CareerUid)==7);Require(RetainedUpgradeSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_retained_upgrade_probe")));Console.WriteLine("[career-process] career-retained-upgrades-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Retained upgrades process did not close.");
