    static void GrailMakeRoom(GameState p,int target,Action<GameState> checkpoint=null,uint peerUid=4294908801){if(checkpoint==null)checkpoint=GrailCareerSave;nextUid=peerUid;var peer=Player(Kernel.Maps[1002],true);peer.LoadItemStats();Server.GamePool=new[]{p,peer};
