            while(p.Inventory.Count>target){Require(p.Inventory.Count<40 && peer.Inventory.Count<40);
                var available=p.Inventory.Objects.FirstOrDefault(i=>(bool)Call(Feature("AtomicTrade"),"Tradable",p,peer,i));ConquerItem material=null;
                if(available==null){material=p.Inventory.Objects.FirstOrDefault(i=>i.Bound && i.ID>=800000 && i.ID<900000)??p.Inventory.Objects.FirstOrDefault(i=>i.Bound && i.ID==1088001)??p.Inventory.Objects.First(i=>i.Bound && i.ID==723467);
                    Func<ConquerItem,bool> tradable=i=>!i.Bound && i.StackSize==1 && i.Lock==0 && !i.Suspicious && ConquerItemInformation.BaseInformations[i.ID].Type==ConquerItemBaseInformation.ItemType.Dropable;
                    if(!bank.Objects.Any(tradable)){var other=p.Warehouses.First(w=>w.Value.Objects.Any(tradable) && new ushort[]{1000,1002,1011,1020,1015}.Any(map=>Kernel.Maps.ContainsKey(map) && Kernel.Maps[map].Npcs.ContainsKey((uint)w.Key)));bank=other.Value;banker=(uint)other.Key;}
                    var location=new ushort[]{1000,1002,1011,1020,1015}.Select(map=>Kernel.Maps[map]).First(map=>map.Npcs.ContainsKey(banker));var npc=location.Npcs[banker];p.Entity.Teleport(location.ID,npc.X,npc.Y);peer.Entity.Teleport(location.ID,npc.X,npc.Y);
                    available=bank.Objects.Where(tradable).OrderBy(i=>i.UID).First();GrailWarehouse(p,available.UID,2,banker);Require(p.Inventory.ContainsUID(available.UID));}
                uint uid=available.UID;HeartTalk(p,banker,0);HeartTalk(peer,banker,0);CareerTradePacket(p,Trade.Request,peer.Entity.UID);CareerTradePacket(peer,Trade.Request,p.Entity.UID);CareerTradePacket(p,Trade.AddItem,uid);Require(p.Trade.Items.Count==1);CareerTradePacket(p,Trade.Accept,0);CareerTradePacket(peer,Trade.Accept,0);Require(!p.Inventory.ContainsUID(uid) && peer.Inventory.ContainsUID(uid));
                if(material!=null){GrailWarehouse(p,material.UID,1,banker);Require(bank.Objects.Any(i=>i.UID==material.UID));}Require(EntityTable.SaveEntity(peer));checkpoint(p);
            }
            p.Entity.Teleport(1002,317,321);peer.Entity.Teleport(1002,317,321);Require(EntityTable.SaveEntity(peer));checkpoint(p);
        }
