    static void CareerRuneClassPreflight(){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();
        Require(ArsenalCareerSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_arsenal_career_probe")) && Convert.ToInt32(Sql("SELECT stage FROM revora_arsenal_career_probe"))==2);
        string before=ArsenalCareerSnapshot(p);
        var progress=typeof(GameState).Assembly.GetType("Revora.Network.GamePackets.RuneProgress",true);
        var canUse=progress.GetMethod("CanUse",Hidden,null,new[]{typeof(byte),typeof(byte),typeof(byte),typeof(uint)},null);
        var goods=(System.Collections.IEnumerable)Feature("RevoraPointShopSystem").GetField("Runes",Hidden).GetValue(null);
        var catalog=new System.Collections.Generic.List<Tuple<byte,uint,uint>>();foreach(var good in goods){var t=good.GetType();catalog.Add(Tuple.Create((byte)t.GetField("Option").GetValue(good),(uint)t.GetField("Id").GetValue(good),(uint)t.GetField("Price").GetValue(good)));}
        var yellow=p.RunesItem.Values.Where(i=>i.ID/10000==403 && i.ID%100==9 && i.Position>=103 && i.Position<=105).ToArray();Require(yellow.Length==3);
        byte[] schools={11,21,41,51,61,81,71,132,142,161};int[] ids={11312,11313,11316,11317,11318,11319,11320,11315,11314,11321};
        uint rvp=0;int missing=0;
