            var red=catalog.Single(g=>g.Item2/10000==401 && legal(g.Item2));var blue=catalog.Single(g=>g.Item2/10000==402 && legal(g.Item2));
            uint terminal=blue.Item2+26;Require(ConquerItemInformation.BaseInformations.ContainsKey(terminal) && legal(terminal) && yellow.All(i=>legal(i.ID)));
            bool present=(long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id","uid",(long)CareerUid,"id",ids[ix])==1;
            if(!present){missing++;rvp+=red.Item3+blue.Item3;}
