        }
        Require(missing==9 && p.Entity.RevoraPoint>=rvp && p.Entity.Class==45 && p.Entity.Level==140 && p.Entity.Reborn==2);
        Console.WriteLine("[rune-class-budget] missing="+missing+" pair-rvp="+rvp+" owned-rvp="+p.Entity.RevoraPoint+" owned-cp="+p.Entity.ConquerPoints+" bag="+p.Inventory.Count+" offhands="+p.Equipment.GetItems().Count(i=>i.Position==5 || i.Position==25));
        Require(ArsenalCareerSnapshot(p)==before);
