    static void ClanTerritoryMakeRoom(GameState p){
            Require(p.Inventory.Count==40);nextUid=4294908801;var peer=Player(Kernel.Maps[1002],true);peer.LoadItemStats();Server.GamePool=new[]{p,peer};
            lock(p.ItemSyncRoot){
