                Action<uint,byte> warehouse=(uid,action)=>{HeartTalk(p,8,0);var packet=new byte[172];Revora.Network.Writer.WriteUInt16(164,0,packet);Revora.Network.Writer.WriteUInt16(1102,2,packet);Revora.Network.Writer.WriteUInt32(8,4,packet);packet[12]=action;packet[13]=10;Revora.Network.Writer.WriteUInt32(uid,18,packet);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,164,packet);Warehouse.Process(packet,p);};
                trade(p.Inventory.Objects.First(i=>i.ID==1088000 && !i.Bound).UID);var bank=p.Warehouses.First(w=>(uint)w.Key==8).Value;
                while(p.Inventory.Count>35){uint uid=bank.Objects.Where(i=>!i.Bound && i.StackSize==1 && i.ID/1000>=410 && i.ID/1000<=619).OrderBy(i=>i.UID).First().UID;warehouse(uid,2);Require(p.Inventory.ContainsUID(uid));trade(uid);uint stored=p.Inventory.Objects.First(i=>i.Bound && i.ID>=800000 && i.ID<900000).UID;warehouse(stored,1);Require(bank.Objects.Any(i=>i.UID==stored));}
                Require(p.Inventory.Count==35 && EntityTable.SaveEntity(p) && EntityTable.SaveEntity(peer));
            }
    }
