                else if(index>=2){if(p.Inventory.Count==40){ClanTerritoryMakeRoom(p);Sql("UPDATE revora_clan_territory_career_probe SET snapshot=@snapshot","snapshot",ClanTerritorySnapshot(p));}uint type=index==3?1060021u:1060020u+(uint)index;var shop=ShopFile.Shops.Values.First(v=>v.MoneyType==ShopFile.MoneyType.Gold && v.Items.Contains(type) && p.Map.Npcs.ContainsKey(v.UID));var scroll=CareerSilverBuy(p,type,shop.UID);ItemHandler.UseItem(scroll,p);}Require(p.Entity.MapID==cities[index]);
