                p.Entity.X=npc.X;p.Entity.Y=(ushort)(npc.Y+1);foreach(byte action in new byte[]{6,8}){var packet=new byte[148];Revora.Network.Writer.WriteUInt16(140,0,packet);Revora.Network.Writer.WriteUInt16(1313,2,packet);packet[4]=action;Revora.Network.Writer.WriteUInt32(npc.UID,12,packet);System.Text.Encoding.ASCII.GetBytes("TQClient").CopyTo(packet,140);ClanWar.Process(packet,p);}
