            }
        }else{Require(step==6);Require(!(bool)Call(results,"Pay",p));Require(EntityTable.SaveEntity(p));Require(ClanTerritorySnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_clan_territory_career_probe")));}
