        }else Require(PriceCareerSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_price_career_probe")));
        if(start || hunt){
            if(hunt)Require((int)Sql("SELECT stage FROM revora_price_career_probe")==1 && p.Inventory.Objects.Count(i=>i.ID==p.Entity.PriceItemId)==12);
            Feature("DailyHuntDrops").GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>0));int target=start?12:p.Entity.Priceamount;
            while(p.Inventory.Objects.Count(i=>i.ID==p.Entity.PriceItemId)<target){
                var mob=p.Map.Entities.Values.First(m=>m.MonsterInfo!=null && (m.MonsterInfo.ID==7 || m.MonsterInfo.ID==66) && !m.Dead);
                var before=p.Map.FloorItems.Keys.ToArray();EliminationHit(p,mob);
                var drop=p.Map.FloorItems.Values.Single(d=>!before.Contains(d.UID) && d.OwnerUID==p.Entity.UID && d.ItemID==p.Entity.PriceItemId);
                p.Entity.X=drop.X;p.Entity.Y=drop.Y;var loot=new FloorItem(true){UID=drop.UID,Type=FloorItem.Remove}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,loot.Length-8,loot);FloorItem.Process(loot,p);FloorItem.Process(loot,p);Require(p.Inventory.ContainsUID(drop.Item.UID) && p.Action==2);
            }
            Require((long)Sql("SELECT count(*) FROM revora_daily_hunt_pickups WHERE collector=@uid AND item_type=729093","uid",(long)p.Entity.UID)==target);
            Require((long)Sql("SELECT count(*) FROM revora_price_runs WHERE uid=@uid AND day='20270125' AND NOT completed","uid",(long)p.Entity.UID)==1);
        }else if(claim){
            Require((int)Sql("SELECT stage FROM revora_price_career_probe")==2);CareerPortal(p,1002);
            uint cp=p.Entity.ConquerPoints,rp=p.Entity.RevoraPoint;ushort study=p.Entity.SubClasses.StudyPoints;var prior=p.Inventory.Objects.Select(i=>i.UID).ToArray();
            HeartTalk(p,79882,2);HeartTalk(p,79882,11);HeartTalk(p,79882,11);
            Require(p.Action==2 && p.Entity.ConquerPoints==cp+Config.DailyQuestCp && p.Entity.RevoraPoint==rp+Config.DailyQuestRevoraPoints && p.Entity.SubClasses.StudyPoints==study+Config.DailyPriceQuestStudy);
            Require(!p.Inventory.Contains(729093,1) && !p.Inventory.Contains(729087,1));var reward=p.Inventory.Objects.Where(i=>!prior.Contains(i.UID)).ToArray();
            Require(reward.Length==2 && reward.Any(i=>i.ID==Config.DailyQuestChiToken) && reward.Any(i=>i.ID==4030101 && i.Bound && i.StackSize==1));
            Require((long)Sql("SELECT count(*) FROM revora_price_runs WHERE uid=@uid AND day='20270125' AND completed AND rune_uid IS NOT NULL AND soul_uid IS NULL AND skip_fee=0","uid",(long)p.Entity.UID)==1);
        }else{
            Require((int)Sql("SELECT stage FROM revora_price_career_probe")==3);HeartTalk(p,79882,2);HeartTalk(p,79882,11);HeartTalk(p,79882,13);Require(EntityTable.SaveEntity(p));
            Require(PriceCareerSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_price_career_probe")));
        }
        Require(EntityTable.SaveEntity(p));if(start || hunt || claim)Sql("UPDATE revora_price_career_probe SET stage=stage+1,snapshot=@snapshot","snapshot",PriceCareerSnapshot(p));
        Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();Environment.Exit(0);
