    static void CtfStaleReturn(){
        var sync=typeof(CaptureTheFlag).GetField("sync",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(Server.Thread.CTF);
        lock(sync)typeof(CaptureTheFlag).GetField("nextTick",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(Server.Thread.CTF,DateTime.MaxValue);
        Require((int)Sql("SELECT stage FROM revora_ctf_interrupt_probe")==5);
        careerRitesFixture=true;nextUid=4294908701;var old=Player(Kernel.Maps[1002],true);old.LoadItemStats();EntityVariableTable.Load(old);old.Entity.PKMode=Revora.Game.Enums.PKMode.Capture;
        var returns=Feature("CtfResults");lock(old.ItemSyncRoot)Require((bool)Call(returns,"ReserveReturn","ctf-20270116",old));
        nextUid=4294908701;var current=Player(Kernel.Maps[1002],true);current.LoadItemStats();EntityVariableTable.Load(current);Server.GamePool=new[]{current};
        typeof(CaptureTheFlag).GetMethod("Leave",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(Server.Thread.CTF,new object[]{old});
        Require(!(bool)Sql("SELECT requested FROM revora_ctf_returns WHERE uid=4294908701"));
        Require(!(bool)Call(returns,"Return",old,true));Require((bool)Call(returns,"Return",current,true));
        Require(current.Entity.MapID==1002 && current.Entity.X==408 && current.Entity.Y==330 && current.Entity.PKMode==Revora.Game.Enums.PKMode.Capture);
        Require((bool)Sql("SELECT returned FROM revora_ctf_returns WHERE uid=4294908701"));
        Require(DuelInterruptedAssets()==Convert.ToString(Sql("SELECT assets FROM revora_ctf_interrupt_probe")));
        Sql("UPDATE revora_ctf_interrupt_probe SET stage=6");Console.WriteLine("[career-process] career-ctf-stale-passed");Console.Out.Flush();Environment.Exit(0);
    }
