        careerRitesFixture=true;nextUid=4294908701;var p=Player(Kernel.Maps[1002],true);p.LoadItemStats();EntityVariableTable.Load(p);Server.GamePool=new[]{p};var returns=Feature("CtfResults");
        bool recover=phase.EndsWith("reload");Require((int)Sql("SELECT stage FROM revora_ctf_interrupt_probe")== (recover?4:3));
