            Require(p.Entity.MapID==1002 && p.Entity.PKMode==Revora.Game.Enums.PKMode.Capture && (bool)Sql("SELECT returned FROM revora_ctf_returns WHERE uid=4294908701"));
            HeartTalk(p,380,11);Require(p.Entity.MapID==2057 && !(bool)Sql("SELECT returned FROM revora_ctf_returns WHERE uid=4294908701"));Require(EntityTable.SaveEntity(p));
