            Require((bool)Call(returns,"Return",p,true));Require((bool)Sql("SELECT returned FROM revora_ctf_returns WHERE uid=4294908701"));
            Require((long)Sql("SELECT count(*) FROM revora_ctf_runs WHERE run='ctf-20270116' AND state='cancelled' AND winner=0")==1);
            Sql("UPDATE revora_ctf_interrupt_probe SET stage=5");
        }
