        Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();Environment.Exit(0);
    }
    static void CtfInterrupted(string phase){
        bool enter=phase.EndsWith("enter"),recover=phase.EndsWith("recover"),retry=phase.EndsWith("retry");
        // Isolate the explicit login recovery from the autonomous tick while fixture sessions load.
        var ctfSync=typeof(CaptureTheFlag).GetField("sync",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(Server.Thread.CTF);
        lock(ctfSync)typeof(CaptureTheFlag).GetField("nextTick",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(Server.Thread.CTF,DateTime.MaxValue);
        careerRitesFixture=true;var players=new System.Collections.Generic.List<GameState>();
        foreach(uint uid in new uint[]{4294908701,4294908702,4294908703,4294908704}){nextUid=uid;var p=Player(Kernel.Maps[1002],true);p.LoadItemStats();EntityVariableTable.Load(p);players.Add(p);}
        Server.GamePool=players.ToArray();var returns=Feature("CtfResults");
        if(enter){
            Require((bool)Sql("SELECT to_regclass('revora_ctf_interrupt_probe') IS NULL"));
            Sql("CREATE TABLE revora_ctf_interrupt_probe(stage int NOT NULL,assets text NOT NULL);INSERT INTO revora_ctf_interrupt_probe VALUES(0,@assets)","assets",DuelInterruptedAssets());
            var leader=players[0];var guild=new Revora.Game.ConquerStructures.Society.Guild(leader.Entity.Name){ID=50011,Name="CtfReturnProbe"};
            foreach(var p in players){p.Guild=guild;p.Entity.GuildID=(ushort)guild.ID;p.AsMember=new Revora.Game.ConquerStructures.Society.Guild.Member(guild.ID){ID=p.Entity.UID,Name=p.Entity.Name,Level=p.Entity.Level,Class=p.Entity.Class,Rank=p==leader?Revora.Game.Enums.GuildMemberRank.GuildLeader:Revora.Game.Enums.GuildMemberRank.Member};p.Entity.GuildRank=(ushort)p.AsMember.Rank;guild.Members[p.Entity.UID]=p.AsMember;}
            guild.Leader=leader.AsMember;guild.LeaderName=leader.Entity.Name;GuildTable.Create(guild);Kernel.Guilds[guild.ID]=guild;
            var now=new DateTime(2027,1,10,5,0,1,DateTimeKind.Utc);
            var ctf=(CaptureTheFlag)Activator.CreateInstance(typeof(CaptureTheFlag),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{Kernel.Maps[2057],(Func<DateTime>)(()=>now)},null);Server.Thread.CTF=ctf;ctf.Tick();Require(CaptureTheFlag.IsWar);
            for(int i=0;i<players.Count;i++){var p=players[i];p.Entity.PKMode=(Revora.Game.Enums.PKMode)(i%3);HeartTalk(p,380,11);Require(p.Entity.MapID==2057 && p.Entity.PKMode==Revora.Game.Enums.PKMode.Team && EntityTable.SaveEntity(p));}
            Require((long)Sql("SELECT count(*) FROM revora_ctf_returns WHERE run='ctf-20270109' AND NOT returned")==4);
            Require(DuelInterruptedAssets()==Convert.ToString(Sql("SELECT assets FROM revora_ctf_interrupt_probe")));
            Sql("UPDATE revora_ctf_interrupt_probe SET stage=1");
        }else{
            Require((int)Sql("SELECT stage FROM revora_ctf_interrupt_probe")== (recover?1:retry?2:3));
            Require((long)Sql("SELECT count(*) FROM revora_ctf_runs WHERE run='ctf-20270109' AND state='cancelled' AND winner=0")==1);
            if(recover){
                Require((long)Sql("SELECT count(*) FROM revora_ctf_returns WHERE run='ctf-20270109' AND NOT returned")==4);
                Sql("CREATE FUNCTION reject_ctf_return_ack() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.uid=4294908702 AND NEW.returned THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER reject_ctf_return_ack BEFORE UPDATE ON revora_ctf_returns FOR EACH ROW EXECUTE FUNCTION reject_ctf_return_ack()");
            }
            try{for(int i=0;i<players.Count;i++){
                var p=players[i];bool pending=(bool)Sql("SELECT NOT returned FROM revora_ctf_returns WHERE uid=@uid","uid",(long)p.Entity.UID);
                ushort beforeX=p.Entity.X,beforeY=p.Entity.Y;
                bool ok=(bool)Call(returns,"Return",p,true);for(int attempt=0;!ok && !(recover && i==1) && p.Action==2 && attempt<100;attempt++){System.Threading.Thread.Sleep(20);ok=(bool)Call(returns,"Return",p,true);}Console.WriteLine("[ctf-return-probe] index="+i+" pending="+pending+" ok="+ok+" action="+p.Action+" canonical="+(Kernel.GamePool.ContainsKey(p.Entity.UID) && ReferenceEquals(Kernel.GamePool[p.Entity.UID],p))+" loaded="+p.Entity.FullyLoaded+" fenced="+typeof(Entity).GetField("PersistenceRequiresReload",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(p.Entity));Require(ok==!(recover && i==1));
                Require(p.Entity.MapID==1002 && p.Entity.X==(pending?408:beforeX) && p.Entity.Y==(pending?330:beforeY));
                if(pending)Require(p.Entity.PKMode==(Revora.Game.Enums.PKMode)(i%3));
                if(ok){Require((bool)Call(returns,"Return",p,true));HeartTalk(p,380,12);Require(EntityTable.SaveEntity(p));}
            }}finally{if(recover)Sql("DROP TRIGGER reject_ctf_return_ack ON revora_ctf_returns;DROP FUNCTION reject_ctf_return_ack()");}
            Require((long)Sql("SELECT count(*) FROM revora_ctf_returns WHERE run='ctf-20270109' AND returned")== (recover?3:4));
            Require((long)Sql("SELECT count(*) FROM revora_ctf_prizes WHERE run='ctf-20270109'")==0);
            Require(DuelInterruptedAssets()==Convert.ToString(Sql("SELECT assets FROM revora_ctf_interrupt_probe")));
            if(recover || retry)Sql("UPDATE revora_ctf_interrupt_probe SET stage=stage+1");
        }
        Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();Environment.Exit(0);
    }
    static string DuelInterruptedAssets(){return Convert.ToString(Sql(@"SELECT json_build_object('purses',(SELECT json_agg(r ORDER BY uid) FROM (SELECT uid,conquerpoints,revorapoint,money FROM entities WHERE uid BETWEEN 4294908701 AND 4294908704) r),'items',(SELECT json_agg(r ORDER BY uid) FROM items r WHERE entityid BETWEEN 4294908701 AND 4294908704),'vaults',(SELECT json_agg(r ORDER BY entityid) FROM variablevault r WHERE entityid BETWEEN 4294908701 AND 4294908704),'results',(SELECT json_agg(r ORDER BY cycle,place) FROM revora_duel_results r))::text"));}
    static void DuelInterrupted(string phase){
        bool enter=phase.EndsWith("enter"),recover=phase.EndsWith("recover");
        careerRitesFixture=true;
        var players=new System.Collections.Generic.List<GameState>();
        foreach(uint uid in new uint[]{4294908701,4294908702,4294908703,4294908704}){
            nextUid=uid;var p=Player(Kernel.Maps[1002],true);p.LoadItemStats();EntityVariableTable.Load(p);players.Add(p);
        }
        Server.GamePool=players.ToArray();var service=Feature("DuelPitSystem");
        var arena=(Map)service.GetField("EventMap",Hidden).GetValue(null);Require(arena!=null && arena.BaseID==700);
        if(enter){
            Require((bool)Sql("SELECT to_regclass('revora_duel_interrupt_probe') IS NULL"));
            Sql("CREATE TABLE revora_duel_interrupt_probe(stage int NOT NULL,assets text NOT NULL);INSERT INTO revora_duel_interrupt_probe VALUES(0,@assets)","assets",DuelInterruptedAssets());
            service.GetField("CycleStart",Hidden).SetValue(null,DateTime.Now.AddMinutes(1));Revora.Game.Features.DuelPitSystem.Tick();
            for(int i=0;i<players.Count;i++){players[i].Entity.PKMode=(Revora.Game.Enums.PKMode)(i%3);HeartTalk(players[i],900000011,1);}
            Require(((System.Collections.Generic.HashSet<uint>)service.GetField("Registered",Hidden).GetValue(null)).Count==4);
            service.GetField("CycleStart",Hidden).SetValue(null,new DateTime(2026,12,7,11,15,0));Call(service,"StartFight");
            Require((bool)service.GetField("Running",Hidden).GetValue(null) && (int)service.GetField("Round",Hidden).GetValue(null)==0);
            Require((long)Sql("SELECT count(*) FROM revora_duel_admissions WHERE cycle='202612071115' AND NOT ended AND NOT returned")==4);
            Require(players.Count(p=>p.Entity.MapID==arena.ID)==2 && players.Count(p=>p.Entity.MapID==1002)==2);
            foreach(var p in players)Require(EntityTable.SaveEntity(p));
            Require(DuelInterruptedAssets()==Convert.ToString(Sql("SELECT assets FROM revora_duel_interrupt_probe")));
            Sql("UPDATE revora_duel_interrupt_probe SET stage=1");
        }else{
            int stage=(int)Sql("SELECT stage FROM revora_duel_interrupt_probe");
            // The first private run exited at the incorrect all-four-in-arena fixture assertion.
            // Its committed admission is recovered unchanged; queued fighters correctly stay in town.
            Require(recover?(stage==0 || stage==1):stage==2);
            Require(!(bool)service.GetField("Running",Hidden).GetValue(null));
            Require((long)Sql("SELECT count(*) FROM revora_duel_admissions WHERE cycle='202612071115' AND ended")==4);
            if(recover)Require((long)Sql("SELECT count(*) FROM revora_duel_admissions WHERE cycle='202612071115' AND NOT returned")==4);
            for(int i=0;i<players.Count;i++){
                var p=players[i];Revora.Game.Features.DuelPitSystem.OnLogin(p);Revora.Game.Features.DuelPitSystem.OnLogin(p);
                Require(p.Action==2 && p.Entity.MapID==1002);
                Require(p.Entity.X==Revora.Game.Features.DuelPitSystem.TwinCityX && p.Entity.Y==Revora.Game.Features.DuelPitSystem.TwinCityY);
                if(recover)Require(p.Entity.PKMode==(Revora.Game.Enums.PKMode)(i%3));
                Revora.Game.Features.DuelPitSystem.HandleNpc(p,new NpcRequest(true){NpcID=900000011,OptionID=2});
                Require((uint)p[Revora.Game.Features.DuelPitSystem.ClaimKey]==0 && EntityTable.SaveEntity(p));
            }
            Require((long)Sql("SELECT count(*) FROM revora_duel_admissions WHERE cycle='202612071115' AND ended AND returned")==4);
            Require((long)Sql("SELECT count(*) FROM revora_duel_results WHERE cycle='202612071115'")==0);
            Require(DuelInterruptedAssets()==Convert.ToString(Sql("SELECT assets FROM revora_duel_interrupt_probe")));
            if(recover)Sql("UPDATE revora_duel_interrupt_probe SET stage=2");
        }
        Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();Environment.Exit(0);
    }
