                Require(p.Entity.SubClasses.StudyPoints==study+20 && (long)Sql("SELECT count(*) FROM revora_sword_master_runs WHERE uid=@uid AND state='victory' AND item_uid=@item","uid",(long)CareerUid,"item",(long)soul.UID)==1);
                Require((long)Sql("SELECT count(*) FROM revora_sword_master_loot l JOIN revora_sword_master_runs r ON r.id=l.run WHERE r.uid=@uid AND l.collector IS NULL","uid",(long)CareerUid)==3);Console.WriteLine("[career-master] normal-ranged-hits="+hits);
            }else if(loot){
                Require((int)Sql("SELECT stage FROM revora_career_master_probe")==2);Call(rewards,"Tick",true);var drops=p.Map.FloorItems.Values.Where(d=>(bool)Call(rewards,"Managed",d)).ToArray();Require(drops.Length==3);int before=p.Inventory.Count;
                foreach(var drop in drops){p.Entity.X=drop.X;p.Entity.Y=drop.Y;var packet=new FloorItem(true){UID=drop.UID,Type=FloorItem.Remove}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,packet.Length-8,packet);FloorItem.Process(packet,p);FloorItem.Process(packet,p);Require(p.Inventory.ContainsUID(drop.Item.UID));}
                Require(p.Inventory.Count==before+3 && drops.Count(d=>d.Item.Bound && ConquerItemInformation.BaseInformations[d.ItemID].PurificationLevel==7)==1);
            }else{Require((int)Sql("SELECT stage FROM revora_career_master_probe")==3);string before=CareerMasterSnapshot(p);confirm();Call(rewards,"Tick",true);Require(bosses().Length==0 && p.Map.FloorItems.Values.Count(d=>(bool)Call(rewards,"Managed",d))==0 && before==CareerMasterSnapshot(p));}
        }
        Require(EntityTable.SaveEntity(p));if(buy || win || loot){Sql("UPDATE revora_career_master_probe SET stage=stage+1,snapshot=@snapshot","snapshot",CareerMasterSnapshot(p));Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();Environment.Exit(0);return;}
        Console.WriteLine("[career-process] "+phase+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Master process did not close.");
    }
    static string CareerHonorSnapshot(GameState p){return Convert.ToString(Sql(@"SELECT json_build_object('prior',@prior::json,'arena',(SELECT json_agg(r ORDER BY entityid) FROM arena r WHERE entityid IN(4294907001,4294907002)),'teamarena',(SELECT json_agg(r ORDER BY entityid) FROM teamarena r WHERE entityid IN(4294907001,4294907002)),'match',(SELECT row_to_json(r) FROM revora_arena_matches r WHERE id=(SELECT run FROM revora_career_honor_probe)),'rank',(SELECT json_agg(r ORDER BY uid) FROM revora_arena_rank_rewards r WHERE source_run=(SELECT run FROM revora_career_honor_probe)))::text","prior",CareerSnowSnapshot(p)));}
    static void CareerHonor(string phase){
        bool fight=phase.EndsWith("fight"),pay=phase.EndsWith("pay");
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();p.Quests=new Quests(p);p.Quests.Load();ChiTable.Load(p);
        nextUid=4294907002u;var peer=Player(Kernel.Maps[1002],true,1003,true,true);peer.LoadItemStats();Server.GamePool=new[]{p,peer};
        Console.WriteLine("[career-honor] players-loaded");
        DateTime now=new DateTime(2026,12,2,20,0,0,DateTimeKind.Utc);if(!fight)now=now.AddDays(1);
        Feature("ArenaMatchLedger").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
        if(phase.EndsWith("recover")){
            // Repair only fixture metadata after its unfiltered active-run lookup selected an abandoned run.
            // Both completed wins remain untouched; recovery never replays combat or grants a result.
            Require((long)Sql("SELECT count(*) FROM revora_career_honor_probe WHERE stage=0 AND snapshot IS NULL AND honor=0 AND EXISTS(SELECT 1 FROM revora_arena_abandoned a WHERE a.run=revora_career_honor_probe.run)")==1);
            Require((long)Sql("SELECT count(*) FROM revora_arena_matches WHERE day='20261202' AND winner=@uid AND state='finished'","uid",(long)CareerUid)==2 && p.CurrentHonor==0);
            Require((long)Sql("SELECT count(*) FROM revora_arena_result_commits WHERE run='05f9f119-7833-4983-921c-78ca023f55b0'")==1);
            Sql("UPDATE revora_career_honor_probe SET run='05f9f119-7833-4983-921c-78ca023f55b0',stage=1");
            Require(EntityTable.SaveEntity(p) && EntityTable.SaveEntity(peer));Sql("UPDATE revora_career_honor_probe SET snapshot=@snapshot","snapshot",CareerHonorSnapshot(p));
            Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();Environment.Exit(0);return;
        }
        if(fight){
            if((bool)Sql("SELECT to_regclass('revora_career_honor_probe') IS NULL")){
                Require(CareerSnowSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_snow_probe")));
                Sql("CREATE TABLE revora_career_honor_probe(run uuid NOT NULL,honor bigint NOT NULL,stage int NOT NULL,snapshot text)");
            }else{
                // Resume the observed pre-match mirror refusal; never replay a recorded match.
                Require((long)Sql("SELECT count(*) FROM revora_career_honor_probe WHERE stage<>0")==0);
                Require((long)Sql("SELECT count(*) FROM revora_arena_matches WHERE (player1=@uid OR player2=@uid) AND (day='20261202' OR state='active') AND NOT EXISTS(SELECT 1 FROM revora_arena_abandoned a WHERE a.run=revora_arena_matches.id)","uid",(long)CareerUid,"now",now)==0);
            }
            Console.WriteLine("[career-honor] probe-ready");
            p.Entity.Teleport(1002,408,330);peer.Entity.Teleport(1002,410,330);
            Action<GameState,uint,uint> request=(who,dialog,button)=>{var frame=new Qualifier.ArenaSignup{DialogID=dialog,OptionID=button}.BuildPacket();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,frame.Length-8,frame);Revora.Network.PacketHandler.HandlePacket(frame,who);Require(who.Action==2);};
            Console.WriteLine("[career-honor] signup");
            request(p,0,0);request(peer,0,0);Require(Qualifier.PlayerList.ContainsKey(p.Entity.UID) && Qualifier.PlayerList.ContainsKey(peer.Entity.UID));
            Console.WriteLine("[career-honor] matching");
            Qualifier.EngagePlayers();Require(ReferenceEquals(p.ArenaStatistic.PlayWith,peer));request(p,3,1);request(peer,3,1);Qualifier.VerifyAwaitingPeople();
            Console.WriteLine("[career-honor] accepted");
            var group=p.QualifierGroup;Console.WriteLine("[career-honor] group="+(group!=null)+" main-map="+p.Entity.MapID+" peer-map="+peer.Entity.MapID+" main-map-loaded="+(p.Map!=null)+" peer-map-loaded="+(peer.Map!=null));Require(group!=null && ReferenceEquals(peer.QualifierGroup,group) && p.Map!=null && peer.Map!=null && p.Map.ID==peer.Map.ID && p.Map.BaseID==700);
            var run=(Guid)group.GetType().GetField("ParticipationKey",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(group);
            Sql("DELETE FROM revora_career_honor_probe WHERE stage=0 AND EXISTS(SELECT 1 FROM revora_arena_abandoned a WHERE a.run=revora_career_honor_probe.run);INSERT INTO revora_career_honor_probe VALUES(@run,@honor,0,NULL)","run",run,"honor",(long)p.CurrentHonor);
            // Only the pre-fight countdown and attack cooldown are advanced; damage and result use production combat.
            Console.WriteLine("[career-honor] combat");
            group.ImportTime=group.CreateTime=Time32.Now.AddSeconds(-13);p.Attackable=peer.Attackable=true;p.CantAttack=peer.CantAttack=Time32.Now.AddSeconds(-1);int hits=0;
            while(!group.Done && hits++<100){p.Entity.X=peer.Entity.X;p.Entity.Y=(ushort)(peer.Entity.Y+1);p.Screen.Add(peer.Entity);peer.Screen.Add(p.Entity);p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=peer.Entity.UID,X=peer.Entity.X,Y=peer.Entity.Y,AttackType=Attack.Ranged},p);}
            Console.WriteLine("[career-honor] combat-done="+group.Done+" peer-hp="+peer.Entity.Hitpoints+" hits="+hits);Require(group.Done);Qualifier.CheckGroups();Require((long)Sql("SELECT count(*) FROM revora_arena_matches WHERE id=@run AND state='finished' AND winner=@uid","run",run,"uid",(long)CareerUid)==1);
            Require(p.CurrentHonor==Convert.ToUInt32(Sql("SELECT honor FROM revora_career_honor_probe")));Console.WriteLine("[career-honor] normal-combat-hits="+hits);
        }else{
            string loadedHonor=CareerHonorSnapshot(p),savedHonor=Convert.ToString(Sql("SELECT snapshot FROM revora_career_honor_probe"));
            // Startup may seal the completed day before the player claims its ranking award.
            Require(loadedHonor==savedHonor || pay && (bool)Sql("SELECT (@loaded::jsonb - 'rank')=(@saved::jsonb - 'rank') AND NOT EXISTS(SELECT 1 FROM revora_arena_rank_rewards WHERE source_run=(SELECT run FROM revora_career_honor_probe) AND paid_at IS NOT NULL)","loaded",loadedHonor,"saved",savedHonor));
            if(pay){
                Require((int)Sql("SELECT stage FROM revora_career_honor_probe")==1);var ranking=Feature("ArenaRankingSettlement");Call(ranking,"Close","20261202");
                uint before=p.CurrentHonor;Call(ranking,"Pay",p);uint award=Convert.ToUInt32(Sql("SELECT honor FROM revora_arena_rank_rewards WHERE source_run=(SELECT run FROM revora_career_honor_probe) AND uid=@uid","uid",(long)CareerUid));
                Require(award>=8000 && p.CurrentHonor==before+award && p.TeamArenaStatistic.CurrentHonor==p.CurrentHonor);Call(ranking,"Pay",p);Require(p.CurrentHonor==before+award);Console.WriteLine("[career-honor] earned-ranking-honor="+award);
            }else{Require((int)Sql("SELECT stage FROM revora_career_honor_probe")==2);string before=CareerHonorSnapshot(p);Call(Feature("ArenaRankingSettlement"),"Pay",p);Require(before==CareerHonorSnapshot(p));}
        }
        Require(EntityTable.SaveEntity(p) && EntityTable.SaveEntity(peer));
        if(fight || pay){Sql("UPDATE revora_career_honor_probe SET stage=stage+1,snapshot=@snapshot","snapshot",CareerHonorSnapshot(p));Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();Environment.Exit(0);return;}
        Console.WriteLine("[career-process] "+phase+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Honor process did not close.");
    }
