    static void CareerSnow(string phase){
        Require(new[]{"career-snow-checkpoint","career-snow-win","career-snow-loot","career-snow-reload"}.Contains(phase));careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();p.Quests=new Quests(p);p.Quests.Load();ChiTable.Load(p);Server.GamePool=new[]{p};
        var encounter=Feature("SnowBansheeEncounter");var store=Feature("SnowBansheeStore");var rewards=Feature("SnowBansheeRewards");var instance=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
        Func<Entity> body=()=>{var a=encounter.GetField("Active",Hidden).GetValue(null);return a==null?null:(Entity)a.GetType().GetField("Body",instance).GetValue(a);};
        if(phase.EndsWith("checkpoint")){
            Require(CareerTeratoSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_terato_probe")) && p.Inventory.Count<=37);
            Sql("CREATE TABLE revora_career_snow_probe(run uuid NOT NULL,stamp timestamptz NOT NULL,stage int NOT NULL,snapshot text);INSERT INTO revora_career_snow_probe SELECT id,now(),0,NULL FROM revora_snow_banshee_runs WHERE state='active'");Require((long)Sql("SELECT count(*) FROM revora_career_snow_probe")==1);
        }
