        if(!phase.EndsWith("checkpoint"))Require(CareerSnowSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_snow_probe")));
        Action<Entity> hit=mob=>{p.Entity.X=mob.X;p.Entity.Y=(ushort)(mob.Y+1);p.Screen.Add(mob);p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=mob.UID,X=mob.X,Y=mob.Y,AttackType=Attack.Ranged},p);Require(p.Action==2);};
        if(phase.EndsWith("checkpoint")){
            HeartTalk(p,7767,15);HeartTalk(p,7767,16);Require(p.Entity.MapID==1000);HeartTalk(p,27837,2);Require(p.Entity.MapID==1927);
            var boss=body();Require(boss!=null && boss.Hitpoints==100000000);for(int n=0;n<5;n++)hit(boss);Require(boss.Hitpoints>0 && boss.Hitpoints<100000000);
            now=now.AddSeconds(6);Call(encounter,"Tick");Require(boss.Hitpoints==Convert.ToUInt32(Sql("SELECT hp FROM revora_snow_banshee_runs WHERE id=(SELECT run FROM revora_career_snow_probe)")));
            Console.WriteLine("[career-snow] checkpoint-hp="+boss.Hitpoints);
        }else if(phase.EndsWith("win")){
            Require((int)Sql("SELECT stage FROM revora_career_snow_probe")==1);var boss=body();Require(boss!=null && boss.Hitpoints<100000000 && boss.Hitpoints==Convert.ToUInt32(Sql("SELECT hp FROM revora_snow_banshee_runs WHERE id=(SELECT run FROM revora_career_snow_probe)")));
            uint study=p.Entity.SubClasses.StudyPoints;int hits=0;while(!boss.Dead && hits++<15000)hit(boss);Require(boss.Dead);Call(rewards,"Tick",true);
            Require(p.Entity.SubClasses.StudyPoints==study+100 && (long)Sql("SELECT count(*) FROM revora_snow_banshee_loot WHERE run=(SELECT run FROM revora_career_snow_probe) AND collector IS NULL")==3);
            Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=10527","uid",(long)CareerUid)==1);Console.WriteLine("[career-snow] finishing-hits="+hits);
        }else if(phase.EndsWith("loot")){
            Require((int)Sql("SELECT stage FROM revora_career_snow_probe")==2);Call(rewards,"Tick",true);var drops=p.Map.FloorItems.Values.Where(d=>(bool)Call(rewards,"Managed",d)).ToArray();Require(drops.Length==3);int count=p.Inventory.Count;
            foreach(var drop in drops){p.Entity.X=drop.X;p.Entity.Y=drop.Y;var packet=new FloorItem(true){UID=drop.UID,Type=FloorItem.Remove}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,packet.Length-8,packet);FloorItem.Process(packet,p);FloorItem.Process(packet,p);Require(p.Inventory.ContainsUID(drop.Item.UID));}
            Require(p.Inventory.Count==count+3 && drops.Count(d=>d.Item.Bound && ConquerItemInformation.BaseInformations[d.ItemID].PurificationLevel==7)>=1);
        }else Require((int)Sql("SELECT stage FROM revora_career_snow_probe")==3);
        Require(EntityTable.SaveEntity(p));
        if(!phase.EndsWith("reload")){Sql("UPDATE revora_career_snow_probe SET stage=stage+1,snapshot=@snapshot","snapshot",CareerSnowSnapshot(p));Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();Environment.Exit(0);return;}
        string before=CareerSnowSnapshot(p);Call(rewards,"Tick",true);Require(CareerSnowSnapshot(p)==before && p.Map.FloorItems.Values.Count(d=>(bool)Call(rewards,"Managed",d))==0);
        Require((long)Sql("SELECT count(*) FROM revora_snow_banshee_loot WHERE run=(SELECT run FROM revora_career_snow_probe) AND collector=@uid","uid",(long)CareerUid)==3);
        Console.WriteLine("[career-process] "+phase+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Snow process did not close.");
    }
