            Require((long)Sql("SELECT count(*) FROM revora_terato_runs WHERE uid=@uid AND state='active' AND valuable_reward","uid",(long)CareerUid)==1);
            HeartTalk(p,900000127,3);Require(actors().Length==1 && (long)Sql("SELECT count(*) FROM revora_terato_materials m JOIN revora_terato_runs r ON r.id=m.run WHERE r.uid=@uid","uid",(long)CareerUid)==1);
        }else if(phase.EndsWith("win")){
