            p.Entity.X=boss.X;p.Entity.Y=(ushort)(boss.Y+1);p.Screen.Add(boss);int hits=0;while(!boss.Dead && hits++<10000){p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=boss.UID,X=boss.X,Y=boss.Y,AttackType=Attack.Ranged},p);}Require(boss.Dead && p.Action==2);Call(rewards,"Tick",true);
            Require(p.Entity.SubClasses.StudyPoints==study+50 && (long)Sql("SELECT count(*) FROM revora_terato_loot l JOIN revora_terato_runs r ON r.id=l.run WHERE r.uid=@uid AND l.collector IS NULL","uid",(long)CareerUid)==3);
            Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=10526","uid",(long)CareerUid)==1);Console.WriteLine("[career-terato] ranged-hits="+hits);
        }else if(phase.EndsWith("loot")){
