        if(!phase.EndsWith("reload")){Sql("UPDATE revora_career_terato_probe SET stage=stage+1,snapshot=@snapshot","snapshot",CareerTeratoSnapshot(p));Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();Environment.Exit(0);return;}
        string beforeReplay=CareerTeratoSnapshot(p);ushort savedX=p.Entity.X,savedY=p.Entity.Y;HeartTalk(p,900000127,3);Call(rewards,"Tick",true);Require(actors().Length==0 && p.Map.FloorItems.Values.Count(d=>(bool)Call(rewards,"Managed",d))==0);
        Require((long)Sql("SELECT count(*) FROM revora_terato_loot l JOIN revora_terato_runs r ON r.id=l.run JOIN items i ON i.uid=l.item_uid WHERE r.uid=@uid AND l.slot=2 AND l.bound AND i.bound=1","uid",(long)CareerUid)==1);
        p.Entity.X=savedX;p.Entity.Y=savedY;Require(EntityTable.SaveEntity(p) && CareerTeratoSnapshot(p)==beforeReplay);
