        using(var c=DataHolder.MySqlConnection){c.Open();using(var t=c.BeginTransaction()){
            using(var q=new Npgsql.NpgsqlCommand("CREATE TEMP TABLE revora_terato_runs(id uuid,valuable_reward boolean);CREATE TEMP TABLE revora_terato_study(LIKE public.revora_terato_study INCLUDING ALL);CREATE TEMP TABLE revora_terato_loot(LIKE public.revora_terato_loot INCLUDING ALL)",c,t))q.ExecuteNonQuery();
            foreach(bool valuable in new[]{false,true}){Guid run=Guid.NewGuid();using(var q=new Npgsql.NpgsqlCommand("INSERT INTO revora_terato_runs VALUES(@run,@valuable)",c,t)){q.Parameters.AddWithValue("run",run);q.Parameters.AddWithValue("valuable",valuable);q.ExecuteNonQuery();}
                Call(rewards,"Record",c,t,run,CareerUid,new[]{CareerUid});
                using(var q=new Npgsql.NpgsqlCommand("SELECT item_type,bound FROM revora_terato_loot WHERE run=@run AND slot=2",c,t)){q.Parameters.AddWithValue("run",run);using(var r=q.ExecuteReader()){Require(r.Read());uint level=ConquerItemInformation.BaseInformations[(uint)r.GetInt32(0)].PurificationLevel;Require(r.GetBoolean(1)==valuable && (valuable?level==7:level>=1 && level<=6));}}
            }
            t.Rollback();
        }}
