    static void CareerVirtueJourney(string phase){
        Require(new[]{"career-virtue-earn","career-virtue-reload"}.Contains(phase));careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
