    static void TournamentProcess(string phase){
        nextUid=4294908401;var a=Player(Kernel.Maps[1002],true);nextUid=4294908402;var b=Player(Kernel.Maps[1002],true);var players=new[]{a,b};foreach(var p in players)p.LoadItemStats();Server.GamePool=players;
        var eventType=typeof(Revora.Sistemas.Quarantine);var admissions=typeof(Server).Assembly.GetType("Revora.Sistemas.QuarantineAdmissions");var purses=typeof(Server).Assembly.GetType("Revora.Sistemas.QuarantinePurses");
        bool interrupt=phase.EndsWith("interrupt"),recover=phase.EndsWith("recover"),earn=phase.EndsWith("earn");
        if(interrupt){
            foreach(var p in players){Require(p.Entity.MapID==1002 && p.Inventory.Count<38);var choice=ShopFile.Shops.Values.Where(v=>v.MoneyType==ShopFile.MoneyType.Gold && p.Map.Npcs.ContainsKey(v.UID)).SelectMany(v=>v.Items.Where(id=>id/1000==130).Select(id=>new{Shop=v,Info=ConquerItemInformation.BaseInformations[id]})).Where(v=>v.Info.Level<=p.Entity.Level && v.Info.Strength<=p.Entity.Strength && v.Info.Agility<=p.Entity.Agility && v.Info.GoldWorth>0).OrderBy(v=>v.Info.Level).ThenBy(v=>v.Info.GoldWorth).First();var armor=CareerSilverBuy(p,choice.Info.ID,choice.Shop.UID);ItemHandler.EquipItem(new ItemUsage(true){UID=armor.UID,dwParam=3,Action=ItemUsage.Mode.EquipItem},p);Require(p.Equipment.TryGetItem(3)!=null && p.Equipment.TryGetItem(3).UID==armor.UID);p.Entity.PKMode=Enums.PKMode.Capture;p.LoadItemStats();Require(EntityTable.SaveEntity(p));}
            Sql("CREATE TABLE revora_tournament_process_probe(step integer NOT NULL,round_id uuid,baseline text,snapshot text);INSERT INTO revora_tournament_process_probe VALUES(0,NULL,@baseline,NULL)","baseline",InterruptedEventRewards());
        }else if(!recover)Require(TournamentProcessSnapshot()==Convert.ToString(Sql("SELECT snapshot FROM revora_tournament_process_probe")));
        if(interrupt || earn){
            Revora.Sistemas.Quarantine.StartScheduled(new DateTime(2026,10,interrupt?11:12,20,0,0));Require(Revora.Sistemas.Quarantine.Started);Guid round=(Guid)eventType.GetField("roundId",Hidden).GetValue(null);
