    static void InterruptedEvent(string phase){
        string kind=phase.Split('-')[2];bool interrupt=phase.EndsWith("interrupt"),recover=phase.EndsWith("recover");
        Require(kind=="beast" || kind=="wave" || kind=="relic");nextUid=kind=="beast"?4294908301u:4294908401u;
        var players=Enumerable.Range(0,kind=="beast"?1:4).Select(i=>Player(Kernel.Maps[1002],true)).ToArray();foreach(var p in players){p.LoadItemStats();EntityVariableTable.Load(p);}
        var feature=Feature(kind=="beast"?"BeastTrialSystem":kind=="wave"?"WaveDefenseSystem":"RelicRushSystem");uint npc=kind=="beast"?900000009u:kind=="wave"?900000007u:900000005u;
        Sql("CREATE TABLE IF NOT EXISTS revora_event_interruption_probe(kind text PRIMARY KEY,done boolean NOT NULL,snapshot text NOT NULL)");
        if(interrupt){
            Require((long)Sql("SELECT count(*) FROM revora_event_interruption_probe WHERE kind=@kind","kind",kind)==0);
            if(kind=="beast")Require(BeastProcessSnapshot()==Convert.ToString(Sql("SELECT snapshot FROM revora_beast_process_probe")));
            if(kind=="wave")Require(RelicProcessSnapshot()==Convert.ToString(Sql("SELECT snapshot FROM revora_relic_process_probe")));
            Require(InterruptedAdmissionCount(kind,false,false)==0 && InterruptedAdmissionCount(kind,true,false)==0);
            foreach(var p in players){p.Entity.PKMode=Enums.PKMode.Capture;Require(EntityTable.SaveEntity(p));}
            string before=InterruptedEventRewards();DateTime start=DateTime.Now.AddHours(2),now=start.AddMinutes(-4);
            if(kind=="relic"){feature.GetField("CycleStart",Hidden).SetValue(null,start);feature.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));}
            else feature.GetField("CycleStart",Hidden).SetValue(null,DateTime.Now.AddMinutes(1));
            feature.GetMethod("Tick").Invoke(null,null);
            if(kind=="wave"){var leader=players[0];leader.Team=new Revora.Game.ConquerStructures.Team(leader);foreach(var p in players.Skip(1))leader.Team.Add(p);var clerk=Kernel.Maps[1002].Npcs[npc];foreach(var p in players){p.Entity.X=clerk.X;p.Entity.Y=clerk.Y;}HeartTalk(leader,npc,1);}
            else foreach(var p in players)HeartTalk(p,npc,1);
            if(kind=="relic"){now=start;feature.GetMethod("Tick").Invoke(null,null);}
            Require(players.All(p=>p.Entity.MapID!=1002) && InterruptedAdmissionCount(kind,false,false)==players.Length);
            foreach(var p in players)Require(EntityTable.SaveEntity(p));Require(before==InterruptedEventRewards());
            Sql("INSERT INTO revora_event_interruption_probe VALUES(@kind,false,@snapshot)","kind",kind,"snapshot",before);
