    static void RelicProcess(string phase){
        nextUid=4294908401;var players=Enumerable.Range(0,4).Select(i=>Player(Kernel.Maps[1002],true)).ToArray();foreach(var p in players){p.LoadItemStats();EntityVariableTable.Load(p);}
        var feature=Feature("RelicRushSystem");
        if(phase.EndsWith("earn")){
