            Console.WriteLine("[career-process] career-relic-earn-passed");Console.Out.Flush();Environment.Exit(0);return;
        }
        Require(RelicProcessSnapshot()==Convert.ToString(Sql("SELECT snapshot FROM revora_relic_process_probe")));foreach(var p in players){Revora.Game.Features.RelicRushSystem.OnLogin(p);Require(p.Entity.MapID==1002);}
        if(phase.EndsWith("claim")){
            var cps=new uint[]{Config.RelicRushSecondCp,Config.RelicRushThirdCp,Config.RelicRushFirstCp,0};var rvps=new uint[]{Config.RelicRushSecondRevoraPoints,Config.RelicRushThirdRevoraPoints,Config.RelicRushFirstRevoraPoints,0};var golds=new ulong[]{Config.RelicRushSecondGold,Config.RelicRushThirdGold,Config.RelicRushFirstGold,0};
            for(int i=0;i<4;i++){var p=players[i];uint cp=p.Entity.ConquerPoints,rvp=p.Entity.RevoraPoint;ulong gold=p.Entity.Money;var oldIds=p.Inventory.Objects.Select(v=>v.UID).ToArray();HeartTalk(p,900000005,2);
                Require(p.Entity.ConquerPoints==cp+cps[i] && p.Entity.RevoraPoint==rvp+rvps[i] && p.Entity.Money==gold+golds[i]);
                var added=p.Inventory.Objects.Where(v=>!oldIds.Contains(v.UID)).ToArray();Require(added.Length==(i<3?1:0) && added.All(v=>v.Bound && ConquerItemInformation.BaseInformations[v.ID].PurificationLevel==7));
                Require((uint)p[Revora.Game.Features.RelicRushSystem.ClaimKey]==0);string after=RelicProcessSnapshot();HeartTalk(p,900000005,2);Require(after==RelicProcessSnapshot());Require(EntityTable.SaveEntity(p));}
            Require((long)Sql("SELECT count(*) FROM revora_relic_placements WHERE uid BETWEEN 4294908401 AND 4294908404 AND imported")==3);Sql("UPDATE revora_relic_process_probe SET done=true,snapshot=@snapshot","snapshot",RelicProcessSnapshot());
        }
        Require((bool)Sql("SELECT done FROM revora_relic_process_probe"));foreach(var p in players)HeartTalk(p,900000005,2);Require(RelicProcessSnapshot()==Convert.ToString(Sql("SELECT snapshot FROM revora_relic_process_probe")));
        Console.WriteLine("[career-process] "+phase+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Relic process did not close.");
    }
