        }
        Require(CareerExploreSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_hunting_probe")));
        int step=Convert.ToInt32(Sql("SELECT step FROM revora_career_hunting_probe"));
        ushort[] route={1215,1207,1208,1207,1215,1216,1204,1213,1201,1202,1205,1202,1201,1213,1204,1216,1214,1217,1020,1011,1002};
        if(!reload){
            if(step<0){ulong money=p.Entity.Money;long trips=Convert.ToInt64(Sql("SELECT trips FROM revora_adventure_passages WHERE uid=@uid","uid",(long)CareerUid));HeartTalk(p,380,1);Require(p.Entity.MapID==1038);HeartTalk(p,9884,1);Require(p.Action==2 && p.Entity.MapID==1216 && p.Entity.Money==money-1000);
                Require(Convert.ToInt64(Sql("SELECT trips FROM revora_adventure_passages WHERE uid=@uid AND NOT pending AND destination=1216","uid",(long)CareerUid))==trips+1);
                Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_hunting_probe SET step=0,snapshot=@snapshot","snapshot",CareerExploreSnapshot(p));step=0;
