                if(origin==1217){
                    int portalIndex=p.Map.Portals.FindIndex(v=>v.DestinationMapID==route[index]);Require(portalIndex>=0);var portal=p.Map.Portals[portalIndex];bool crossed=false;
                    for(int dx=-3;dx<=3 && !crossed;dx++)for(int dy=-3;dy<=3 && !crossed;dy++){
                        int x=portal.CurrentX+dx,y=portal.CurrentY+dy;if(x<1 || y<1 || !p.Map.Floor[x,y,MapObjectType.Player])continue;
                        bool neighbor=false;for(byte d=0;d<8;d++){int nx=x+Entity.XDir[d],ny=y+Entity.YDir[d];if(nx>0 && ny>0 && p.Map.Floor[nx,ny,MapObjectType.Player] && Kernel.GetDistance(portal.CurrentX,portal.CurrentY,(ushort)nx,(ushort)ny)<=4)neighbor=true;}
                        if(neighbor){AdventureIslandPortal(p,portalIndex,(ushort)x,(ushort)y);crossed=true;}
                    }
                    Require(crossed);
                }else CareerPortal(p,route[index]);
                Require(p.Action==2 && p.Entity.MapID==route[index]);
                Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_hunting_probe SET step=@step,snapshot=@snapshot","step",index+1,"snapshot",CareerExploreSnapshot(p));Console.WriteLine("[career-hunting] "+origin+" -> "+route[index]);
            }
        }
        Require(Convert.ToInt32(Sql("SELECT step FROM revora_career_hunting_probe"))==route.Length && p.Entity.MapID==1002);
        foreach(int id in new[]{10708,10709,10710,10711,10713,10714,10719,10720,10721})Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id AND source='travel-region-v1'","uid",(long)CareerUid,"id",id)==1);
        Require(CareerExploreSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_hunting_probe")));
        Console.WriteLine("[career-process] career-hunting-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Hunting route did not close.");
    }
    static string CareerReturnLocation(){return Convert.ToString(Sql("SELECT json_build_array(mapid,previousmapid,previousx,previousy)::text FROM entities WHERE uid=@uid","uid",(long)CareerUid));}
    static void CareerMarketReturn(bool reload){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
