            Require(p.Entity.MapID==1002);string before=CareerReturnLocation();bool rejected=false;
            Sql("ALTER TABLE entities ADD CONSTRAINT career_market_map_reject CHECK(uid<>4294907001 OR mapid<>1036) NOT VALID");
            try{try{p.Entity.MapID=1036;}catch(Npgsql.PostgresException){rejected=true;}Require(rejected && p.Entity.MapID==1002 && before==CareerReturnLocation());}
            finally{Sql("ALTER TABLE entities DROP CONSTRAINT career_market_map_reject");}
