            Sql("CREATE TABLE revora_career_return_probe(x int NOT NULL,y int NOT NULL,snapshot text);INSERT INTO revora_career_return_probe VALUES(@x,@y,@snapshot)","x",(int)p.Entity.PrevX,"y",(int)p.Entity.PrevY,"snapshot",CareerExploreSnapshot(p));
