        HeartTalk(p,45,1);Require(p.Entity.MapID==1002 && p.Entity.X==x && p.Entity.Y==y);
        Require(CareerExploreSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_return_probe")));
        Require(EntityTable.SaveEntity(p));Console.WriteLine("[career-process] career-return-reload-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Market return did not close.");
    }
    static void CareerCityJourney(bool reload){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();
        if((bool)Sql("SELECT to_regclass('revora_career_city_probe') IS NULL")){
            Require(!reload && CareerExploreSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_explore_probe")));
            Sql("CREATE TABLE revora_career_city_probe(stage int NOT NULL,snapshot text);INSERT INTO revora_career_city_probe VALUES(0,@snapshot)","snapshot",CareerExploreSnapshot(p));
        }
        if(!reload && CareerExploreSnapshot(p)!=Convert.ToString(Sql("SELECT snapshot FROM revora_career_city_probe"))){
            Require((bool)Sql(@"WITH RECURSIVE nodes(side,path,v) AS(
SELECT 0,ARRAY[]::text[],snapshot::jsonb FROM revora_career_city_probe UNION ALL SELECT 1,ARRAY[]::text[],@now::jsonb
UNION ALL SELECT n.side,n.path||e.key,CASE WHEN jsonb_typeof(e.value)='string' AND left(e.value#>>'{}',1)='{' THEN (e.value#>>'{}')::jsonb ELSE e.value END
FROM nodes n CROSS JOIN LATERAL(SELECT key,value FROM jsonb_each(CASE WHEN jsonb_typeof(n.v)='object' THEN n.v ELSE '{}'::jsonb END)
UNION ALL SELECT ord::text,value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(n.v)='array' THEN n.v ELSE '[]'::jsonb END) WITH ORDINALITY a(value,ord)) e),
flat AS(SELECT side,jsonb_object_agg(array_to_string(path,'/'),v) v FROM nodes WHERE jsonb_typeof(v) NOT IN('object','array') AND NOT path && ARRAY['achievements','visits'] GROUP BY side),
records AS(SELECT side,e.value FROM nodes n CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(n.v)='array' AND n.path[array_length(n.path,1)] IN('achievements','visits') THEN n.v ELSE '[]'::jsonb END) e),
added AS(SELECT value FROM records WHERE side=1 EXCEPT SELECT value FROM records WHERE side=0)
SELECT (SELECT stage FROM revora_career_city_probe)=10 AND (SELECT v FROM flat WHERE side=0)=(SELECT v FROM flat WHERE side=1)
AND NOT EXISTS(SELECT value FROM records WHERE side=0 EXCEPT SELECT value FROM records WHERE side=1)
AND (SELECT count(*) FROM added)=2 AND NOT EXISTS(SELECT 1 FROM added WHERE value->>'uid' IS DISTINCT FROM '4294907001' OR value->>'achievement_id' IS DISTINCT FROM '10812' OR NOT COALESCE(value->>'source'='travel-region-v1' OR value->>'map_id'='1036',false))","now",CareerExploreSnapshot(p)));
            Sql("UPDATE revora_career_city_probe SET snapshot=@snapshot","snapshot",CareerExploreSnapshot(p));
        }
        Require(CareerExploreSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_city_probe")));
        int stage=Convert.ToInt32(Sql("SELECT stage FROM revora_career_city_probe"));
        if(!reload){
            for(int index=stage;index<5;index++){
                uint type=(uint)(1060020+index);var shop=ShopFile.Shops.Values.First(v=>v.MoneyType==ShopFile.MoneyType.Gold && v.Items.Contains(type) && p.Map.Npcs.ContainsKey(v.UID));var npc=p.Map.Npcs[shop.UID];p.Entity.X=npc.X;p.Entity.Y=(ushort)(npc.Y+1);
                ulong money=p.Entity.Money;uint price=ConquerItemInformation.BaseInformations[type].GoldWorth;int count=p.Inventory.Objects.Where(v=>v.ID==type).Sum(v=>(int)v.StackSize);
                var frame=new ItemUsage(true){UID=shop.UID,dwParam=type,dwExtraInfo=1,Action=ItemUsage.Mode.BuyFromNPC}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,frame.Length-8,frame);ItemUsage.Process(frame,p);
                Require(p.Action==2 && p.Entity.Money==money-price && p.Inventory.Objects.Where(v=>v.ID==type).Sum(v=>(int)v.StackSize)==count+1);
                Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_city_probe SET stage=@stage,snapshot=@snapshot","stage",index+1,"snapshot",CareerExploreSnapshot(p));Console.WriteLine("[career-city] scroll="+type+" silver="+price);
            }
            ushort[] targets={1000,1020,1011,1015,1002};uint[] types={1060021,1060022,1060023,1060024,1060020};
            for(int index=Math.Max(0,stage-5);index<5;index++){
                uint type=types[index];int count=p.Inventory.Objects.Where(v=>v.ID==type).Sum(v=>(int)v.StackSize);ItemHandler.UseItem(p.Inventory.Objects.First(v=>v.ID==type),p);
                Require(p.Action==2 && p.Entity.MapID==targets[index] && p.Inventory.Objects.Where(v=>v.ID==type).Sum(v=>(int)v.StackSize)==count-1);
                Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_city_probe SET stage=@stage,snapshot=@snapshot","stage",index+6,"snapshot",CareerExploreSnapshot(p));
            }
            if(stage<11){
                if(p.Entity.MapID!=1002 && p.Entity.MapID!=1036){
                    Require(p.Entity.MapID==1015);var shop=ShopFile.Shops.Values.First(v=>v.MoneyType==ShopFile.MoneyType.Gold && v.Items.Contains(1060020) && p.Map.Npcs.ContainsKey(v.UID));var npc=p.Map.Npcs[shop.UID];p.Entity.X=npc.X;p.Entity.Y=(ushort)(npc.Y+1);ulong money=p.Entity.Money;uint price=ConquerItemInformation.BaseInformations[1060020].GoldWorth;
                    var frame=new ItemUsage(true){UID=shop.UID,dwParam=1060020,dwExtraInfo=1,Action=ItemUsage.Mode.BuyFromNPC}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,frame.Length-8,frame);ItemUsage.Process(frame,p);Require(p.Entity.Money==money-price);ItemHandler.UseItem(p.Inventory.Objects.First(v=>v.ID==1060020),p);Require(p.Entity.MapID==1002);
                    Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_city_probe SET snapshot=@snapshot","snapshot",CareerExploreSnapshot(p));Console.WriteLine("[career-city] recovery-scroll-silver="+price);
                }
                if(p.Entity.MapID!=1036)CareerPortal(p,1036);Require(p.Entity.MapID==1036);HeartTalk(p,45,1);Require(p.Entity.MapID==1002);Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_city_probe SET stage=11,snapshot=@snapshot","snapshot",CareerExploreSnapshot(p));
            }
        }
        Require(Convert.ToInt32(Sql("SELECT stage FROM revora_career_city_probe"))==11);
        foreach(int id in new[]{10701,10625,10617,10629,10812})Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id AND source='travel-region-v1'","uid",(long)CareerUid,"id",id)==1);
        Require(CareerExploreSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_city_probe")));
        Console.WriteLine("[career-process] career-city-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career city travel did not close.");
    }
