    static void CareerSkyJourney(string phase){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();p.Quests=new Quests(p);p.Quests.Load();
        if(phase.EndsWith("prize")){
            if(p.Entity.MapID==1040){
                Require((bool)Sql(@"WITH RECURSIVE nodes(side,path,v) AS(
SELECT 0,ARRAY[]::text[],snapshot::jsonb FROM revora_career_treasury_probe UNION ALL SELECT 1,ARRAY[]::text[],@now::jsonb
UNION ALL SELECT n.side,n.path||e.key,CASE WHEN jsonb_typeof(e.value)='string' AND left(e.value#>>'{}',1)='{' THEN (e.value#>>'{}')::jsonb ELSE e.value END FROM nodes n CROSS JOIN LATERAL(
SELECT key,value FROM jsonb_each(CASE WHEN jsonb_typeof(n.v)='object' THEN n.v ELSE '{}'::jsonb END)
UNION ALL SELECT ord::text,value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(n.v)='array' THEN n.v ELSE '[]'::jsonb END) WITH ORDINALITY a(value,ord)) e),
leaves AS(SELECT side,path,v FROM nodes WHERE jsonb_typeof(v) NOT IN('object','array')),
changes AS(SELECT COALESCE(o.path,n.path) path,o.v old,n.v current FROM (SELECT * FROM leaves WHERE side=0) o FULL JOIN (SELECT * FROM leaves WHERE side=1) n USING(path) WHERE o.v IS DISTINCT FROM n.v)
SELECT count(*)=4 AND count(*) FILTER(WHERE path[array_length(path,1)]='warehouse')=3 AND bool_and((path[array_length(path,1)]='warehouse' AND old='0'::jsonb AND current='10028'::jsonb) OR (path[array_length(path,1)-1]='purse' AND path[array_length(path,1)]='1' AND old='1020697097'::jsonb AND current='1020697103'::jsonb)) FROM changes","now",CareerTreasurySnapshot(p)));
                Call(Feature("SkyPassQuest"),"OnLogin",p);Require(p.Entity.MapID==1012);
            }else{
            Require(CareerTreasurySnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_treasury_probe")));
            CareerPortal(p,1011);CareerPortal(p,1020);var npc=p.Map.Npcs[10028];p.Entity.X=npc.X;p.Entity.Y=(ushort)(npc.Y+1);
            foreach(var item in p.Inventory.Objects.Where(i=>i.ID/1000>=410 && i.ID/1000<=450).Take(3).ToArray()){
                var packet=new byte[172];Revora.Network.Writer.WriteUInt16(164,0,packet);Revora.Network.Writer.WriteUInt16(1102,2,packet);Revora.Network.Writer.WriteUInt32(10028,4,packet);packet[12]=1;packet[13]=10;Revora.Network.Writer.WriteUInt32(item.UID,18,packet);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,164,packet);Warehouse.Process(packet,p);Require(!p.Inventory.ContainsUID(item.UID) && p.Warehouses[(Revora.Game.ConquerStructures.Warehouse.WarehouseID)10028].Objects.Any(i=>i.UID==item.UID));
            }
            Require(p.Inventory.Count<=35);CareerPortal(p,1012);}
            HeartTalk(p,30055,1);Require(p.Entity.MapID==1040);
            for(int stage=1;stage<=5;stage++){
              for(int route=4;route>=0;route--){
                HeartTalk(p,SkyActor(stage,route,"Gate"),1);string state=Convert.ToString(Sql("SELECT phase FROM revora_sky_runs WHERE uid=@uid","uid",(long)CareerUid));
                if(state=="battle"){
                    uint family=(uint)(3000+(stage-1)*5+route);var target=p.Map.Entities.Values.First(e=>e.MonsterInfo!=null && e.MonsterInfo.ID==family && !e.Dead);p.Entity.X=target.X;p.Entity.Y=(ushort)(target.Y+2);p.Screen.Add(target);
                    int hits=0,stalled=0;while(!target.Dead && hits<2000){uint hp=target.Hitpoints;p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=target.UID,X=target.X,Y=target.Y,AttackType=Attack.Ranged},p);hits++;stalled=target.Hitpoints==hp?stalled+1:0;if(stalled>=32)break;}
                    Require(target.Dead && p.Action==2 && !p.Entity.Dead);HeartTalk(p,SkyActor(stage,route,"Guard"),1);Console.WriteLine("[career-sky] battle-stage="+stage+" shots="+hits);
                }
                Require(p.Action==2);
                if((long)Sql("SELECT count(*) FROM revora_sky_runs WHERE uid=@uid AND (stage>@stage OR phase='prize')","uid",(long)CareerUid,"stage",stage)==1)break;
              }
              Require((long)Sql("SELECT count(*) FROM revora_sky_runs WHERE uid=@uid AND (stage>@stage OR phase='prize')","uid",(long)CareerUid,"stage",stage)==1);
            }
            Require(p.Inventory.Contains(721109,1) && (long)Sql("SELECT count(*) FROM revora_sky_claims WHERE uid=@uid","uid",(long)CareerUid)==0);
            Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=11019","uid",(long)CareerUid)==0);
            Require(EntityTable.SaveEntity(p));Sql("CREATE TABLE revora_career_sky_probe(done boolean NOT NULL,snapshot text);INSERT INTO revora_career_sky_probe VALUES(false,@snapshot)","snapshot",CareerSkySnapshot(p));Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();Environment.Exit(0);return;
        }
        Require(CareerSkySnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_sky_probe")));
        if(phase.EndsWith("claim")){
            Call(Feature("SkyPassQuest"),"OnLogin",p);Require(p.Entity.MapID==1012);HeartTalk(p,30055,1);Require(p.Entity.MapID==1040 && p.Inventory.Contains(721109,1));HeartTalk(p,30054,1);Require(p.Action==2 && p.Entity.MapID==1012 && !p.Inventory.Contains(721109,1));
            Require((long)Sql("SELECT count(*) FROM revora_sky_claims r JOIN items i ON i.uid=ANY(r.rewards) WHERE r.uid=@uid AND i.entityid=r.uid AND i.bound=1 AND (i.id=1088001 OR i.id=4030101)","uid",(long)CareerUid)==5);
            Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=11019 AND source='sky-pass-v1'","uid",(long)CareerUid)==1);
            string before=CareerSkySnapshot(p);HeartTalk(p,30055,1);Require(p.Entity.MapID==1012 && CareerSkySnapshot(p)==before);CareerPortal(p,1020);CareerPortal(p,1011);CareerPortal(p,1002);Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_sky_probe SET done=true,snapshot=@snapshot","snapshot",CareerSkySnapshot(p));
        }
        Require((bool)Sql("SELECT done FROM revora_career_sky_probe") && p.Entity.MapID==1002 && CareerSkySnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_sky_probe")));
        Console.WriteLine("[career-process] "+phase+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Sky journey did not close.");
    }
    static string CareerTreasurySnapshot(GameState p){return Convert.ToString(Sql(@"SELECT json_build_object('career',@career::json,
'keys',(SELECT json_agg(r ORDER BY item_uid) FROM revora_dis_keys r WHERE uid=@uid),
'treasury',(SELECT row_to_json(r) FROM revora_dis_treasury r WHERE uid=@uid),
'openings',(SELECT json_agg(r ORDER BY opening) FROM revora_dis_treasury_claims r WHERE uid=@uid),
'packs',(SELECT json_agg(r ORDER BY result_uid) FROM revora_dis_refinery_packs r WHERE uid=@uid),
'horns',(SELECT json_agg(r ORDER BY item_uid) FROM revora_dis_horn_claims r WHERE uid=@uid))::text","career",CareerDisSnapshot(p),"uid",(long)CareerUid));}
    static void CareerTreasuryJourney(bool reload){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();p.Quests=new Quests(p);p.Quests.Load();
        if((bool)Sql("SELECT to_regclass('revora_career_treasury_probe') IS NULL")){
            Require(!reload && CareerDisSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_dis_probe")));
            Sql("CREATE TABLE revora_career_treasury_probe(done boolean NOT NULL,snapshot text);INSERT INTO revora_career_treasury_probe VALUES(false,@snapshot)","snapshot",CareerTreasurySnapshot(p));
        }
        if(!reload){
            var key=p.Inventory.Objects.Single(i=>i.ID==3006982);string before=CareerTreasurySnapshot(p);ItemHandler.UseItem(key,p);Require(CareerTreasurySnapshot(p)==before);
            HeartTalk(p,3215,3);Require(p.Action==2 && p.Map.BaseID==3954);HeartTalk(p,900000089,1);Require(p.Inventory.ContainsUID(key.UID));
            HeartTalk(p,900000089,0);System.Threading.Tasks.Parallel.For(0,12,i=>Npcs.GetDialog(new NpcRequest(true){NpcID=900000089,OptionID=1},p));
            Require(p.Action==2 && !p.Inventory.ContainsUID(key.UID));Require((long)Sql("SELECT count(*) FROM revora_dis_treasury_claims WHERE uid=@uid AND opening=1 AND key_uid=@key","uid",(long)CareerUid,"key",(long)key.UID)==1);
            before=CareerTreasurySnapshot(p);ItemHandler.UseItem(key,p);Npcs.GetDialog(new NpcRequest(true){NpcID=900000089,OptionID=1},p);Require(CareerTreasurySnapshot(p)==before);
            HeartTalk(p,3215,9);Require(p.Entity.MapID==1002);before=CareerTreasurySnapshot(p);HeartTalk(p,3215,3);Require(p.Entity.MapID==1002 && CareerTreasurySnapshot(p)==before);
            foreach(var pack in p.Inventory.Objects.Where(i=>i.ID==3008057 || i.ID==3008058).ToArray()){
                Require(pack.Bound && pack.StackSize==1);ItemHandler.UseItem(pack,p);Require(p.Action==2 && !p.Inventory.ContainsUID(pack.UID));
                Require((long)Sql("SELECT count(*) FROM revora_dis_refinery_packs r JOIN items i ON i.uid=r.result_uid AND i.entityid=r.uid AND i.id=r.result_type WHERE r.uid=@uid AND r.pack_uid=@pack AND i.bound=1","uid",(long)CareerUid,"pack",(long)pack.UID)==1);
                before=CareerTreasurySnapshot(p);ItemHandler.UseItem(pack,p);Require(CareerTreasurySnapshot(p)==before);
            }
            Require(p.Entity.Level>=Config.LevelCap);var horn=p.Inventory.Objects.Single(i=>i.ID==790001);before=CareerTreasurySnapshot(p);HeartTalk(p,3215,5);HeartTalk(p,3215,50);Require(p.Action==2 && p.Inventory.ContainsUID(horn.UID) && CareerTreasurySnapshot(p)==before);
            Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_treasury_probe SET done=true,snapshot=@snapshot","snapshot",CareerTreasurySnapshot(p));
        }
        Require((bool)Sql("SELECT done FROM revora_career_treasury_probe") && p.Entity.MapID==1002 && CareerTreasurySnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_treasury_probe")));
        Console.WriteLine("[career-process] career-treasury-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Treasury did not close.");
    }
    static long CareerDisValue(string field){return Convert.ToInt64(Sql("SELECT CASE @field WHEN 'stage' THEN stage WHEN 'progress' THEN progress WHEN 'quota' THEN quota WHEN 'crystal_order[progress+1]' THEN crystal_order[progress+1] END FROM revora_dis_runs WHERE uid=@uid","field",field,"uid",(long)CareerUid));}
    static void CareerDisKill(GameState p,ref DateTime now){
        now=now.AddSeconds(3);Call(Feature("DisCityQuest"),"Tick");var target=p.Map.Entities.Values.First(e=>e.MonsterInfo!=null && !e.Dead);p.Entity.X=target.X;p.Entity.Y=(ushort)(target.Y+2);p.Screen.Add(target);
        int shots=0,stalled=0;while(!target.Dead && shots<2000){
            var arrow=p.Equipment.TryGetItem(5);if(arrow==null || arrow.Durability==0){var next=p.Inventory.Objects.First(i=>ItemHandler.IsArrow(i.ID) && i.Durability>0);ItemHandler.EquipItem(new ItemUsage(true){UID=next.UID,dwParam=5,Action=ItemUsage.Mode.EquipItem},p);}
            uint hp=target.Hitpoints;p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=target.UID,X=target.X,Y=target.Y,AttackType=Attack.Ranged},p);shots++;
            stalled=target.Hitpoints==hp?stalled+1:0;if(stalled>=32)break;
        }
        if(!target.Dead)Console.WriteLine("[career-dis] stalled shots="+shots+" hp="+target.Hitpoints+" attack="+p.Entity.MaxAttack+" player-hp="+p.Entity.Hitpoints);
        Require(target.Dead && p.Action==2 && !p.Entity.Dead);
    }
