        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();p.Quests=new Quests(p);p.Quests.Load();
        var type=Feature("DisCityQuest");var oldClock=type.GetField("Clock",Hidden).GetValue(null);DateTime now=new DateTime(2026,10,2,20,0,0,DateTimeKind.Utc);type.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
        try{
            if((bool)Sql("SELECT to_regclass('revora_career_dis_probe') IS NULL")){
                Require(!reload && CareerLunaSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_luna_probe")));
                Sql("CREATE TABLE revora_career_dis_probe(done boolean NOT NULL,snapshot text);INSERT INTO revora_career_dis_probe VALUES(false,@snapshot)","snapshot",CareerDisSnapshot(p));
                var shop=ShopFile.Shops.Values.First(v=>v.MoneyType==ShopFile.MoneyType.Gold && p.Map.Npcs.ContainsKey(v.UID) && v.Items.Any(arrowId=>ItemHandler.IsArrow(arrowId)));uint id=shop.Items.Where(v=>ItemHandler.IsArrow(v)).OrderByDescending(v=>ConquerItemInformation.BaseInformations[v].Durability).First();
                for(int i=0;i<1;i++){var arrow=CareerSilverBuy(p,id,shop.UID);Console.WriteLine("[career-dis] purchased-arrow="+id+" durability="+arrow.Durability);}
                Require(EntityTable.SaveEntity(p));
            }
            if(!reload){
                Call(type,"OnLogin",p);Require(p.Entity.MapID==1002);HeartTalk(p,3215,1);Require(p.Action==2 && p.Map.BaseID>=2021 && p.Map.BaseID<=2024);
                while(CareerDisValue("stage")<=4 && Convert.ToString(Sql("SELECT phase FROM revora_dis_runs WHERE uid=@uid","uid",(long)CareerUid))!="complete"){
                    int stage=(int)CareerDisValue("stage");
                    if(stage==1 || stage==2){int quota=stage==1?5:(int)CareerDisValue("quota");if(stage==2)Require(quota==600);while(CareerDisValue("progress")<quota){CareerDisKill(p,ref now);if(CareerDisValue("progress")%100==0)Console.WriteLine("[career-dis] stage="+stage+" progress="+CareerDisValue("progress"));}HeartTalk(p,3215,2);HeartTalk(p,3215,1);Require(CareerDisValue("stage")==stage+1);}
                    else if(stage==3){while(CareerDisValue("progress")<9){uint crystal=(uint)(900000080+CareerDisValue("crystal_order[progress+1]"));CareerDisKill(p,ref now);HeartTalk(p,crystal,1);}HeartTalk(p,3215,1);Require(CareerDisValue("stage")==4);}
                    else {while(CareerDisValue("progress")<4)CareerDisKill(p,ref now);HeartTalk(p,3215,2);ItemHandler.UseItem(p.Inventory.Objects.First(i=>i.ID==3006983),p);ItemHandler.UseItem(p.Inventory.Objects.First(i=>i.ID==3006984),p);CareerDisKill(p,ref now);HeartTalk(p,3215,1);Require(p.Entity.MapID==1002);}
                    Require(EntityTable.SaveEntity(p));Console.WriteLine("[career-dis] finished-stage="+stage);
                }
                Require((long)Sql("SELECT count(*) FROM revora_dis_stage_claims WHERE uid=@uid","uid",(long)CareerUid)==4);foreach(int id in new[]{11002,11003,11004,11005})Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id AND source='dis-city-v1'","uid",(long)CareerUid,"id",id)==1);
                string completed=CareerDisSnapshot(p);HeartTalk(p,3215,1);Require(p.Entity.MapID==1002 && CareerDisSnapshot(p)==completed);Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_dis_probe SET done=true,snapshot=@snapshot","snapshot",CareerDisSnapshot(p));
            }
            Require(CareerDisValue("stage")==4 && CareerDisValue("progress")==4 && CareerDisValue("quota")==600);
            Require((bool)Sql("SELECT done FROM revora_career_dis_probe") && p.Entity.MapID==1002 && CareerDisSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_dis_probe")));
        }finally{type.GetField("Clock",Hidden).SetValue(null,oldClock);}
        Console.WriteLine("[career-process] career-dis-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Dis City did not close.");
    }
