                Require(p.Action==2 && p.Entity.MapID==1103 && p.Entity.Money==before);
                Require((long)Sql("SELECT count(*) FROM revora_moon_platform_passages WHERE uid=@uid AND NOT pending AND trips=1","uid",(long)CareerUid)==1);
                string admitted=CareerLunaSnapshot(p);Npcs.GetDialog(new NpcRequest(true){NpcID=4178,OptionID=2},p);Require(CareerLunaSnapshot(p)==admitted);
                int count=p.Inventory.Objects.Where(v=>v.ID==1060020).Sum(v=>(int)v.StackSize);ItemHandler.UseItem(p.Inventory.Objects.First(v=>v.ID==1060020),p);Require(p.Entity.MapID==1002 && p.Inventory.Objects.Where(v=>v.ID==1060020).Sum(v=>(int)v.StackSize)==count-1);Require(EntityTable.SaveEntity(p));
