    static void CareerWalkRegion(GameState p,int achievement){
        int width=p.Map.Floor.Bounds.Width,height=p.Map.Floor.Bounds.Height,start=p.Entity.Y*width+p.Entity.X,found=-1;
        var previous=Enumerable.Repeat(-1,width*height).ToArray();var directions=new byte[previous.Length];var queue=new System.Collections.Generic.Queue<int>();previous[start]=start;queue.Enqueue(start);
        while(queue.Count>0){int node=queue.Dequeue(),x=node%width,y=node/width;
            if(((int[])Call(Feature("TravelRegions"),"At",p.Entity.MapID,(ushort)x,(ushort)y)).Contains(achievement)){found=node;break;}
            for(byte d=0;d<8;d++){int nx=x+Entity.XDir[d],ny=y+Entity.YDir[d];if(nx<0 || ny<0 || nx>=width || ny>=height || !p.Map.Floor[nx,ny,MapObjectType.Player])continue;int next=ny*width+nx;if(previous[next]>=0)continue;previous[next]=node;directions[next]=d;queue.Enqueue(next);}
        }
        Require(found>=0);var steps=new System.Collections.Generic.Stack<byte>();for(int node=found;node!=start;node=previous[node])steps.Push(directions[node]);int count=steps.Count;
        foreach(byte d in steps){Require(p.Entity.Move((Enums.ConquerAngle)d,1));}
        // A landing already inside the region still needs an accepted movement.
        if(count==0){for(byte d=0;d<8;d++){ushort x=(ushort)(p.Entity.X+Entity.XDir[d]),y=(ushort)(p.Entity.Y+Entity.YDir[d]);if(p.Map.Floor[x,y,MapObjectType.Player] && ((int[])Call(Feature("TravelRegions"),"At",p.Entity.MapID,x,y)).Contains(achievement)){Require(p.Entity.Move((Enums.ConquerAngle)d,1));count++;break;}}}
        Require(count>0);Console.WriteLine("[career-fields] region="+achievement+" accepted-steps="+count);
    }
