            if(stage<3){
                int width=p.Map.Floor.Bounds.Width,height=p.Map.Floor.Bounds.Height,start=p.Entity.Y*width+p.Entity.X,found=-1;var previous=Enumerable.Repeat(-1,width*height).ToArray();var queue=new System.Collections.Generic.Queue<int>();previous[start]=start;queue.Enqueue(start);
                while(queue.Count>0){int node=queue.Dequeue(),x=node%width,y=node/width;if(((int[])Call(Feature("TravelRegions"),"At",p.Entity.MapID,(ushort)x,(ushort)y)).Contains(10809)){found=node;break;}
                    for(int nx=Math.Max(0,x-17);nx<Math.Min(width,x+18);nx++)for(int ny=Math.Max(0,y-17);ny<Math.Min(height,y+18);ny++){int next=ny*width+nx;if(previous[next]>=0 || !p.Map.Floor[nx,ny,MapObjectType.Player] || Kernel.GetDistance((ushort)x,(ushort)y,(ushort)nx,(ushort)ny)>17)continue;previous[next]=node;queue.Enqueue(next);}}
                Require(found>=0);var route=new System.Collections.Generic.Stack<int>();for(int node=found;node!=start;node=previous[node])route.Push(node);
                foreach(int node in route){System.Threading.Thread.Sleep(1200);ushort x=(ushort)(node%width),y=(ushort)(node/width);Require(Kernel.GetDistance(p.Entity.X,p.Entity.Y,x,y)<=17);
                    var jump=new Data(true){UID=p.Entity.UID,ID=Data.Jump,wParam1=p.Entity.X,wParam2=p.Entity.Y,Xt1=x,Yt1=y,TimeStamp=Time32.Now}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,jump.Length-8,jump);Data.Process(jump,p);
                    Require(p.Action==2 && p.Entity.MapID==1103 && p.Entity.X==x && p.Entity.Y==y);Console.WriteLine("[career-moon] accepted-jump="+x+","+y);
                }
                Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_moon_probe SET stage=3,snapshot=@snapshot","snapshot",CareerTrainingSnapshot(p));}
