'purchases',(SELECT json_agg(r ORDER BY item_uid) FROM revora_furniture_purchases r WHERE uid=@uid),
'placements',(SELECT json_agg(r ORDER BY actor) FROM revora_house_furniture r WHERE uid=@uid),
