    static byte[] CareerFurniturePosition(GameState p,ushort look){
        for(int dx=-12;dx<=12;dx++)for(int dy=-12;dy<=12;dy++){
            int x=p.Entity.X+dx,y=p.Entity.Y+dy;
            if(x<=0 || y<=0 || x>=p.Map.Floor.Bounds.Width || y>=p.Map.Floor.Bounds.Height || !(bool)Call(Feature("HouseFurniture"),"Cell",p,(ushort)x,(ushort)y,look))continue;
            var body=new System.Collections.Generic.List<byte>();uint[] pairs={4,(uint)x,5,(uint)y,6,look};
            for(int n=0;n<pairs.Length;n+=2){body.Add((byte)(pairs[n]*8));uint v=pairs[n+1];while(v>=128){body.Add((byte)(v|128));v>>=7;}body.Add((byte)v);}
            var frame=new byte[body.Count+12];body.CopyTo(frame,4);Revora.Network.Writer.WriteUInt16((ushort)(frame.Length-8),0,frame);Revora.Network.Writer.WriteUInt16(2030,2,frame);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,frame.Length-8,frame);return frame;
        }
        throw new InvalidOperationException("No legal furniture cell near owner.");
    }
