        }
        var portal=home.Portals.Single();p.Entity.X=portal.CurrentX;p.Entity.Y=portal.CurrentY;GeneralData.UsePortal(new Data(true){ID=Data.UsePortal,UID=p.Entity.UID},p);Require(p.Entity.MapID==portal.DestinationMapID);if(p.Entity.MapID!=1002)p.Entity.Teleport(1002,345,529);
        }while(!reload && (long)Sql("SELECT count(*) FROM revora_furniture_purchases WHERE uid=@uid","uid",(long)CareerUid)<12);
        Require((long)Sql("SELECT count(*) FROM revora_furniture_purchases WHERE uid=@uid AND cps_paid=2500 AND silver_paid=0","uid",(long)CareerUid)==12);
        Require((long)Sql("SELECT count(*) FROM revora_house_furniture WHERE uid=@uid AND removed_at IS NULL","uid",(long)CareerUid)==12);
        Require(home.Npcs.Values.Count(v=>v.Type==Enums.NpcType.Furniture)==12);
        Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=10101 AND source='house-furniture-v1'","uid",(long)CareerUid)==1);
