            Sql("CREATE TABLE revora_career_house_probe(snapshot text);INSERT INTO revora_career_house_probe VALUES(@snapshot)","snapshot",CareerHouseSnapshot(p));
        }
        Require(CareerHouseSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_house_probe")));
        if(!reload){
            uint[] permits={721170,721174,711198,711200,711553};ulong[] silver={300000,500000,2000000,5000000,0};
            int level=Convert.ToInt32(Sql("SELECT COALESCE((SELECT houselevel FROM house WHERE id=@uid),0)","uid",(long)CareerUid));
            for(int next=level+1;next<=5;next++){
                uint cp=p.Entity.ConquerPoints,price=(uint)Call(Feature("Housing"),"Price",next);ulong money=p.Entity.Money;
                var before=p.Inventory.Objects.Select(i=>i.UID).ToArray();HeartTalk(p,30156,(byte)(next+4));HeartTalk(p,30156,40);
                var cert=p.Inventory.Objects.Single(i=>!before.Contains(i.UID));Require(cert.ID==permits[next-1] && p.Entity.ConquerPoints==cp-price);
                string bought=CareerHouseSnapshot(p);HeartTalk(p,30156,40);Require(bought==CareerHouseSnapshot(p));
                HeartTalk(p,30156,next==1?(byte)1:(byte)3);HeartTalk(p,30156,40);
                Require(p.Action==2 && !p.Inventory.ContainsUID(cert.UID) && p.Entity.Money==money-silver[next-1] && Convert.ToInt32(Sql("SELECT houselevel FROM house WHERE id=@uid","uid",(long)CareerUid))==next);
                string built=CareerHouseSnapshot(p);HeartTalk(p,30156,40);Require(built==CareerHouseSnapshot(p));
                SkillTable.SaveSpells(p);Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_house_probe SET snapshot=@snapshot","snapshot",CareerHouseSnapshot(p));
                Console.WriteLine("[career-house] level="+next+" cp="+price+" silver="+silver[next-1]);
            }
        }
        Require((long)Sql("SELECT count(*) FROM revora_house_builds WHERE uid=@uid","uid",(long)CareerUid)==5);
        foreach(int id in new[]{10102,10103,10104,10105,10122})Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id AND source='house-construction-v1'","uid",(long)CareerUid,"id",id)==1);
        var home=(Map)Call(Feature("Housing"),"Load",p);Require(home!=null && home.BaseID==3024 && MapsTable.MapInformations[home.ID].Owner==CareerUid);
        HeartTalk(p,30156,2);Require(p.Action==2 && p.Entity.MapID==home.ID && home.Floor[p.Entity.X,p.Entity.Y,MapObjectType.Player]);
        var portal=home.Portals.Single();p.Entity.X=portal.CurrentX;p.Entity.Y=portal.CurrentY;
        GeneralData.UsePortal(new Data(true){ID=Data.UsePortal,UID=p.Entity.UID},p);Require(p.Entity.MapID==portal.DestinationMapID);
        if(p.Entity.MapID!=1002)p.Entity.Teleport(1002,345,529);
        Require(CareerHouseSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_house_probe")));
        Console.WriteLine("[career-process] career-house-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career housing did not close.");
    }
