    static void CareerRuneMove(GameState p,ConquerItem item,ushort action,uint slot=0){var packet=new byte[112];Revora.Network.Writer.WriteUInt16(104,0,packet);Revora.Network.Writer.WriteUInt16(1009,2,packet);Revora.Network.Writer.WriteUInt32(item.UID,8,packet);Revora.Network.Writer.WriteUInt32(slot,12,packet);Revora.Network.Writer.WriteUInt16(action,20,packet);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,104,packet);RunesSystem.HandlePacket1009(p,packet);}
    static void CareerRuneJourney(bool reload){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();Require(p.RunesItem!=null && p.Entity.Class==45);
        if((bool)Sql("SELECT to_regclass('revora_career_rune_probe') IS NULL")){
            Require(!reload && CareerEnchantSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_enchant_probe")));
            Sql("CREATE TABLE revora_career_rune_probe(snapshot text,items bigint[] NOT NULL);INSERT INTO revora_career_rune_probe VALUES(@snapshot,ARRAY[]::bigint[])","snapshot",CareerRuneSnapshot(p));
        }
        Require(CareerRuneSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_rune_probe")));
        if(!reload){
            byte[] choices={182,192,200,201,202};uint[] types={4010201,4020301,4030101,4030201,4030301};uint[] prices={1000,750,500,500,500};
            var uids=((long[])Sql("SELECT items FROM revora_career_rune_probe")).ToList();
            for(int ix=uids.Count;ix<5;ix++){
                var before=p.Inventory.Objects.Select(i=>i.UID).ToArray();uint rvp=p.Entity.RevoraPoint;HeartTalk(p,900000014,choices[ix]);var item=p.Inventory.Objects.Single(i=>!before.Contains(i.UID));Require(item.ID==types[ix] && p.Entity.RevoraPoint==rvp-prices[ix]);
                CareerRuneMove(p,item,61);Require(item.Position==211 && p.RunesItem.ContainsKey(item.UID));CareerRuneMove(p,item,57,(uint)(101+ix));Require(item.Position==101+ix);
                uids.Add(item.UID);SkillTable.SaveSpells(p);Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_rune_probe SET items=@items,snapshot=@snapshot","items",uids.ToArray(),"snapshot",CareerRuneSnapshot(p));
            }
            uint stoneType=EShopFile.Shops[2888].Items.Where(id=>id>=730001 && id<=730008 && ConquerItemInformation.BaseInformations.ContainsKey(id) && ConquerItemInformation.BaseInformations[id].ConquerPointsWorth>0).OrderByDescending(id=>id).First();
            var clock=Feature("ExemptionTokenShop").GetField("Clock",Hidden);var savedClock=clock.GetValue(null);var latest=Sql("SELECT extract(epoch FROM max(purchased_at)) FROM revora_exemption_purchases WHERE uid=@uid AND item_type=@type","uid",(long)CareerUid,"type",(int)stoneType);DateTime buyTime=latest==DBNull.Value?DateTime.UtcNow:new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddSeconds(Convert.ToDouble(latest));if(buyTime<DateTime.UtcNow)buyTime=DateTime.UtcNow;
            var until=DateTime.UtcNow.AddSeconds(70);int used=0;
            try{clock.SetValue(null,(Func<DateTime>)(()=>buyTime));
            foreach(long uid in uids){var rune=p.RunesItem[(uint)uid];uint terminal=rune.ID/10000==401?1u:rune.ID/10000==402?27u:9u;uint cp=p.Entity.ConquerPoints;
                while(rune.ID%100<terminal && DateTime.UtcNow<until && used<250){
                    buyTime=buyTime.AddSeconds(2);var before=p.Inventory.Objects.Select(i=>i.UID).ToArray();CareerBuy(p,stoneType);var stone=p.Inventory.Objects.Single(i=>!before.Contains(i.UID));Require(stone.ID==stoneType && stone.Plus==stoneType-730000);
                    var packet=new byte[103];Revora.Network.Writer.WriteUInt16(95,0,packet);Revora.Network.Writer.WriteUInt16(1009,2,packet);Revora.Network.Writer.WriteUInt32(rune.UID,8,packet);Revora.Network.Writer.WriteUInt16(63,20,packet);Revora.Network.Writer.WriteUInt32(1,26,packet);Revora.Network.Writer.WriteUInt32(stone.UID,91,packet);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,95,packet);
                    uint type=rune.ID,xp=rune.RunesEXP;RunesSystem.HandlePacket1009(p,packet);Require(p.Action==2 && !p.Inventory.ContainsUID(stone.UID) && (rune.ID>type || rune.RunesEXP>xp));used++;
                    string once=CareerRuneSnapshot(p);RunesSystem.HandlePacket1009(p,packet);Require(once==CareerRuneSnapshot(p));
                    SkillTable.SaveSpells(p);Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_rune_probe SET snapshot=@snapshot","snapshot",CareerRuneSnapshot(p));
                }
                Console.WriteLine("[career-rune] id="+rune.ID+" xp="+rune.RunesEXP+" stone="+stoneType+" cp="+(cp-p.Entity.ConquerPoints));
            }
            }finally{clock.SetValue(null,savedClock);}
        }
        var owned=(long[])Sql("SELECT items FROM revora_career_rune_probe");Require(owned.Length==5 && owned.All(uid=>p.RunesItem.ContainsKey((uint)uid)));var equipped=owned.Select(uid=>p.RunesItem[(uint)uid]).ToArray();Require(equipped.Select(i=>i.Position).OrderBy(i=>i).SequenceEqual(new byte[]{101,102,103,104,105}));
        foreach(int id in new[]{11310,11311})Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id AND source='rune-loadout-v1'","uid",(long)CareerUid,"id",id)==1);
        bool complete=equipped.All(i=>i.ID%100==(i.ID/10000==401?1u:i.ID/10000==402?27u:9u));Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=11316 AND source='rune-full-level-v1'","uid",(long)CareerUid)==(complete?1:0));
        if(complete){
            var eligible=(System.Collections.Generic.HashSet<int>)GameAssembly.GetType("Revora.TitleRequirements",true).GetMethod("Eligible",Hidden).Invoke(null,new object[]{p});Require(eligible.Contains(90001));
            var titles=(System.Collections.Generic.Dictionary<int,bool>)p.Entity.WTitles.GetType().GetMethod("Records",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p.Entity.WTitles,null);Require(titles.ContainsKey(90001));
        }
        Require(CareerRuneSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_rune_probe")));Console.WriteLine("[career-rune] five-max="+complete);
        Console.WriteLine("[career-process] career-rune-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career runes did not close.");
    }
    static string CareerEnchantSnapshot(GameState p){return Convert.ToString(Sql("SELECT json_build_object('career',@career::json,'enchantments',(SELECT json_agg(r ORDER BY created_at,id) FROM revora_item_enchantments r WHERE uid=@uid),'item_hp',(SELECT json_agg(r ORDER BY uid) FROM (SELECT uid,enchant FROM items WHERE entityid=@uid) r))::text","career",CareerVestmentSnapshot(p),"uid",(long)CareerUid));}
    static void CareerEnchantJourney(bool reload,bool recover=false){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();
        if((bool)Sql("SELECT to_regclass('revora_career_enchant_probe') IS NULL")){
            Require(!reload && CareerVestmentSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_alternate_probe")));
            Sql("CREATE TABLE revora_career_enchant_probe(snapshot text);INSERT INTO revora_career_enchant_probe VALUES(@snapshot)","snapshot",CareerEnchantSnapshot(p));
        }
        if(recover){
            Require((long)Sql("SELECT count(*) FROM revora_item_enchantments WHERE uid=@uid","uid",(long)CareerUid)==1);
            uint type=Convert.ToUInt32(Sql("SELECT gem_type FROM revora_item_enchantments WHERE uid=@uid","uid",(long)CareerUid));uint price=ConquerItemInformation.BaseInformations[type].ConquerPointsWorth;Require(price>0);
            Require((bool)Sql(@"WITH RECURSIVE nodes(v,depth) AS(SELECT snapshot::jsonb,0 FROM revora_career_enchant_probe UNION ALL SELECT CASE WHEN jsonb_typeof(e.value)='string' THEN (e.value#>>'{}')::jsonb ELSE e.value END,n.depth+1 FROM nodes n CROSS JOIN LATERAL jsonb_each(n.v) e WHERE n.depth<40 AND (jsonb_typeof(e.value)='object' OR jsonb_typeof(e.value)='string' AND left(e.value#>>'{}',1)='{')),old AS(SELECT v->'belongings' AS v FROM nodes WHERE v?'belongings' LIMIT 1),current AS(SELECT @now::jsonb AS v)
SELECT old.v-'purse'=current.v-'purse' AND (old.v->'purse'->>0)::bigint-(current.v->'purse'->>0)::bigint=@price AND (old.v->'purse')-0=(current.v->'purse')-0
AND EXISTS(SELECT 1 FROM revora_item_enchantments e JOIN items i ON i.uid=e.target_uid WHERE e.uid=@uid AND i.entityid=@uid AND e.before_hp=0 AND e.roll_hp=e.after_hp AND i.enchant=e.after_hp AND e.after_hp>0 AND e.before_stack=1 AND e.after_stack=0 AND NOT EXISTS(SELECT 1 FROM items WHERE uid=e.gem_uid))
FROM old,current","now",CollectionSnapshot(p),"price",(long)price,"uid",(long)CareerUid));
            Sql("UPDATE revora_career_enchant_probe SET snapshot=@snapshot","snapshot",CareerEnchantSnapshot(p));Console.WriteLine("[career-process] career-enchant-recover-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Enchantment recovery did not close.");
        }
        Require(CareerEnchantSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_enchant_probe")));
        var targets=new byte[]{1,2,3,4,6,8}.Select(slot=>p.Equipment.TryGetItem(slot)).ToArray();Require(targets.All(i=>i!=null));
        if(!reload){
            uint gemType=EShopFile.Shops[2888].Items.Where(id=>id>=700001 && id<=700073 && id%10>=1 && id%10<=3 && ConquerItemInformation.BaseInformations.ContainsKey(id) && ConquerItemInformation.BaseInformations[id].ConquerPointsWorth>0 && Enum.IsDefined(typeof(Revora.Game.Enums.Gem),(byte)(id%1000))).OrderBy(id=>ConquerItemInformation.BaseInformations[id].ConquerPointsWorth).ThenBy(id=>id).First();
