                string once=CareerEnchantSnapshot(p);ItemHandler.EnchantItem(request,p);Require(once==CareerEnchantSnapshot(p));
                ItemHandler.EquipItem(new ItemUsage(true){UID=item.UID,dwParam=slot,Action=ItemUsage.Mode.EquipItem},p);Require(p.Equipment.TryGetItem(slot).UID==item.UID);
                if(arrow!=null && arrow.Position!=5){ItemHandler.EquipItem(new ItemUsage(true){UID=arrow.UID,dwParam=5,Action=ItemUsage.Mode.EquipItem},p);Require(p.Equipment.TryGetItem(5).UID==arrow.UID);}
                Require(EntityTable.SaveEntity(p));p.Entity.MyAchievement.GetType().GetMethod("Invalidate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p.Entity.MyAchievement,null);p.Entity.MyAchievement.Send();
                Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=10416","uid",(long)CareerUid)==(targets.All(i=>i.Enchant>0)?1:0));
                Sql("UPDATE revora_career_enchant_probe SET snapshot=@snapshot","snapshot",CareerEnchantSnapshot(p));Console.WriteLine("[career-enchant] slot="+slot+" gem="+gemType+" cp="+(before-p.Entity.ConquerPoints)+" hp="+item.Enchant);
            }
        }
        Require(targets.All(i=>i.Enchant>0));
        Require((long)Sql("SELECT count(*) FROM revora_item_enchantments WHERE uid=@uid","uid",(long)CareerUid)==6);
        foreach(int id in new[]{10416,10430})Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id","uid",(long)CareerUid,"id",id)==1);
        Require(CareerEnchantSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_enchant_probe")));
        Console.WriteLine("[career-process] career-enchant-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career enchant did not close.");
    }
