            Require((long)Sql("SELECT conquerpoints FROM entities WHERE uid=@uid","uid",(long)CareerUid)==cp-price && (long)Sql("SELECT count(*) FROM revora_vestment_purchases WHERE uid=@uid","uid",(long)CareerUid)==2);
            var added=(long[])Sql("SELECT item_uids FROM revora_vestment_purchases WHERE uid=@uid AND item_uids<>@old","uid",(long)CareerUid,"old",old);Require(added.Length==7 && !added.Intersect(old).Any());
            Sql("CREATE TABLE revora_career_alternate_probe(snapshot text,items bigint[],old_items bigint[],balance bigint);INSERT INTO revora_career_alternate_probe VALUES(@snapshot,@items,@old,@balance)","snapshot",CareerVestmentSnapshot(p),"items",added,"old",old,"balance",(long)(cp-price));
        }else{
