            var uids=(long[])Sql("SELECT items FROM revora_career_alternate_probe");var old=(long[])Sql("SELECT old_items FROM revora_career_alternate_probe");var items=p.Inventory.Objects.Concat(p.Equipment.GetItems()).Where(i=>uids.Contains((long)i.UID)).ToArray();Require(items.Length==7);
