            if(phase=="career-alternate-earn"){
                Require(GeneralData.SwitchEquipment(p,true));Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=10432","uid",(long)CareerUid)==0);Require(GeneralData.SwitchEquipment(p,false));
                foreach(var item in items.OrderBy(i=>ItemHandler.GetPositionFromID(i.ID))){byte slot=(byte)(ItemHandler.GetPositionFromID(item.ID)+20);ItemHandler.EquipItem(new ItemUsage(true){UID=item.UID,dwParam=slot,Action=ItemUsage.Mode.EquipItem},p);Require(p.Equipment.TryGetItem(slot)!=null && p.Equipment.TryGetItem(slot).UID==item.UID);}
                Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=10432","uid",(long)CareerUid)==0);
                Require(GeneralData.SwitchEquipment(p,true));Require(GeneralData.SwitchEquipment(p,true));Require(GeneralData.SwitchEquipment(p,false));Require(EntityTable.SaveEntity(p));
                Sql("UPDATE revora_career_alternate_probe SET snapshot=@snapshot","snapshot",CareerVestmentSnapshot(p));
