            Require((long)Sql("SELECT count(*) FROM itemadding a JOIN items i ON i.uid=a.uid WHERE i.entityid=@uid AND i.uid=ANY(@items) AND a.addingtype=0 AND a.addinglevel=7 AND a.duration=0","uid",(long)CareerUid,"items",uids)==6);
            string before=CareerVestmentSnapshot(p);HeartTalk(p,900000001,12);Require(before==CareerVestmentSnapshot(p));Require((long)Sql("SELECT count(*) FROM revora_vestment_purchases WHERE uid=@uid","uid",(long)CareerUid)==2);
