(SELECT count(*) FROM jsonb_array_elements(old.v->'items') i WHERE (i->>'uid')::bigint=ANY(purchase.item_uids))=0 AND
(SELECT jsonb_agg(i-'position' ORDER BY i->>'uid') FROM jsonb_array_elements(old.v->'items') i)=
(SELECT jsonb_agg(i-'position' ORDER BY i->>'uid') FROM jsonb_array_elements(current.v->'items') i WHERE NOT (i->>'uid')::bigint=ANY(purchase.item_uids)) AND
(SELECT count(*) FROM items i WHERE i.uid=ANY(purchase.item_uids) AND i.entityid=@uid AND i.bound=1)=7
