                    var arrow=items.Single(i=>ItemHandler.IsArrow(i.ID));if(arrow.Position!=5)ItemHandler.EquipItem(new ItemUsage(true){UID=arrow.UID,dwParam=5,Action=ItemUsage.Mode.EquipItem},p);Require(p.Equipment.TryGetItem(5)!=null);p.LoadItemStats();CareerTrainMelee(p,500,12,Attack.Ranged);
