    static string CareerSubclassSnapshot(GameState p){return Convert.ToString(Sql("SELECT json_build_object('career',@career::json,'classes',(SELECT json_agg(r ORDER BY uid) FROM subclasses r WHERE id=@uid),'study',(SELECT studypoints FROM entities WHERE uid=@uid))::text","career",CareerGemSnapshot(p),"uid",(long)CareerUid));}
