    static void CareerSubclassBuy(GameState p,uint type,uint amount){
        p.BindWorldMap(1002);var npc=p.Map.Npcs[91008];p.Entity.X=npc.X;p.Entity.Y=(ushort)(npc.Y+1);uint cp=p.Entity.ConquerPoints;uint price=ConquerItemInformation.BaseInformations[type].ConquerPointsWorth;Require(price>0 && (ulong)price*amount<=cp);
        var packet=new ItemUsage(true){UID=91008,dwParam=type,dwExtraInfo=amount,Action=ItemUsage.Mode.BuyFromNPC}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,packet.Length-8,packet);ItemUsage.Process(packet,p);Require(p.Entity.ConquerPoints==cp-price*amount);
