    static void CareerSubclassJourney(bool reload){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);SubClassTable.Load(p.Entity);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();
        if((bool)Sql("SELECT to_regclass('revora_career_subclass_probe') IS NULL")){
            Require(!reload && CareerGemSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_active_probe")));
            Sql("CREATE TABLE revora_career_subclass_probe(snapshot text);INSERT INTO revora_career_subclass_probe VALUES(@snapshot)","snapshot",CareerSubclassSnapshot(p));
        }
        Require(CareerSubclassSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_subclass_probe")));
        if(!reload && !p.Entity.SubClasses.Classes.ContainsKey(5) && p.Inventory.Count>30){
            var balls=p.Inventory.Objects.Where(i=>i.ID==1088000 && i.Lock==0 && !i.Suspicious).ToArray();
            var stored=p.Warehouses.SelectMany(w=>w.Value.Objects).Where(i=>i.ID==1088000 && i.Lock==0 && !i.Suspicious).Take(3).ToArray();
            Require(balls.Length==7 && stored.Length==3 && p.Inventory.Count+3<=40);
            foreach(var item in stored){uint npcId=item.Warehouse;var map=Kernel.Maps.Values.Single(m=>m.Npcs.ContainsKey(npcId));var npc=map.Npcs[npcId];p.Entity.Teleport(map.ID,(ushort)(npc.X-1),npc.Y);
                var packet=new byte[172];Revora.Network.Writer.WriteUInt16(164,0,packet);Revora.Network.Writer.WriteUInt16(1102,2,packet);Revora.Network.Writer.WriteUInt32(npcId,4,packet);packet[12]=2;packet[13]=10;Revora.Network.Writer.WriteUInt32(item.UID,18,packet);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,164,packet);Revora.Network.GamePackets.Warehouse.Process(packet,p);Require(p.Inventory.ContainsUID(item.UID));
            }
            p.BindWorldMap(1002);uint cp=p.Entity.ConquerPoints;ulong silver=p.Entity.Money;HeartTalk(p,11275,2);
