                uint book=books[Array.IndexOf(ids,id)];var map=Kernel.Maps.Values.First(m=>(m.ID==1002 || m.ID==1011) && (m.Npcs.ContainsKey(141) || m.Npcs.ContainsKey(423)));uint shop=map.Npcs.ContainsKey(141)?141u:423u;
