                    uint hp=target.Hitpoints;p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);p.Entity.SSyFBS=Time32.Now.AddSeconds(-2);p.Entity.Stamina=100;
                    Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=target.UID,X=target.X,Y=target.Y,AttackType=Attack.Magic,Decoded=true,Damage=id},p);shots++;
                    if(target.Hitpoints==hp)stalled++;else stalled=0;if(stalled>=32)break;
                }
