    static string CareerGemSnapshot(GameState p){return Convert.ToString(Sql("SELECT json_build_object('career',@career::json,'gems',(SELECT json_agg(r ORDER BY id) FROM revora_gem_compositions r WHERE uid=@uid),'materials',(SELECT json_agg(m ORDER BY m.item_uid) FROM revora_gem_materials m JOIN revora_gem_compositions c ON c.id=m.composition WHERE c.uid=@uid),'mining',(SELECT row_to_json(r) FROM revora_mining_state r WHERE uid=@uid))::text","career",CareerBooksSnapshot(p),"uid",(long)CareerUid));}
