                var packet=new byte[172];Revora.Network.Writer.WriteUInt16(164,0,packet);Revora.Network.Writer.WriteUInt16(1102,2,packet);Revora.Network.Writer.WriteUInt32(npcId,4,packet);packet[12]=2;packet[13]=10;Revora.Network.Writer.WriteUInt32(item.UID,18,packet);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,164,packet);Warehouse.Process(packet,p);Require(p.Inventory.ContainsUID(item.UID));}
            Require(p.Inventory.Objects.Count(i=>i.ID==700031 && !i.Bound)==10);p.BindWorldMap(1002);CareerPortal(p,1011);HeartTalk(p,125,1);Require(p.Entity.MapID==1025);
            var pick=p.Inventory.Objects.Single(i=>i.ID==562000);foreach(byte slot in new byte[]{5,4})if(p.Equipment.TryGetItem(slot)!=null)ItemHandler.UnequipItem(new ItemUsage(true){dwParam=slot,Action=ItemUsage.Mode.UnequipItem},p);
            ItemHandler.EquipItem(new ItemUsage(true){UID=pick.UID,dwParam=4,Action=ItemUsage.Mode.EquipItem},p);Require(p.Equipment.TryGetItem(4).UID==pick.UID);
            var mining=Feature("MiningRewards");DateTime now=DateTime.UtcNow.AddDays(4);var prior=(DateTime)Sql("SELECT next_at FROM revora_mining_state WHERE uid=@uid","uid",(long)CareerUid);if(prior>=now)now=prior.AddSeconds(3);
            mining.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));mining.GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>max==10000?0:max==4?2:0));
            var start=new Data(true){ID=Data.SwingPickaxe,UID=p.Entity.UID}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,start.Length-8,start);Data.Process(start,p);
            for(int n=0;n<5;n++){now=now.AddSeconds(3);Revora.Game.ConquerStructures.Mining.Mine(p);Require(p.Inventory.Objects.Count(i=>i.ID==700031 && !i.Bound)==11+n);}
            CareerPortal(p,1011);CareerPortal(p,1002);ulong silver=p.Entity.Money;int count=p.Inventory.Count;uint[] inputs=p.Inventory.Objects.Where(i=>i.ID==700031 && !i.Bound).Select(i=>i.UID).ToArray();Require(inputs.Length==15);
            ItemUsage.Process(CareerGemRequest(),p);Require(p.Entity.Money==silver-10000 && p.Inventory.Count==count-14 && !inputs.Any(uid=>p.Inventory.ContainsUID(uid)));
            Require(p.Inventory.Objects.Count(i=>i.ID==700032 && !i.Bound)==1);Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_career_gems_probe SET snapshot=@snapshot","snapshot",CareerGemSnapshot(p));
        }
        Require((long)Sql("SELECT count(*) FROM revora_gem_compositions WHERE uid=@uid AND input_type=700031 AND output_type=700032 AND cost=10000 AND NOT bound","uid",(long)CareerUid)==1);
        Require((long)Sql("SELECT count(*) FROM revora_gem_materials m JOIN revora_gem_compositions c ON c.id=m.composition WHERE c.uid=@uid","uid",(long)CareerUid)==15);
        string beforeReplay=CareerGemSnapshot(p);ItemUsage.Process(CareerGemRequest(),p);Require(CareerGemSnapshot(p)==beforeReplay && p.Inventory.Objects.Count(i=>i.ID==700032 && !i.Bound)==1);
        Require(CareerGemSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_gems_probe")));
        Console.WriteLine("[career-process] career-gems-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career gem journey did not close.");
    }
