            var catalog=ShopFile.Shops[5].Items.Distinct().Where(type=>families.Contains((ushort)(type/1000))).Select(type=>ConquerItemInformation.BaseInformations[type]).Where(i=>i.Class==0 && i.Proficiency==0 && i.GoldWorth>0 && i.Level<=p.Entity.Level).OrderByDescending(i=>i.MaxAttack).ToArray();
