            var weapon=p.Inventory.Objects.FirstOrDefault(i=>i.ID==typeId)??CareerSilverBuy(p,typeId);ItemHandler.EquipItem(new ItemUsage(true){UID=weapon.UID,dwParam=4,Action=ItemUsage.Mode.EquipItem},p);Require(p.Equipment.TryGetItem(4).UID==weapon.UID);p.LoadItemStats();
            byte level=p.Spells[id].Level;uint xp=p.Spells[id].Experience;int shots=0;var until=DateTime.UtcNow.AddSeconds(12);
            var targets=Kernel.Maps.Values.SelectMany(m=>m.Entities.Values).Where(e=>!e.Dead && e.MonsterInfo!=null && !e.MonsterInfo.Boss && !e.MonsterInfo.Guard && !e.MonsterInfo.Reviver && !e.Companion && e.Defence<p.Entity.MaxAttack/2).OrderByDescending(e=>e.Hitpoints).Take(128).ToArray();
            foreach(var target in targets){
