                while(!target.Dead && !p.Entity.Dead && p.Spells[id].Level<9 && DateTime.UtcNow<until && shots<100000){uint hp=target.Hitpoints;p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=target.UID,X=target.X,Y=target.Y,AttackType=Attack.Melee},p);shots++;if(target.Hitpoints==hp)stalled++;else stalled=0;if(stalled>=32)break;}
                if(p.Entity.Dead || p.Spells[id].Level==9 || DateTime.UtcNow>=until || shots>=100000)break;
            }
            SkillTable.SaveSpells(p);SkillTable.SaveProficiencies(p);p.BindWorldMap(1002);Require(EntityTable.SaveEntity(p));
            Console.WriteLine("[career-passives] skill="+id+" shots="+shots+" before="+level+":"+xp+" after="+p.Spells[id].Level+":"+p.Spells[id].Experience);
            Sql("UPDATE revora_career_passives_probe SET snapshot=@snapshot","snapshot",CareerBooksSnapshot(p));
        }
        p.Entity.MyAchievement.Send();foreach(ushort id in ids){int credit=id==5030?10506:10515+(id-7000)/10;Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id AND source='weapon-skill-fixed-v1'","uid",(long)CareerUid,"id",credit)==(p.Spells[id].Level==9?1:0));}
        Require(CareerBooksSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_passives_probe")));
        Console.WriteLine("[career-passives] fixed="+ids.Count(id=>p.Spells[id].Level==9));Console.WriteLine("[career-process] career-passives-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career passive training did not close.");
    }
