            if(p.Entity.MapID!=map.ID)CareerPortal(p,map.ID);uint shop=map.Npcs.ContainsKey(141)?141u:423u;var npc=map.Npcs[shop];p.Entity.X=npc.X;p.Entity.Y=(ushort)(npc.Y+1);
