                var item=p.Inventory.Objects.Single(v=>v.ID==books[i]);Require(p.Entity.Money==before-5000);
                Require((long)Sql("SELECT count(*) FROM revora_weapon_book_purchases WHERE uid=@uid AND @item=ANY(item_uids) AND cost=5000 AND quantity=1","uid",(long)CareerUid,"item",(long)item.UID)==1);
                ItemHandler.UseItem(item,p);Require(!p.Inventory.ContainsUID(item.UID) && p.Spells.ContainsKey(spells[i]) && p.Spells[spells[i]].Level==0);
