        Require(CareerBooksSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_books_probe")));
        Console.WriteLine("[career-process] career-books-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career book journey did not close.");
    }
