    static void CareerPromotionMaterials(GameState p){
        if(p.Entity.Class==41 && !p.Inventory.Contains(1072031,5)){
            p.BindWorldMap(1002);var pick=p.Inventory.Objects.Concat(p.Equipment.GetItems()).SingleOrDefault(i=>i.ID==562000);
            if(pick==null){var shop=p.Map.Npcs[1];p.Entity.X=shop.X;p.Entity.Y=(ushort)(shop.Y+2);ulong silver=p.Entity.Money;
                var buy=new ItemUsage(true){UID=1,dwParam=562000,dwExtraInfo=1,Action=ItemUsage.Mode.BuyFromNPC}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,buy.Length-8,buy);ItemUsage.Process(buy,p);
                pick=p.Inventory.Objects.Single(i=>i.ID==562000);Require(p.Entity.Money==silver-1000);}
            foreach(byte slot in new byte[]{5,4})if(p.Equipment.TryGetItem(slot)!=null && p.Equipment.TryGetItem(slot).UID!=pick.UID)ItemHandler.UnequipItem(new ItemUsage(true){dwParam=slot,Action=ItemUsage.Mode.UnequipItem},p);
            if(pick.Position!=4)ItemHandler.EquipItem(new ItemUsage(true){UID=pick.UID,dwParam=4,Action=ItemUsage.Mode.EquipItem},p);Require(p.Equipment.TryGetItem(4).UID==pick.UID);
            var mining=Feature("MiningRewards");DateTime now=DateTime.UtcNow.AddDays(3);var prior=Sql("SELECT next_at FROM revora_mining_state WHERE uid=@uid","uid",(long)CareerUid);if(prior!=null && prior!=DBNull.Value && (DateTime)prior>=now)now=((DateTime)prior).AddSeconds(3);
            mining.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));int call=0;
            mining.GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>max==10000?9999:max==100?(++call==2?99:0):0));
            HeartTalk(p,10080,5);Require(p.Entity.MapID==1028);var start=new Data(true){ID=Data.SwingPickaxe,UID=p.Entity.UID}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,start.Length-8,start);Data.Process(start,p);
            for(int attempt=0;!p.Inventory.Contains(1072031,5) && attempt<5;attempt++){call=0;now=now.AddSeconds(3);int before=p.Inventory.Objects.Count(i=>i.ID==1072031);Revora.Game.ConquerStructures.Mining.Mine(p);Require(p.Inventory.Objects.Count(i=>i.ID==1072031)==before+1);}
            Require(p.Inventory.Contains(1072031,5));CareerPortal(p,1002);
        }
                if(p.Entity.Class%10==2 && !p.Inventory.Contains(1080001,1)){
                    p.BindWorldMap(1000);Feature("DailyHuntDrops").GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>0));
                    var hill=p.Map.Entities.Values.First(m=>m.MonsterInfo!=null && m.MonsterInfo.ID==15 && !m.Dead);EliminationHit(p,hill);
                    var drop=p.Map.FloorItems.Values.Single(d=>d.ItemID==1080001 && d.OwnerUID==p.Entity.UID);
                    p.Entity.X=drop.X;p.Entity.Y=drop.Y;var loot=new FloorItem(true){UID=drop.UID,Type=FloorItem.Remove}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,loot.Length-8,loot);FloorItem.Process(loot,p);
                    Require(p.Inventory.ContainsUID(drop.Item.UID));p.BindWorldMap(1002);
                }
                if(p.Entity.Class%10==3 && !p.Inventory.Contains(1088001,1))CareerBuy(p,1088001);
                if(p.Entity.Class%10==4 && !p.Inventory.Contains(721090,1)){
                    p.BindWorldMap(1002);var moon=Feature("MoonBoxQuest");int tactic=0;
                    moon.GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>max==7?tactic:0));
                    HeartTalk(p,600050,1);
                    for(int i=0;i<6;i++){
                        tactic=i;
                        if((bool)Sql("SELECT tokens[@index]>0 FROM revora_moon_runs WHERE uid=@uid","index",i+1,"uid",(long)CareerUid))continue;
                        if(p.Entity.MapID==1042)HeartTalk(p,600003,1);Require(p.Entity.MapID==1043+i);
                        if(!p.Inventory.Contains(721010u+(uint)i,1)){
                            var mob=p.Map.Entities.Values.First(m=>m.MonsterInfo!=null && m.MonsterInfo.ID==6000+i && !m.Dead);EliminationHit(p,mob);Require(p.Inventory.Contains(721010u+(uint)i,1));
                        }
                        HeartTalk(p,600005u+(uint)i*2,1);Require(p.Entity.MapID==1042);
                    }
                    HeartTalk(p,600003,1);Require(p.Entity.MapID==1049);HeartTalk(p,600017,1);Require(p.Entity.MapID==1050);
                    HeartTalk(p,600018,1);Require(p.Entity.MapID==1002 && p.Inventory.Contains(721090,1));
                }

    }
    static void CareerPromotionSchools(bool reload){
        careerRitesFixture=true;combinedCollectionFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true,true);combinedCollectionFixture=false;
        SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);new CoatStorage().Login(p);new TitleStorage().Login(p);p.LoadItemStats();
        if((bool)Sql("SELECT to_regclass('revora_career_schools_probe') IS NULL")){
            Require(!reload && CareerSignSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_promotions_probe")));
            Sql("CREATE TABLE revora_career_schools_probe(step integer,snapshot text);INSERT INTO revora_career_schools_probe VALUES(0,@snapshot)","snapshot",CareerSignSnapshot(p));
        }
        Require(CareerSignSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_schools_probe")));
        int step=Convert.ToInt32(Sql("SELECT step FROM revora_career_schools_probe"));Require(step>=0 && step<=PromotionSchools.Length);
        if(!reload && step<PromotionSchools.Length){
            byte school=PromotionSchools[step];uint trainer=PromotionTrainers[step];if(p.Inventory.Count>25)CombinedStash(p);
            Require(p.Entity.Level==140);uint cp=p.Entity.ConquerPoints;
            HeartTalk(p,59558,3);HeartTalk(p,59558,6);HeartTalk(p,59558,7);Require(p.Entity.ConquerPoints==cp-2000 && p.Inventory.Contains(711083,1));
            cp=p.Entity.ConquerPoints;HeartTalk(p,59558,3);HeartTalk(p,59558,5);CareerPaidRequest(p,school);Require(p.Entity.Class==school && p.Entity.Level==15 && p.Entity.ConquerPoints==cp-Config.SerethReincarnationCp);
            CareerGrow(p,110);Require(p.Entity.Level==140);
            while(p.Entity.Class%10<5){CareerPromotionMaterials(p);p.BindWorldMap(1002);CareerPortal(p,1004);byte before=p.Entity.Class;HeartTalk(p,trainer,1);HeartTalk(p,trainer,trainer==51580?(byte)2:(byte)3);Require(p.Entity.Class==before+1);CareerPortal(p,1002);}
            Require(EntityTable.SaveEntity(p));p.Entity.MyAchievement.Send();step++;
            Sql("UPDATE revora_career_schools_probe SET step=@step,snapshot=@snapshot","step",step,"snapshot",CareerSignSnapshot(p));
        }
        Require(p.Entity.Level==140 && p.Entity.Reborn==2 && CombinedCount(p,"Garments")==200 && CombinedCount(p,"Mounts")==100);
        p.Entity.MyAchievement.Send();foreach(int id in PromotionCredits.Take(step).SelectMany(ids=>ids)){
            Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id AND source='class-promotion-v1'","uid",(long)CareerUid,"id",id)==1);
            int bit=(id/100-101)*32+id%100-1;Require((System.BitConverter.ToUInt32(p.Entity.MyAchievement.ToArray(),16+bit/32*4)&(1u<<(bit%32)))!=0);
        }
        if(step>0){uint trainer=PromotionTrainers[step-1];string before=CareerSignSnapshot(p);p.BindWorldMap(1002);CareerPortal(p,1004);HeartTalk(p,trainer,1);HeartTalk(p,trainer,trainer==51580?(byte)2:(byte)3);CareerPortal(p,1002);Require(CareerSignSnapshot(p)==before);}
        Require(CareerSignSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_schools_probe")));
        Console.WriteLine("[career-schools] completed="+step+" credits="+PromotionCredits.Take(step).Sum(ids=>ids.Length));
        Console.WriteLine("[career-process] career-schools-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career schools did not close.");
    }
