            var daily=Feature("DailyWorldBosses");var latest=Sql("SELECT max(planned) FROM revora_daily_boss_runs");DateTime previous=latest==DBNull.Value?DateTime.UtcNow:DateTime.SpecifyKind((DateTime)latest,DateTimeKind.Utc);
