    static void CareerPirate(bool reload){
        careerRitesFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true,1003,true);SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);p.LoadItemStats();
        if((bool)Sql("SELECT to_regclass('revora_career_pirate_probe') IS NULL")){
