        }
        if(reload)Require(CareerPirateSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_pirate_probe WHERE uid=@uid","uid",(long)CareerUid)));
        if(!reload && (long)Sql("SELECT count(*) FROM revora_pirate_awakenings WHERE uid=@uid","uid",(long)CareerUid)<2){
            CareerMakeRoom(p);CareerSchool(p,611);
            foreach(ushort family in new ushort[]{611,612}){
                byte slot=family==611?(byte)4:(byte)5;var equipped=p.Equipment.TryGetItem(slot);
                if(equipped!=null && equipped.ID/1000==(family==611?671u:670u))continue;
                uint type=ShopFile.Shops[5].Items.Distinct().Where(id=>id/1000==family).Select(id=>ConquerItemInformation.BaseInformations[id]).Where(i=>i.Level<=70 && i.GoldWorth>0).OrderByDescending(i=>i.MaxAttack).First().ID;
                var gear=p.Inventory.Objects.Concat(p.Equipment.GetItems()).Where(i=>i.ID==type).OrderBy(i=>i.UID).FirstOrDefault()??CareerSilverBuy(p,type);
                ItemHandler.EquipItem(new ItemUsage(true){UID=gear.UID,dwParam=slot,Action=ItemUsage.Mode.EquipItem},p);Require(p.Equipment.TryGetItem(slot).UID==gear.UID);
            }
            CareerMakeRoom(p);p.BindWorldMap(1004);HeartTalk(p,4272,150);Require(p.Entity.MapID==10271);
            Feature("PirateEpicStore").GetField("SearchDraw",Hidden).SetValue(null,(Func<int,int>)(max=>max==100?0:max-1));
            while((long)Sql("SELECT count(*) FROM revora_pirate_awakenings WHERE uid=@uid","uid",(long)CareerUid)<2){
                uint cp=p.Entity.ConquerPoints;NinjaAttempt(p,199590);Require(p.Entity.ConquerPoints==cp-27 && MonkCount(p,3307443)==1);
                HeartTalk(p,199590,20);Require(p.Entity.ConquerPoints==cp-27);
