                Require(MonkCount(p,3307449)==1);long before=(long)Sql("SELECT count(*) FROM revora_pirate_awakenings WHERE uid=@uid","uid",(long)CareerUid);
                HeartTalk(p,199590,0);HeartTalk(p,199590,3);HeartTalk(p,199590,20);HeartTalk(p,199590,20);
                Require(MonkCount(p,3307449)==0 && p.Entity.ConquerPoints==cp-27 && (long)Sql("SELECT count(*) FROM revora_pirate_awakenings WHERE uid=@uid","uid",(long)CareerUid)==before+1);
            }
            HeartTalk(p,199590,254);Require(p.Entity.MapID==1004);p.BindWorldMap(1002);Require(EntityTable.SaveEntity(p));
        }
        Require((long)Sql("SELECT count(*) FROM revora_pirate_awakenings WHERE uid=@uid","uid",(long)CareerUid)==2);
        foreach(byte slot in new byte[]{4,5}){
            var gear=p.Equipment.TryGetItem(slot);Require(gear!=null && gear.ID/1000==(slot==4?671u:670u));
            uint soulUid=Convert.ToUInt32(Sql("SELECT soul_uid FROM revora_pirate_awakenings WHERE uid=@uid AND weapon_uid=@weapon","uid",(long)CareerUid,"weapon",(long)gear.UID));
            var soul=p.Inventory.Objects.Single(i=>i.UID==soulUid);Require(soul.Bound && ConquerItemInformation.BaseInformations[soul.ID].PurificationLevel==7);
        }
        p.LoadItemStats();foreach(ushort family in new ushort[]{671,670})if(!reload && (!p.Proficiencies.ContainsKey(family) || p.Proficiencies[family].Level<12))CareerTrainMelee(p,family);
        bool done=new ushort[]{671,670}.All(f=>p.Proficiencies.ContainsKey(f) && p.Proficiencies[f].Level>=12);if(reload)Require(done);
        p.Entity.MyAchievement.GetType().GetMethod("Invalidate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p.Entity.MyAchievement,null);p.Entity.MyAchievement.Send();
        foreach(int id in CareerSpecialAchievements.Concat(CareerShopAchievements).Concat(new[]{10321,10323,10405,11214,11215,11223,11222}).Concat(done?new[]{11322,11323}:new int[0])){
