            int bit=(id/100-101)*32+id%100-1;Require((System.BitConverter.ToUInt32(p.Entity.MyAchievement.ToArray(),16+bit/32*4)&(1u<<(bit%32)))!=0);
        }
        string loaded=string.Join(",",p.Proficiencies.Values.OrderBy(v=>v.ID).Select(v=>v.ID+":"+v.Level+":"+v.PreviousLevel+":"+v.Experience));
        Require(loaded==Convert.ToString(Sql("SELECT string_agg(id::text||':'||level::text||':'||previouslevel::text||':'||experience::text,',' ORDER BY id) FROM profs WHERE entityid=@uid","uid",(long)CareerUid)));
        if(reload)Require(CareerPirateSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_pirate_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else Sql("UPDATE revora_career_pirate_probe SET snapshot=@snapshot WHERE uid=@uid","snapshot",CareerPirateSnapshot(p),"uid",(long)CareerUid);
        Console.WriteLine("[career-pirate] remaining="+(done?0:1));Console.WriteLine("[career-process] career-pirate-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career Pirate did not close.");
