        Require(TrojanProgress(p,"Stage")==14 && TrojanProgress(p,"Completed")==1 && TrojanProgress(p,"Energy")==90 && !p.Inventory.Objects.Any(i=>i.ID==3003340));
        Require((long)Sql("SELECT count(*) FROM revora_trojan_epic_energy WHERE uid=@uid","uid",(long)CareerUid)==90 && (long)Sql("SELECT count(*) FROM revora_trojan_epic_encounters WHERE uid=@uid AND state='victory'","uid",(long)CareerUid)==20);
        Require((long)Sql("SELECT count(*) FROM revora_trojan_epic_rewards WHERE uid=@uid","uid",(long)CareerUid)==1);
        p.Entity.MyAchievement.GetType().GetMethod("Invalidate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p.Entity.MyAchievement,null);p.Entity.MyAchievement.Send();
        foreach(int id in CareerShopAchievements.Concat(new[]{10321,10323,10405}))Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id","uid",(long)CareerUid,"id",id)==1);
        if(reload)Require(CareerTrojanSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_trojan_probe WHERE uid=@uid","uid",(long)CareerUid)));
