    static void CareerProficiencyRetry(bool reload){
        const uint uid=4294907002;proficiencyRetryFixture=true;nextUid=uid;
        bool fresh=(bool)Sql("SELECT to_regclass('revora_proficiency_retry_probe') IS NULL");
        if(fresh){Require(!reload);
            if((long)Sql("SELECT count(*) FROM entities WHERE uid=@uid","uid",(long)uid)==0)Player(Kernel.Maps[1002]);
            else Require((long)Sql("SELECT count(*) FROM entities WHERE uid=@uid AND name='ArenaProbe4001' AND level=100 AND class=15 AND NOT EXISTS(SELECT 1 FROM profs WHERE entityid=@uid) AND NOT EXISTS(SELECT 1 FROM items WHERE entityid=@uid)","uid",(long)uid)==1);
            Sql("CREATE TABLE revora_proficiency_retry_probe(uid bigint PRIMARY KEY,snapshot text);INSERT INTO revora_proficiency_retry_probe(uid) VALUES(@uid)","uid",(long)uid);}
        nextUid=uid;var p=Player(Kernel.Maps[1002],true);SkillTable.LoadProficiencies(p);
        if(!reload){
            Require((long)Sql("SELECT count(*) FROM profs WHERE entityid=@uid","uid",(long)uid)==0);
            var first=new Proficiency(true){ID=420,Level=2,PreviousLevel=0,Experience=11};
            var second=new Proficiency(true){ID=410,Level=3,PreviousLevel=1,Experience=17};
            p.AddProficiency(first);p.AddProficiency(second);
            Sql("ALTER TABLE profs ADD CONSTRAINT career_proficiency_reject CHECK(entityid<>4294907002 OR id<>410) NOT VALID");
            bool failed=false;try{SkillTable.SaveProficiencies(p);}catch(Npgsql.PostgresException ex){if(ex.SqlState!="23514")throw;failed=true;}
            finally{Sql("ALTER TABLE profs DROP CONSTRAINT career_proficiency_reject");}
            Require(failed && !first.Available && !second.Available && (long)Sql("SELECT count(*) FROM profs WHERE entityid=@uid","uid",(long)uid)==0);
            SkillTable.SaveProficiencies(p);Require(first.Available && second.Available);
            Require((long)Sql("SELECT count(*) FROM profs WHERE entityid=@uid AND ((id=420 AND level=2 AND previouslevel=0 AND experience=11) OR (id=410 AND level=3 AND previouslevel=1 AND experience=17))","uid",(long)uid)==2);
            first.Level=4;first.Experience=23;second.Level=5;second.Experience=29;SkillTable.SaveProficiencies(p);
            string before=Convert.ToString(Sql("SELECT json_agg(r ORDER BY id)::text FROM profs r WHERE entityid=@uid","uid",(long)uid));SkillTable.SaveProficiencies(p);
            Require(before==Convert.ToString(Sql("SELECT json_agg(r ORDER BY id)::text FROM profs r WHERE entityid=@uid","uid",(long)uid)));
            Sql("UPDATE revora_proficiency_retry_probe SET snapshot=@snapshot WHERE uid=@uid","snapshot",before,"uid",(long)uid);
        }
        SkillTable.LoadProficiencies(p);Require(p.Proficiencies.Count==2 && p.Proficiencies[420].Level==4 && p.Proficiencies[420].PreviousLevel==0 && p.Proficiencies[420].Experience==23 && p.Proficiencies[410].Level==5 && p.Proficiencies[410].PreviousLevel==1 && p.Proficiencies[410].Experience==29);
        Require(Convert.ToString(Sql("SELECT json_agg(r ORDER BY id)::text FROM profs r WHERE entityid=@uid","uid",(long)uid))==Convert.ToString(Sql("SELECT snapshot FROM revora_proficiency_retry_probe WHERE uid=@uid","uid",(long)uid)));
        Console.WriteLine("[career-process] career-prof-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Proficiency retry did not close.");
    }
