    static void CareerMakeRoom(GameState p){
        if(p.Inventory.Count<35)return;
        foreach(var item in p.Inventory.Objects.Where(i=>i.Days==0 && (CareerShopFamilies.Contains((ushort)(i.ID/1000)) || CareerSpecialFamilies.Contains((ushort)(i.ID/1000)) && CareerSpecialDone(p,(ushort)(i.ID/1000)))).ToArray()){
            if(p.Inventory.Count<=30)break;
            var slot=p.Warehouses.First(w=>(uint)w.Key==8);Require(slot.Value.Count<slot.Value.MaxCount && item.Days==0);
            var npc=Kernel.Maps[1002].Npcs[8];p.Entity.Teleport(1002,(ushort)(npc.X-1),npc.Y);
            var packet=new byte[172];Revora.Network.Writer.WriteUInt16(164,0,packet);Revora.Network.Writer.WriteUInt16(1102,2,packet);
            Revora.Network.Writer.WriteUInt32(8,4,packet);packet[12]=1;packet[13]=10;Revora.Network.Writer.WriteUInt32(item.UID,18,packet);
            Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,164,packet);Warehouse.Process(packet,p);
            Require(!p.Inventory.ContainsUID(item.UID) && slot.Value.Objects.Any(i=>i.UID==item.UID));
        }
        Require(p.Inventory.Count<=30);p.BindWorldMap(1002);
    }
