            p.BindWorldMap(1002);
            if(!p.Inventory.Contains(711083,1)){uint before=p.Entity.ConquerPoints;HeartTalk(p,59558,3);HeartTalk(p,59558,6);HeartTalk(p,59558,7);Require(p.Entity.ConquerPoints==before-2000 && p.Inventory.Contains(711083,1));}
            uint cp=p.Entity.ConquerPoints;HeartTalk(p,59558,3);HeartTalk(p,59558,5);CareerPaidRequest(p,school);Require(p.Entity.Class==school && p.Entity.Level==15 && p.Entity.ConquerPoints==cp-Config.SerethReincarnationCp);
