                Require(p.Proficiencies.ContainsKey(family) && (p.Proficiencies[family].Level>oldLevel || p.Proficiencies[family].Experience>oldXp));
                if(!CareerSpecialDone(p,family))break;
            }
            if(reload)Require(CareerSpecialDone(p,family));
        }
        p.Entity.MyAchievement.GetType().GetMethod("Invalidate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p.Entity.MyAchievement,null);p.Entity.MyAchievement.Send();
        foreach(int id in CareerSpecialAchievements.Where((id,index)=>CareerSpecialDone(p,CareerSpecialFamilies[index])).Concat(CareerShopAchievements).Concat(new[]{10321,10323,10405,11214})){
