    static void CareerTrainMelee(GameState p,ushort family,byte targetLevel=12,uint attackType=Attack.Melee){
            int shots=0;var until=DateTime.UtcNow.AddSeconds(100);
            var targets=Kernel.Maps.Values.SelectMany(m=>m.Entities.Values).Where(e=>!e.Dead && e.MonsterInfo!=null && !e.MonsterInfo.Boss && !e.MonsterInfo.Guard && !e.MonsterInfo.Reviver && !e.Companion && e.Defence<p.Entity.MaxAttack/2).OrderByDescending(e=>e.Hitpoints).Take(128).ToArray();
            foreach(var target in targets){
                p.BindWorldMap(target.MapID);p.Entity.X=target.X;p.Entity.Y=target.Y;p.Screen.Add(target);int stalled=0;
                while(!target.Dead && !p.Entity.Dead && DateTime.UtcNow<until && shots<2000000){
                    if(p.Proficiencies.ContainsKey(family) && p.Proficiencies[family].Level>=targetLevel)break;
                    uint hp=target.Hitpoints;p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);
                    Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=target.UID,X=target.X,Y=target.Y,AttackType=attackType},p);shots++;
                    if(target.Hitpoints==hp)stalled++;else stalled=0;
                    if(stalled>=32){
                        if(shots<=96){Entity visible;bool found=p.Screen.TryGetValue(target.UID,out visible);Console.WriteLine("[career-weapons-stall] family="+family+" map="+target.MapID+" target="+target.UID+" cached="+found+" same="+ReferenceEquals(visible,target)+" attack="+p.Entity.MaxAttack+" hp="+target.Hitpoints);}
                        break;
                    }
                }
                if(p.Entity.Dead || DateTime.UtcNow>=until || shots>=2000000 || p.Proficiencies.ContainsKey(family) && p.Proficiencies[family].Level>=targetLevel)break;
            }
            SkillTable.SaveProficiencies(p);p.BindWorldMap(1002);Require(EntityTable.SaveEntity(p));
            Console.WriteLine("[career-weapons] family="+family+" shots="+shots+" level="+(p.Proficiencies.ContainsKey(family)?p.Proficiencies[family].Level:0)+" xp="+(p.Proficiencies.ContainsKey(family)?p.Proficiencies[family].Experience:0));
    }
