            Sql("CREATE TABLE revora_career_switch_probe(uid bigint PRIMARY KEY,snapshot text);INSERT INTO revora_career_switch_probe(uid) VALUES(@uid)","uid",(long)CareerUid);
        }
        if(reload)Require(CareerPaidSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_switch_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else if((long)Sql("SELECT count(*) FROM revora_reincarnations WHERE uid=@uid","uid",(long)CareerUid)==1){
            Require(p.Entity.Class==41 && p.Proficiencies[500].Level==12);
            if(!p.Inventory.Contains(711083,1)){
                uint before=p.Entity.ConquerPoints;HeartTalk(p,59558,3);HeartTalk(p,59558,6);HeartTalk(p,59558,7);
                Require(p.Entity.ConquerPoints==before-2000 && p.Inventory.Contains(711083,1));
            }
            uint cp=p.Entity.ConquerPoints;HeartTalk(p,59558,3);HeartTalk(p,59558,5);CareerPaidRequest(p,11);
            Require(p.Entity.ConquerPoints==cp-Config.SerethReincarnationCp && p.Entity.Level==15);
        }
        Require(p.Entity.Reborn==2 && p.Entity.Class==11 && p.Entity.FirstRebornClass==21 && p.Entity.FirstRebornLevel==112 && p.Entity.SecondRebornClass==41 && p.Entity.SecondRebornLevel>=112);
        Require(p.Proficiencies[500].Level==0 && p.Proficiencies[500].PreviousLevel==12);
        Require((long)Sql("SELECT count(*) FROM revora_reincarnations WHERE uid=@uid","uid",(long)CareerUid)==2);
        if(!reload && p.Entity.Level<110)CareerGrow(p,110);
        Require(p.Entity.Level>=112 && (long)Sql("SELECT count(*) FROM revora_reincarnations WHERE uid=@uid AND recovered_at IS NOT NULL","uid",(long)CareerUid)==2);
        Require((long)Sql("SELECT count(*) FROM reincarnation WHERE uid=@uid","uid",(long)CareerUid)==0);
        p.Entity.MyAchievement.GetType().GetMethod("Invalidate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p.Entity.MyAchievement,null);p.Entity.MyAchievement.Send();
        int bit=(10405/100-101)*32+10405%100-1;Require((System.BitConverter.ToUInt32(p.Entity.MyAchievement.ToArray(),16+bit/32*4)&(1u<<(bit%32)))!=0);
        Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=10405","uid",(long)CareerUid)==1);
        Require((long)Sql("SELECT count(*) FROM revora_oblivion_purchases WHERE uid=@uid","uid",(long)CareerUid)==2);
        uint soul=Convert.ToUInt32(Sql("SELECT soul_uid FROM revora_second_rebirths WHERE uid=@uid","uid",(long)CareerUid));Require(p.Inventory.Objects.Any(i=>i.UID==soul && i.Bound));
        string snapshot=CareerPaidSnapshot(p);CareerPaidRequest(p,11);lock(p.ItemSyncRoot)Call(Feature("ReincarnationRecovery"),"RestoreReady",p);Require(CareerPaidSnapshot(p)==snapshot);
        if(reload)Require(snapshot==Convert.ToString(Sql("SELECT snapshot FROM revora_career_switch_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else Sql("UPDATE revora_career_switch_probe SET snapshot=@snapshot WHERE uid=@uid","snapshot",snapshot,"uid",(long)CareerUid);
        Console.WriteLine("[career-process] career-switch-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career switch did not close.");
    }
    static ConquerItem CareerSilverBuy(GameState p,uint type,uint shopId=5){
        var map=Kernel.Maps.Values.Single(m=>m.Npcs.ContainsKey(shopId));p.BindWorldMap(map.ID);var shop=map.Npcs[shopId];p.Entity.X=shop.X;p.Entity.Y=(ushort)(shop.Y+2);
        ulong before=p.Entity.Money;uint price=ConquerItemInformation.BaseInformations[type].GoldWorth;Require(price>0);
        var buy=new ItemUsage(true){UID=shopId,dwParam=type,dwExtraInfo=1,Action=ItemUsage.Mode.BuyFromNPC}.ToArray();
        Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,buy.Length-8,buy);ItemUsage.Process(buy,p);
        Require(p.Entity.Money==before-price);return p.Inventory.Objects.Single(i=>i.ID==type);
    }
