    static void CareerGrow(GameState p,byte target){
        DateTime now=DateTime.Now;var day=Sql("SELECT day FROM revora_exp_ball_days WHERE uid=@uid","uid",(long)CareerUid);
        if(day!=null && day!=DBNull.Value){int value=Convert.ToInt32(day);var prior=new DateTime(value/10000,value/100%100,value%100);if(prior.Date>=now.Date)now=prior.AddDays(1);}
        Feature("ExperienceConsumables").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
        int used=0;p.BindWorldMap(1002);
        while(p.Entity.Level<target && used<500){
            if(used>0 && used%10==0)now=now.AddDays(1);
            var ball=p.Inventory.Objects.FirstOrDefault(i=>i.ID==723700);if(ball==null){CareerBuy(p,723700);ball=p.Inventory.Objects.First(i=>i.ID==723700);}
            byte level=p.Entity.Level;ulong xp=p.Entity.Experience;ItemHandler.UseItem(ball,p);
            Require(!p.Inventory.ContainsUID(ball.UID) && (p.Entity.Level>level || p.Entity.Experience>xp));used++;
        }
        Require(p.Entity.Level>=target);Console.WriteLine("[career-growth] purchased-exp-balls="+used+" level="+p.Entity.Level);
    }
    static void CareerPaidRecovery(bool reload){
        careerRitesFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true);SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);p.LoadItemStats();
        if((bool)Sql("SELECT to_regclass('revora_career_recovery_probe') IS NULL")){
