        Require((long)Sql("SELECT count(*) FROM reincarnation WHERE uid=@uid","uid",(long)CareerUid)==0);
        uint soul=Convert.ToUInt32(Sql("SELECT soul_uid FROM revora_second_rebirths WHERE uid=@uid","uid",(long)CareerUid));Require(p.Inventory.Objects.Any(i=>i.UID==soul && i.Bound));
        string snapshot=CareerPaidSnapshot(p);lock(p.ItemSyncRoot)Call(Feature("ReincarnationRecovery"),"RestoreReady",p);CareerPaidRequest(p);Require(CareerPaidSnapshot(p)==snapshot);
        if(reload)Require(snapshot==Convert.ToString(Sql("SELECT snapshot FROM revora_career_recovery_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else Sql("UPDATE revora_career_recovery_probe SET snapshot=@snapshot WHERE uid=@uid","snapshot",snapshot,"uid",(long)CareerUid);
        Console.WriteLine("[career-process] career-recovery-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career recovery did not close.");
    }
