        else if((long)Sql("SELECT count(*) FROM revora_reincarnations WHERE uid=@uid","uid",(long)CareerUid)==0){
            Require(p.Entity.Reborn==2 && p.Entity.Class==21 && p.Entity.SecondRebornLevel==122);
            lock(p.ItemSyncRoot)Require(Call(Feature("SecondRebirthRecovery"),"Snapshot",p)==null);
            CareerGrow(p,112);
