                uint before=p.Entity.ConquerPoints;HeartTalk(p,59558,3);HeartTalk(p,59558,6);HeartTalk(p,59558,7);
                Require(p.Entity.ConquerPoints==before-2000 && p.Inventory.Contains(711083,1));
