        }
        Require(p.Entity.Reborn==2 && p.Entity.Class==41 && p.Entity.Level==15 && p.Entity.FirstRebornClass==15 && p.Entity.FirstRebornLevel==122 && p.Entity.SecondRebornClass==21 && p.Entity.SecondRebornLevel>=112);
        Require((long)Sql("SELECT count(*) FROM revora_reincarnations WHERE uid=@uid AND new_class=41 AND recovered_at IS NULL AND cost=@cost AND balance_after=balance_before-cost","uid",(long)CareerUid,"cost",(long)Config.SerethReincarnationCp)==1);
        Require((long)Sql("SELECT count(*) FROM reincarnation WHERE uid=@uid","uid",(long)CareerUid)==1);
        Require((long)Sql("SELECT count(*) FROM revora_oblivion_purchases WHERE uid=@uid AND cost=2000","uid",(long)CareerUid)==1 && !p.Inventory.Contains(711083,1));
        uint soul=Convert.ToUInt32(Sql("SELECT soul_uid FROM revora_second_rebirths WHERE uid=@uid","uid",(long)CareerUid));Require(p.Inventory.Objects.Any(i=>i.UID==soul && i.Bound));
        string snapshot=CareerPaidSnapshot(p);CareerPaidRequest(p);Require(CareerPaidSnapshot(p)==snapshot);
        if(reload)Require(snapshot==Convert.ToString(Sql("SELECT snapshot FROM revora_career_paid_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else Sql("UPDATE revora_career_paid_probe SET snapshot=@snapshot WHERE uid=@uid","snapshot",snapshot,"uid",(long)CareerUid);
        Console.WriteLine("[career-process] career-paid-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career paid rite did not close.");
    }
    static void CareerPaidRequest(GameState p,byte next=41){
        var packet=new byte[21];Revora.Network.Writer.WriteUInt16(13,0,packet);Revora.Network.Writer.WriteUInt16(1066,2,packet);
        packet[8]=next;packet[12]=(byte)(p.Entity.Body%1000);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,13,packet);Reincarnation.Process(packet,p);
    }
    static long CareerAbyssState(string column){return Convert.ToInt64(Sql("SELECT CASE @column WHEN 'stage' THEN stage WHEN 'meters' THEN meters WHEN 'spirits' THEN spirits WHEN 'forms' THEN forms ELSE NULL END FROM revora_abyss_trials WHERE uid=@uid","column",column,"uid",(long)CareerUid));}
    static int CareerAbyssAmount(GameState p,uint type){return p.Inventory.Objects.Where(i=>i.ID==type).Sum(i=>Math.Max(1,(int)i.StackSize));}
    static void CareerAbyssWild(GameState p,bool lord,int roll){
        var world=Feature("AbyssTrialWorld");world.GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>roll));
        Func<Entity,bool> match=m=>m.MonsterInfo!=null && m.MonsterInfo.ID>=3600 && m.MonsterInfo.ID<=3631 && (!lord || m.MonsterInfo.ID==3603) && !m.Dead;
        var mob=p.Map.Entities.Values.FirstOrDefault(match);
        if(mob==null){Call(typeof(Map),"_timerCallBack",p.Map,Time32.Now.AddSeconds(86400).TotalMilliseconds);mob=p.Map.Entities.Values.FirstOrDefault(match);}
        Require(mob!=null);EliminationHit(p,mob);
    }
    static void CareerAbyssFight(GameState p,uint family){
        uint npc=family==3632?3605u:family==3633?3606u:family==3634?3607u:family==3635?3609u:family>=3644?3608u:new uint[]{3616,3618,3620,3622,3628,3630,3633,3635}[family-3636];
        bool active=(bool)Sql("SELECT EXISTS(SELECT 1 FROM revora_abyss_encounters e JOIN revora_abyss_trials r ON r.id=e.run WHERE r.uid=@uid AND e.family=@family AND defeated_at IS NULL)","uid",(long)CareerUid,"family",(int)family);
        if(active)HeartTalk(p,npc,2);else{HeartTalk(p,npc,1);HeartTalk(p,npc,20);}
        var bodies=p.Map.Entities.Values.Where(m=>m.MonsterInfo!=null && m.MonsterInfo.ID==9920000+family).ToArray();
        if(bodies.Length!=1)Console.WriteLine("[career-abyss] summon-family="+family+" bodies="+bodies.Length+" active="+Sql("SELECT count(*) FROM revora_abyss_encounters e JOIN revora_abyss_trials r ON r.id=e.run WHERE r.uid=@uid AND defeated_at IS NULL","uid",(long)CareerUid)+" bag="+p.Inventory.Count+" map="+p.Entity.MapID);
        var body=bodies.Single();
        EliminationHit(p,body);Require(!p.Map.Entities.ContainsKey(body.UID));
    }
    static void CareerAbyssCraft(GameState p,uint output){
        if(output>=722723 && output<=722725){int before=CareerAbyssAmount(p,output);CareerAbyssWild(p,false,output==722723?0:output==722724?16:33);Require(CareerAbyssAmount(p,output)==before+1);return;}
        uint family=output==722722?3632u:output==722726?3633u:output==722729?3634u:output==722731?3635u:0;
        var costs=(Array)Call(Feature("AbyssTrialRules"),family==0?"ExchangeCost":"SummonCost",family==0?output:family);
        // Craft nested offerings first: those recipes consume the same base materials.
        foreach(object cost in costs.Cast<object>().OrderBy(c=>{uint id=(uint)c.GetType().GetField("Type",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(c);return id>=722723 && id<=722725?1:0;})){uint type=(uint)cost.GetType().GetField("Type",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(cost);int count=(ushort)cost.GetType().GetField("Count",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(cost);
            while(CareerAbyssAmount(p,type)<count)CareerAbyssCraft(p,type);
        }
        int beforeOutput=CareerAbyssAmount(p,output);
        if(family==0){byte option=output==722721?(byte)1:output==722728?(byte)2:(byte)3;HeartTalk(p,3601,option);HeartTalk(p,3601,20);}else CareerAbyssFight(p,family);
        Require(CareerAbyssAmount(p,output)==beforeOutput+1);
    }
