    static void CareerSecondRite(bool reload){
        careerRitesFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true);SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);p.LoadItemStats();
        if((bool)Sql("SELECT to_regclass('revora_career_second_probe') IS NULL")){
            Require(!reload && CareerPrepSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_prepare_probe WHERE uid=@uid","uid",(long)CareerUid)));
            Sql("CREATE TABLE revora_career_second_probe(uid bigint PRIMARY KEY,snapshot text);INSERT INTO revora_career_second_probe(uid) VALUES(@uid)","uid",(long)CareerUid);
        }
        if(reload)Require(CareerSecondSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_second_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else if(p.Entity.Reborn==1){
            p.BindWorldMap(1002);HeartTalk(p,59558,181);HeartTalk(p,59558,182);Require(p.Entity.MapID==1700);
            if(CareerAbyssState("stage")==1){
                while(CareerAbyssAmount(p,722731)<3){CareerAbyssCraft(p,722731);Console.WriteLine("[career-abyss] pure-vigors="+CareerAbyssAmount(p,722731));}
                HeartTalk(p,3601,4);HeartTalk(p,3601,20);Require(CareerAbyssState("stage")==2);
            }
            if(CareerAbyssState("stage")==2){
                HeartTalk(p,3602,1);while(CareerAbyssState("meters")<40000)CareerAbyssWild(p,true,99);
                HeartTalk(p,3602,2);Require(CareerAbyssState("stage")==3);Console.WriteLine("[career-abyss] grievance-complete");
            }
            if(CareerAbyssState("stage")==3){
                HeartTalk(p,3603,1);while(CareerAbyssState("spirits")<72)CareerAbyssFight(p,3636u+(uint)(CareerAbyssState("spirits")%8));
                HeartTalk(p,3603,2);Require(CareerAbyssState("stage")==4);Console.WriteLine("[career-abyss] spirits-complete");
            }
            if(CareerAbyssState("stage")==4){
                if(CareerAbyssState("forms")==0 && CareerAbyssAmount(p,722727)==0)CareerAbyssWild(p,true,0);
                while(CareerAbyssState("stage")==4)CareerAbyssFight(p,3644u+(uint)CareerAbyssState("forms"));
            }
            HeartTalk(p,3601,9);Require(CareerAbyssState("stage")==5);HeartTalk(p,3604,1);Require(p.Entity.MapID==1002);
            Require(!p.Inventory.Contains(723701,1));foreach(byte option in new byte[]{2,171,180})HeartTalk(p,59558,option);
        }
        Require(p.Entity.Reborn==2 && p.Entity.Level==15 && p.Entity.Class==21 && p.Entity.FirstRebornClass==15 && p.Entity.FirstRebornLevel==124 && p.Entity.SecondRebornClass==15);
        Require((long)Sql("SELECT count(*) FROM revora_second_rebirths WHERE uid=@uid AND payment_kind='abyss-quest' AND token_uid=0","uid",(long)CareerUid)==1);
        Require((bool)Sql("SELECT consumed_at IS NOT NULL FROM revora_abyss_trials WHERE uid=@uid","uid",(long)CareerUid));
        uint soul=Convert.ToUInt32(Sql("SELECT soul_uid FROM revora_second_rebirths WHERE uid=@uid","uid",(long)CareerUid));
        Require(p.Inventory.Objects.Any(i=>i.UID==soul && i.Bound && i.Days==0 && ConquerItemInformation.BaseInformations[i.ID].PurificationLevel==7));
        foreach(int material in new[]{722723,722724,722725})Require((long)Sql("SELECT sum(m.consumed) FROM revora_abyss_materials m JOIN revora_abyss_operations o ON o.id=m.operation JOIN revora_abyss_trials r ON r.id=o.run WHERE r.uid=@uid AND m.item_type=@type","uid",(long)CareerUid,"type",material)==117);
        Require((long)Sql("SELECT count(*) FROM revora_abyss_encounters e JOIN revora_abyss_trials r ON r.id=e.run WHERE r.uid=@uid AND e.defeated_at IS NOT NULL","uid",(long)CareerUid)==195);
        Require((long)Sql("SELECT count(*) FROM revora_abyss_deaths d JOIN revora_abyss_trials r ON r.id=d.run WHERE r.uid=@uid","uid",(long)CareerUid)==432);
        Require((long)Sql("SELECT count(*) FROM revora_abyss_rewards e JOIN revora_abyss_trials r ON r.id=e.run WHERE r.uid=@uid AND e.claimed_at IS NULL","uid",(long)CareerUid)==0);
        p.Entity.MyAchievement.GetType().GetMethod("Invalidate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p.Entity.MyAchievement,null);p.Entity.MyAchievement.Send();
        foreach(int id in new[]{10315,11030,10316,11031}){int bit=(id/100-101)*32+id%100-1;Require((System.BitConverter.ToUInt32(p.Entity.MyAchievement.ToArray(),16+bit/32*4)&(1u<<(bit%32)))!=0);}
        string snapshot=CareerSecondSnapshot(p);HeartTalk(p,59558,180);Require(CareerSecondSnapshot(p)==snapshot);
        if(reload)Require(snapshot==Convert.ToString(Sql("SELECT snapshot FROM revora_career_second_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else Sql("UPDATE revora_career_second_probe SET snapshot=@snapshot WHERE uid=@uid","snapshot",snapshot,"uid",(long)CareerUid);
        Console.WriteLine("[career-process] career-second-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career second rite did not close.");
    }
    static void CareerBuy(GameState p,uint type){
        uint cp=p.Entity.ConquerPoints,price=ConquerItemInformation.BaseInformations[type].ConquerPointsWorth;Require(price>0);
        var buy=new ItemUsage(true){UID=2888,dwParam=type,dwExtraInfo=1,Action=ItemUsage.Mode.BuyFromNPC}.ToArray();
        Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,buy.Length-8,buy);ItemUsage.Process(buy,p);Require(p.Entity.ConquerPoints==cp-price);
    }
