    static void CareerSecondPreparation(bool reload){
        careerRitesFixture=true;nextUid=CareerUid;var p=Player(Kernel.Maps[1002],true);SkillTable.LoadSpells(p);SkillTable.LoadProficiencies(p);p.LoadItemStats();
        Require(p.Entity.Reborn==1);
        if((bool)Sql("SELECT to_regclass('revora_career_prepare_probe') IS NULL")){
            Require(!reload && CareerRiteSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_rites_probe WHERE uid=@uid","uid",(long)CareerUid)));
            Sql("CREATE TABLE revora_career_prepare_probe(uid bigint PRIMARY KEY,balls integer NOT NULL DEFAULT 0,snapshot text);INSERT INTO revora_career_prepare_probe(uid) VALUES(@uid)","uid",(long)CareerUid);
        }
        if(reload)Require(CareerPrepSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_prepare_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else{
            DateTime now=DateTime.Now;var day=Sql("SELECT day FROM revora_exp_ball_days WHERE uid=@uid","uid",(long)CareerUid);
            if(day!=null && day!=DBNull.Value){int value=Convert.ToInt32(day);var prior=new DateTime(value/10000,value/100%100,value%100);if(prior.Date>=now.Date)now=prior.AddDays(1);}
            Feature("ExperienceConsumables").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
            int used=0;p.BindWorldMap(1002);
            while(p.Entity.Level<120 && used<500){
                if(used>0 && used%10==0)now=now.AddDays(1);
                var ball=p.Inventory.Objects.FirstOrDefault(i=>i.ID==723700);if(ball==null){CareerBuy(p,723700);ball=p.Inventory.Objects.First(i=>i.ID==723700);}
                byte level=p.Entity.Level;ulong xp=p.Entity.Experience;ItemHandler.UseItem(ball,p);
                Require(!p.Inventory.ContainsUID(ball.UID) && (p.Entity.Level>level || p.Entity.Experience>xp));used++;
                Sql("UPDATE revora_career_prepare_probe SET balls=balls+1 WHERE uid=@uid","uid",(long)CareerUid);
            }
            Require(p.Entity.Level>=120);Console.WriteLine("[career-preparation] exp-balls="+used+" level="+p.Entity.Level);
            while(p.Entity.Class<15){
                if(p.Entity.Class==12 && !p.Inventory.Contains(1080001,1)){
                    p.BindWorldMap(1000);Feature("DailyHuntDrops").GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>0));
                    var hill=p.Map.Entities.Values.First(m=>m.MonsterInfo!=null && m.MonsterInfo.ID==15 && !m.Dead);EliminationHit(p,hill);
                    var drop=p.Map.FloorItems.Values.Single(d=>d.ItemID==1080001 && d.OwnerUID==p.Entity.UID);
                    p.Entity.X=drop.X;p.Entity.Y=drop.Y;var loot=new FloorItem(true){UID=drop.UID,Type=FloorItem.Remove}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,loot.Length-8,loot);FloorItem.Process(loot,p);
                    Require(p.Inventory.ContainsUID(drop.Item.UID));p.BindWorldMap(1002);
                }
                if(p.Entity.Class==13 && !p.Inventory.Contains(1088001,1))CareerBuy(p,1088001);
                if(p.Entity.Class==14 && !p.Inventory.Contains(721090,1)){
                    p.BindWorldMap(1002);var moon=Feature("MoonBoxQuest");int tactic=0;
                    moon.GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>max==7?tactic:0));
                    HeartTalk(p,600050,1);
                    for(int i=0;i<6;i++){
                        tactic=i;
                        if((bool)Sql("SELECT tokens[@index]>0 FROM revora_moon_runs WHERE uid=@uid","index",i+1,"uid",(long)CareerUid))continue;
                        if(p.Entity.MapID==1042)HeartTalk(p,600003,1);Require(p.Entity.MapID==1043+i);
                        if(!p.Inventory.Contains(721010u+(uint)i,1)){
                            var mob=p.Map.Entities.Values.First(m=>m.MonsterInfo!=null && m.MonsterInfo.ID==6000+i && !m.Dead);EliminationHit(p,mob);Require(p.Inventory.Contains(721010u+(uint)i,1));
                        }
                        HeartTalk(p,600005u+(uint)i*2,1);Require(p.Entity.MapID==1042);
                    }
                    HeartTalk(p,600003,1);Require(p.Entity.MapID==1049);HeartTalk(p,600017,1);Require(p.Entity.MapID==1050);
                    HeartTalk(p,600018,1);Require(p.Entity.MapID==1002 && p.Inventory.Contains(721090,1));
                }
                p.BindWorldMap(1002);CareerPortal(p,1004);byte before=p.Entity.Class;
                HeartTalk(p,10022,1);HeartTalk(p,10022,3);Require(p.Entity.Class==before+1);
                CareerPortal(p,1002);
            }
        }
        Require(p.Entity.Level>=120 && p.Entity.Class==15 && p.Entity.Reborn==1 && p.Entity.FirstRebornClass==15 && p.Entity.FirstRebornLevel==124);
        p.Entity.MyAchievement.GetType().GetMethod("Invalidate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p.Entity.MyAchievement,null);p.Entity.MyAchievement.Send();
        foreach(int id in new[]{10820,10821,10822,10823})Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id AND source='class-promotion-v1'","uid",(long)CareerUid,"id",id)==1);
        Require((bool)Sql("SELECT @now::jsonb->'rite'=snapshot::jsonb->'rite' FROM revora_career_rites_probe WHERE uid=@uid","now",CareerRiteSnapshot(p),"uid",(long)CareerUid));
        if(reload)Require(CareerPrepSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_prepare_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else Sql("UPDATE revora_career_prepare_probe SET snapshot=@snapshot WHERE uid=@uid","snapshot",CareerPrepSnapshot(p),"uid",(long)CareerUid);
        Console.WriteLine("[career-process] career-prepare-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career preparation did not close.");
    }
