        if(reload)Require(CareerRiteSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_career_rites_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else if(p.Entity.Reborn==0){
            if((long)Sql("SELECT count(*) FROM revora_daily_boss_runs WHERE killer=@uid AND paid","uid",(long)CareerUid)==0){
                p.Entity.Level=120;Require(EntityTable.SaveEntity(p));
                var daily=Feature("DailyWorldBosses");DateTime now=DateTime.UtcNow.AddDays(20);
                var latest=Sql("SELECT max(planned) FROM revora_daily_boss_runs");if(latest!=DBNull.Value && (DateTime)latest>now)now=DateTime.SpecifyKind((DateTime)latest,DateTimeKind.Utc).AddDays(1);
                now=now.ToLocalTime().Date.AddDays(1).ToUniversalTime();daily.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
                Call(daily,"Tick");now=DateTime.SpecifyKind((DateTime)Sql("SELECT min(planned) FROM revora_daily_boss_runs WHERE planned>=@now AND state=0","now",now),DateTimeKind.Utc).AddSeconds(1);
                Call(daily,"Tick");var active=daily.GetField("Active",Hidden).GetValue(null);Require(active!=null);
                var boss=(Entity)active.GetType().GetField("Entity",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(active);
                p.BindWorldMap(boss.MapID);EliminationHit(p,boss);p.BindWorldMap(1002);
            }
            if(!p.Inventory.Contains(721259,1)){
                var pick=p.Inventory.Objects.Concat(p.Equipment.GetItems()).SingleOrDefault(i=>i.ID==562000);
                if(pick==null){
                    var shop=p.Map.Npcs[1];p.Entity.X=shop.X;p.Entity.Y=(ushort)(shop.Y+2);ulong silver=p.Entity.Money;
                    var buy=new ItemUsage(true){UID=1,dwParam=562000,dwExtraInfo=1,Action=ItemUsage.Mode.BuyFromNPC}.ToArray();
                    Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,buy.Length-8,buy);ItemUsage.Process(buy,p);
                    pick=p.Inventory.Objects.Single(i=>i.ID==562000);Require(p.Entity.Money==silver-1000);
                }
                if(pick.Position!=4)ItemHandler.EquipItem(new ItemUsage(true){UID=pick.UID,dwParam=4,Action=ItemUsage.Mode.EquipItem},p);
                Require(p.Equipment.TryGetItem(4).UID==pick.UID);
                var mining=Feature("MiningRewards");DateTime now=DateTime.UtcNow.AddDays(2);int gem=0;
                mining.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
                mining.GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>max==10000?0:max==100?99:max==2 || max==3 || max==4?gem:0));
                foreach(int region in new[]{0,1,2}){
                    if(region==0)HeartTalk(p,10080,5);
                    else if(region==1){CareerPortal(p,1002);CareerPortal(p,1011);HeartTalk(p,125,1);}
                    else{CareerPortal(p,1011);CareerPortal(p,1020);HeartTalk(p,126,1);}
                    Require(p.Entity.MapID==(region==0?1028:region==1?1025:1026));
                    var start=new Data(true){ID=Data.SwingPickaxe,UID=p.Entity.UID}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,start.Length-8,start);Data.Process(start,p);
                    foreach(int index in region==0?new[]{0,1,2}:region==1?new[]{2,3}:new[]{0,1}){
                        uint type=region==0?700001u+(uint)index*10:region==1?700011u+(uint)index*10:700051u+(uint)index*10;
                        if(p.Inventory.Contains(type,1))continue;gem=index;now=now.AddSeconds(3);Revora.Game.ConquerStructures.Mining.Mine(p);Require(p.Inventory.Contains(type,1));
                    }
                }
                CareerPortal(p,1020);CareerPortal(p,1011);CareerPortal(p,1002);
                if(!p.Inventory.Contains(721258,1)){
                    HeartTalk(p,380,1);Require(p.Entity.MapID==1038);HeartTalk(p,9884,1);Require(p.Entity.MapID==1216);
                    HeartTalk(p,300655,1);Require(p.Entity.MapID==1210);AdventureIslandPortal(p,0,4,329);AdventureIslandPortal(p,0,3,400);Require(p.Entity.MapID==1212);
                    Feature("CleanWaterDrops").GetField("Roll",Hidden).SetValue(null,(Func<int,int>)(max=>0));
                    var lord=p.Map.Entities.Values.First(e=>e.MonsterInfo!=null && e.MonsterInfo.ID==8500 && !e.Dead);EliminationHit(p,lord);
                    var drop=p.Map.FloorItems.Values.Single(d=>d.ItemID==721258 && d.OwnerUID==p.Entity.UID);
                    p.Entity.X=drop.X;p.Entity.Y=drop.Y;var loot=new FloorItem(true){UID=drop.UID,Type=FloorItem.Remove}.ToArray();
                    Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,loot.Length-8,loot);FloorItem.Process(loot,p);Require(p.Inventory.ContainsUID(drop.Item.UID));
                    HeartTalk(p,300653,1);Require(p.Entity.MapID==1219);HeartTalk(p,300654,1);Require(p.Entity.MapID==1002);
                }
                HeartTalk(p,59558,38);HeartTalk(p,59558,39);Require(p.Inventory.Contains(721259,1));
            }
            foreach(byte option in new byte[]{1,200,210,212,214})HeartTalk(p,59558,option);
        }
        Require(p.Entity.Reborn==1 && p.Entity.Level==15 && p.Entity.FirstRebornClass==15 && p.Entity.FirstRebornLevel>=120);
        Require(!p.Inventory.Contains(721259,1) && p.Inventory.Objects.Any(i=>i.ID==187405 && !i.Bound && i.Days==0));
        Require((long)Sql("SELECT count(*) FROM revora_heavenly_stone_materials m JOIN revora_heavenly_stone_crafts c ON c.id=m.craft WHERE c.uid=@uid","uid",(long)CareerUid)==8);
        Require((long)Sql("SELECT yields FROM revora_mining_state WHERE uid=@uid","uid",(long)CareerUid)==7);
        p.Entity.MyAchievement.GetType().GetMethod("Invalidate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p.Entity.MyAchievement,null);p.Entity.MyAchievement.Send();
        foreach(int id in new[]{10315,11030}){int bit=(id/100-101)*32+id%100-1;Require((System.BitConverter.ToUInt32(p.Entity.MyAchievement.ToArray(),16+bit/32*4)&(1u<<(bit%32)))!=0);}
        string snapshot=CareerRiteSnapshot(p);HeartTalk(p,59558,39);HeartTalk(p,59558,214);Require(CareerRiteSnapshot(p)==snapshot);
        if(reload)Require(snapshot==Convert.ToString(Sql("SELECT snapshot FROM revora_career_rites_probe WHERE uid=@uid","uid",(long)CareerUid)));
        else Sql("UPDATE revora_career_rites_probe SET snapshot=@snapshot WHERE uid=@uid","snapshot",snapshot,"uid",(long)CareerUid);
        Console.WriteLine("[career-process] career-first-"+(reload?"reload":"earn")+"-passed");Server.CommandsAI("@close");throw new InvalidOperationException("Career first rite did not close.");
    }
